                currentMeaning: "", directContact: "", needsReview: false)
            let result = try XCTUnwrap(RuntimeFoundationInterpreter.validateIndexed(.init(items: [item,empty]), source: source,
                units: RuntimeIndexedSource(source), referenceDate: reference, calendar: calendar,
                rules: .init(items: [], method: .rules), context: .empty))
            XCTAssertEqual(result.items.count, 1); XCTAssertEqual(result.items[0].sourceQuote, source)
            XCTAssertFalse(result.items[0].needsReview)
        }
    }
