    func testSharedSentenceKeepsTwoIndependentFamilyRecipientsAndSeparateMemory() throws {
        if #available(iOS 26.4, *) {
            let text = "I need to ask my mom about the outdoor concert and my partner's mom about the weekend walk. They are two different people. The shelf measurement is 82 centimeters."
            let units = RuntimeIndexedSource(text)
            XCTAssertEqual(units.units.count, 3)
            let first = RuntimeFoundationInterpreter.IndexedItem(evidence: [0,1], anchor: "ask my mom about the outdoor concert", purpose: .task,
                currentMeaning: "Ask my mom about the outdoor concert.", directContact: "my mom", needsReview: false)
            let second = RuntimeFoundationInterpreter.IndexedItem(evidence: [0,1], anchor: "my partner's mom about the weekend walk", purpose: .task,
                currentMeaning: "Ask my partner's mom about the weekend walk.", directContact: "my partner's mom", needsReview: false)
            let memory = RuntimeFoundationInterpreter.IndexedItem(evidence: [2], purpose: .note,
                currentMeaning: "", directContact: "", needsReview: false)
            let result = try XCTUnwrap(RuntimeFoundationInterpreter.validateIndexed(.init(items: [first,second,memory]), source: text,
                units: units, referenceDate: reference, calendar: calendar, rules: .init(items: [],method: .rules), context: .empty))
