            var wrong = second; wrong.directContact = "my mom"
            XCTAssertNil(RuntimeFoundationInterpreter.validateIndexed(.init(items: [first,wrong,memory]), source: text,
                units: units, referenceDate: reference, calendar: calendar, rules: .init(items: [],method: .rules), context: .empty))
