    func testSharedOwnershipRejectsDuplicateOrUngroundedAnchorsAndMissingFinalUnit() {
        if #available(iOS 26.4, *) {
            let units = RuntimeIndexedSource("Ask Mom about the concert and Dad about the walk. They are different people. Keep the shelf size in Memory.")
            let a = RuntimeFoundationInterpreter.IndexedItem(evidence: [0,1], anchor: "Ask Mom about the concert", purpose: .task,
                currentMeaning: "Ask Mom about the concert", directContact: "Mom", needsReview: false)
            let b = RuntimeFoundationInterpreter.IndexedItem(evidence: [0,1], anchor: "Dad about the walk", purpose: .task,
                currentMeaning: "Ask Dad about the walk", directContact: "Dad", needsReview: false)
            let m = RuntimeFoundationInterpreter.IndexedItem(evidence: [2], purpose: .note,currentMeaning: "", directContact: "",needsReview: false)
            XCTAssertTrue(RuntimeFoundationInterpreter.validOwnership([a,b,m],units: units))
            XCTAssertFalse(RuntimeFoundationInterpreter.validOwnership([a,b],units: units))
