            XCTAssertFalse(RuntimeFoundationInterpreter.validOwnership([a,foreign,m],units: units))
            var noAnchor = b; noAnchor.anchor = ""
            XCTAssertFalse(RuntimeFoundationInterpreter.validOwnership([a,noAnchor,m],units: units))
        }
    }
