@MainActor
final class RuntimeBundledReferenceTests: XCTestCase {
    func testPurchasePurposeRanksCompatibleApprovedReferenceAheadOfPacking() async throws {
        var configuration = try XCTUnwrap(RuntimeExampleTestFixtures.reviewed)
        configuration.excludedBlueprints = ["shop_replace_quantity", "shop_allocation", "shop_add_quantity", "fam_purchase_allocation"]
        let rows = try await RuntimeExampleLibrary.shared.select(
            "Buy 8 tins of beans for my sister and 2 tins for Dad. Actually make my sister's allocation 5 tins; keep Dad's 2.",
            configuration: configuration)
        let first = try XCTUnwrap(rows.first)
        XCTAssertNotNil(first.input.utterance.range(of: #"(?i)^\s*(?:buy|purchase)\b"#, options: .regularExpression))
        XCTAssertTrue(rows.allSatisfy { configuration.excludedBlueprints.isDisjoint(with: $0.ruleIDs)
            && !configuration.excludedBlueprints.contains($0.provenance.blueprint) && $0.approval.production_eligible })
    }
    func testWorkedProjectionRetainsInputSolutionAndLifecycleContext() async throws {
        if #available(iOS 26.4, *) {
            var configuration = try XCTUnwrap(RuntimeExampleTestFixtures.reviewed)
            configuration.manualReferenceIDs = ["SIR1-480312"]
            let rows = try await RuntimeExampleLibrary.shared.select("saved change", configuration: configuration)
            let row = try XCTUnwrap(rows.first)
            let original = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(row.payload.utf8)) as? [String: Any])
            let projected = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(RuntimeFoundationInterpreter.projectedDemonstration(row).utf8)) as? [String: Any])
            XCTAssertEqual(projected["reference_id"] as? String, row.id)
            for key in ["input", "solution", "lifecycle_context"] {
                XCTAssertEqual(try JSONSerialization.data(withJSONObject: XCTUnwrap(projected[key]), options: [.sortedKeys]),
                               try JSONSerialization.data(withJSONObject: XCTUnwrap(original[key]), options: [.sortedKeys]), key)
            }
            XCTAssertNil(projected["review"]); XCTAssertNil(projected["provenance"])
        }
    }
    func testBuild21LoadsAndSearchesEntirePinnedDevelopmentBank() async throws {
        let configuration = try XCTUnwrap(RuntimeExampleConfiguration.bundled)
        XCTAssertTrue(configuration.allowProposed)
        XCTAssertTrue(configuration.retrievalEnabled)
        XCTAssertEqual(configuration.libraryURL.lastPathComponent, "runtime-library.sqlite")
        let store = try RuntimeReferenceStore(url: configuration.libraryURL,
            expectedSHA256: configuration.expectedSHA256, allowUnpinnedPrototype: false)
        XCTAssertEqual(store.recordCount, 510_000)
        XCTAssertEqual(store.approvedCount, 0, "Searching proposed examples must never approve them")
        for query in [
            "Pack my niece's cable pouch and my wife's seed envelope. We already own them; do not buy them.",
            "Remind me to call the dentist tomorrow at nine. Actually make that Friday at ten.",
            "Sarah said the meeting moved to Tuesday. Keep that as a note."
        ] {
            let rows = try await RuntimeExampleLibrary.shared.select(query, configuration: configuration)
            XCTAssertFalse(rows.isEmpty)
            XCTAssertLessThanOrEqual(rows.count, 6)
            XCTAssertTrue(rows.allSatisfy { !$0.approval.production_eligible })
            XCTAssertTrue(Set(rows.map(\.id)).isDisjoint(with: ["SIR1-506751", "SIR1-509711", "SIR1-034355"]))
        }
    }
}
#endif

