final class RuntimeQuantityAnalogyTests: XCTestCase {
    private let source = "Buy five cartons of resin beads for my godmother and two for my neighbor. Each carton has twelve beads. Actually my godmother needs three cartons, not five; my neighbor's two stay. Add one spool of silver cord for me. The quantities are separate allocations, not shared totals."
    private func examples() async throws -> [RuntimeWorkedExample] {
        var config = try XCTUnwrap(RuntimeExampleTestFixtures.reviewed)
        config.excludedBlueprints = ["fam_purchase_allocation","shop_add_quantity","shop_allocation","shop_package","shop_replace_quantity"]
        return try await RuntimeExampleLibrary.shared.select(source,configuration:config)
    }
    func testAutomaticAnalogousWorkedPairCompilesActualDiscrepancyAndBindsCurrentValues() async throws {
        let rows = try await examples(); let program = try XCTUnwrap(rows.compactMap(RuntimeQuantityAnalogy.compile).first)
        XCTAssertEqual(program.referenceID,"SIR1-509678")
        let repaired = try XCTUnwrap(RuntimeQuantityAnalogy.interpret(source,examples:rows))
        XCTAssertEqual(repaired.items.count,3)
        XCTAssertEqual(repaired.items.map(\.analysisText),[
            "Buy three cartons of resin beads for my godmother (Each carton has twelve beads)",
            "Buy two cartons of resin beads for my neighbor (Each carton has twelve beads)",
            "Buy one spool of silver cord for me"])
        XCTAssertTrue(repaired.items.allSatisfy { $0.organization.itemType == .shopping && !$0.needsReview
            && $0.organization.personName == nil && $0.organization.dueDate == nil && $0.organization.reminderDate == nil
            && $0.sourceQuote == source })
        XCTAssertNil(RuntimeQuantityAnalogy.interpret(source,examples:[]),"A source parser without a demonstrated repair must not claim example consumption")
        for forbidden in ["pencil", "stepbrother", "picture frame", "cooler", "October"] {
            XCTAssertFalse(repaired.items.contains { $0.analysisText.localizedCaseInsensitiveContains(forbidden) })
        }
    }
    func testContradictoryOldQuantityAmbiguousOwnerUnchangedSiblingAndHiddenTailDecline() async throws {
        let rows = try await examples()
        for invalid in [source.replacingOccurrences(of:"not five",with:"not four"),
            source.replacingOccurrences(of:"neighbor's two stay",with:"neighbor's four stay"),
            source + " Also call Mom tomorrow.",
            source.replacingOccurrences(of:"my neighbor",with:"my godmother"),
            "My aunt said, \"" + source + "\" I have not agreed.",
            source.replacingOccurrences(of:"needs three cartons",with:"might need three cartons")]
        { XCTAssertNil(RuntimeQuantityAnalogy.interpret(invalid,examples:rows),invalid) }
    }
    func testSameObjectAllocationsRetainDifferentOwnersAndOuterAmountsNeverBecomeContents() async throws {
        let rows = try await examples()
        let current = "Buy eight boxes of ceramic pins for Dad and four for my sister. Each box contains six pins. Actually Dad needs two boxes, not eight; my sister's four stay."
        let result = try XCTUnwrap(RuntimeQuantityAnalogy.interpret(current,examples:rows))
        XCTAssertEqual(result.items.count,2)
        XCTAssertEqual(result.items[0].analysisText,"Buy two boxes of ceramic pins for Dad (Each box contains six pins)")
        XCTAssertEqual(result.items[1].analysisText,"Buy four boxes of ceramic pins for my sister (Each box contains six pins)")
        XCTAssertNil(RuntimeQuantityAnalogy.interpret(current.replacingOccurrences(of:"Each box contains six pins",with:"Each crate contains six pins"),examples:rows))
        XCTAssertNil(RuntimeQuantityAnalogy.interpret(current.replacingOccurrences(of:"Each box contains six pins.",with:"Each box contains six pins. Each box contains nine pins."),examples:rows),"Unresolved package-content conflict cannot be marked resolved")
    }
    func testCurrentPurchaseAuthorityIdentityConditionsAndDatesStayAuthoritative() async throws {
        let rows = try await examples()
        for invalid in [
            "Put five packs of ceramic pins for Dad in the crate. Actually Dad needs three packs, not five.",
            "Get five packs of ceramic pins for Dad. Actually Dad needs three packs, not five.",
            "Buy five packs of ceramic pins for Elias. Actually Elia needs three packs, not five.",
            "Buy five packs of ceramic pins for Jonas. Actually Jona needs three packs, not five.",
            "Buy five packs of ceramic pins for Dad on November 7. Actually Dad needs three packs, not five.",
            "Buy five packs of ceramic pins for Dad on Friday. Actually Dad needs three packs, not five.",
            "Buy five packs of ceramic pins for Dad at 3 PM. Actually Dad needs three packs, not five.",
            "Buy five packs of ceramic pins for Dad only with permission. Actually Dad needs three packs, not five.",
            "Buy five packs of ceramic pins for Dad once my aunt approves. Actually Dad needs three packs, not five.",
            "Buy five packs of ceramic pins for Dad, call Mayra about the crates. Actually Dad needs three packs, not five.",
            "Buy five packs of ceramic pins for . Actually make ceramic pins three packs, not five.",
            "Buy five packs of ceramic pins for Dad, the shed contains our ladder. Actually Dad needs three packs, not five.",
            "Buy five packs of ceramic pins for Dad and email Livia about the crate. Actually Dad needs three packs, not five.",
            "Buy five packs of ceramic pins for Dad, perhaps lentils. Actually Dad needs three packs, not five.",
            "For the shopping, put five packs of ceramic pins in the car for Dad. Actually Dad needs three packs, not five.",
            "For the shopping, get five packs of ceramic pins from the cupboard for Dad. Actually Dad needs three packs, not five.",
        ] { XCTAssertNil(RuntimeQuantityAnalogy.interpret(invalid,examples:rows),invalid) }
        let current = "Buy five packs of ceramic pins for Elias. Actually Elias needs three packs, not five."
        XCTAssertEqual(try XCTUnwrap(RuntimeQuantityAnalogy.interpret(current,examples:rows)).items.first?.analysisText,"Buy three packs of ceramic pins for Elias")
    }
    func testCorrectionRoleDoesNotBorrowAnObjectOrRecipientAndEllipsisKeepsExplicitUnits() async throws {
        let rows = try await examples()
        XCTAssertNil(RuntimeQuantityAnalogy.interpret("Buy five packs of Elias for Vera. Actually Elias needs three packs, not five.",examples:rows))
        XCTAssertNil(RuntimeQuantityAnalogy.interpret("Buy five packs of beads for Elias. Actually make the Elias three packs, not five.",examples:rows))
        let current = "Buy five cartons of beads for Elias and two packs for Vera. Actually Elias needs three cartons, not five; Vera's two stay."
        let result = try XCTUnwrap(RuntimeQuantityAnalogy.interpret(current,examples:rows))
        XCTAssertEqual(result.items.map(\.analysisText),["Buy three cartons of beads for Elias","Buy two packs of beads for Vera"])
        let allocation = "Buy five packs of beads for Elias. Actually make Elias's allocation three packs, not five."
        XCTAssertEqual(try XCTUnwrap(RuntimeQuantityAnalogy.interpret(allocation,examples:rows)).items.first?.analysisText,"Buy three packs of beads for Elias")
    }
    func testLaterSamePackageAllocationRetainsEarlierUniversalContents() async throws {
        let rows = try await examples()
        let current = "Buy five cartons of beads for Elias. Each carton has twelve beads. Actually Elias needs three cartons, not five. Add two cartons of beads for Vera."
        let result = try XCTUnwrap(RuntimeQuantityAnalogy.interpret(current,examples:rows))
        XCTAssertEqual(result.items.map(\.analysisText),["Buy three cartons of beads for Elias (Each carton has twelve beads)","Buy two cartons of beads for Vera (Each carton has twelve beads)"])
        XCTAssertNil(RuntimeQuantityAnalogy.interpret(current.replacingOccurrences(of:"Add two cartons of beads",with:"Add two cartons of pins"),examples:rows),"Unresolved late package-content scope cannot silently lose its count")
        XCTAssertNil(RuntimeQuantityAnalogy.interpret("Buy five cartons of Elias for Noah. Each carton has twelve Elias. Actually Noah needs three cartons, not five. Add two cartons of Elia for Vera.",examples:rows),"Distinct CURRENT object literals never share package contents by singularization")
        XCTAssertNil(RuntimeQuantityAnalogy.interpret("Buy five cartons of Elias for Noah. Each carton has twelve Elia. Actually Noah needs three cartons, not five.",examples:rows))
    }
    func testCorruptWorkedAnswerOrMissingReplacementEvidenceCannotProduceAnOperator() async throws {
        let rows = try await examples()
        let original = try XCTUnwrap(rows.first { $0.id == "SIR1-509678" })
        var record = try XCTUnwrap(JSONSerialization.jsonObject(with:Data(original.payload.utf8)) as? [String:Any])
        var solution = try XCTUnwrap(record["solution"] as? [String:Any])
        var groups = try XCTUnwrap(solution["groups"] as? [[String:Any]])
        var entries = try XCTUnwrap(groups[0]["entries"] as? [[String:Any]])
        entries[0]["quantity"] = 7; groups[0]["entries"] = entries; solution["groups"] = groups; record["solution"] = solution
        let corrupt = try JSONDecoder().decode(RuntimeWorkedExample.self,from:JSONSerialization.data(withJSONObject:record))
        XCTAssertNil(RuntimeQuantityAnalogy.compile(corrupt))
        var wrongSpan = record
        var exactSolution = try XCTUnwrap(JSONSerialization.jsonObject(with:Data(original.payload.utf8)) as? [String:Any])["solution"] as! [String:Any]
        var exactGroups = exactSolution["groups"] as! [[String:Any]]
        var spans = exactGroups[0]["evidence"] as! [[String:Any]]
        spans[0]["start"] = (spans[0]["start"] as! Int) + 1
        exactGroups[0]["evidence"] = spans; exactSolution["groups"] = exactGroups; wrongSpan["solution"] = exactSolution
        XCTAssertNil(RuntimeQuantityAnalogy.compile(try JSONDecoder().decode(RuntimeWorkedExample.self,from:JSONSerialization.data(withJSONObject:wrongSpan))))
        var unsupported = try XCTUnwrap(JSONSerialization.jsonObject(with:Data(original.payload.utf8)) as? [String:Any])
        var extraSolution = unsupported["solution"] as! [String:Any]; var extraGroups = extraSolution["groups"] as! [[String:Any]]
        var extraEntries = extraGroups[0]["entries"] as! [[String:Any]]; extraEntries[0]["package_contents"] = ["quantity":9,"text":"unknown contents"]
        extraGroups[0]["entries"] = extraEntries; extraSolution["groups"] = extraGroups; unsupported["solution"] = extraSolution
        XCTAssertNil(RuntimeQuantityAnalogy.compile(try JSONDecoder().decode(RuntimeWorkedExample.self,from:JSONSerialization.data(withJSONObject:unsupported))))

        XCTAssertNil(RuntimeQuantityAnalogy.compile(try XCTUnwrap(rows.first { $0.id == "SIR1-503672" })),"A reference merely present with an unrelated structure is not a repair program")
    }
}
#endif

#if DEBUG
@MainActor
final class RuntimeDiscourseCertificateTests: XCTestCase {
    private var calendar: Calendar { var c = Calendar(identifier:.gregorian); c.timeZone = TimeZone(identifier:"America/Toronto")!; return c }
    private var reference: Date { ISO8601DateFormatter().date(from:"2026-10-04T13:00:00Z")! }
    static let actualFullSource = """
    I am thinking about the club event on Friday, October ninth. The room itself is already confirmed, so that is one less thing to chase. I need to print the direction sign, the one with the arrow to the courtyard entrance. Last time people kept trying the front doors and then messaging us because they were locked. Use the bigger type version. Get that printed before the event starts at six in the evening; I do not want the reminder to happen only when people are arriving.
    
    Asha said, 'Tell everyone to bring a mug,' in the committee chat. I have not agreed to send that message. I want to keep what she said as part of the event notes because we still need to decide whether the room has enough cups. My own task is to ask the caretaker how many cups are there. That needs doing tomorrow, before anybody sends a confident message about what people should bring.
    
    The spare name badges are in the orange envelope inside the supplies bag. Remember that. I wasted a ridiculous amount of time looking in the box of cables last time. I do not need a task to move them, I just need to find them when we pack. The little black marker is with the badges too, so that detail belongs in the same note.
    
    And email Jonah the final volunteer rota once Priya has approved it. She has looked at it, but she has not said it is approved. That difference matters because I think two people are still swapping slots. No, actually, the person collecting the rota is June, not Jonah. Email June the final volunteer rota once Priya has approved it. I am not changing any of the shifts myself in this recording. There is also an idea for next time, having a quiet corner where people can step away from the noise. Keep that as an idea rather than adding another job for Friday.
    """
    private var full: String { Self.actualFullSource }
    private func propose(_ source: String) -> (ThoughtExtractionResult,RuntimeRuleTrace?) {
        var trace: RuntimeRuleTrace?
        let p = RuleBasedThoughtExtractor.process(source,referenceDate:reference,calendar:calendar,traceObserver:{ trace = $0 })
        return (.init(items:p.items,operations:p.operations,method:.rules),trace)
    }
    private func validate(_ p: ThoughtExtractionResult,_ trace: RuntimeRuleTrace?,source: String) -> ThoughtExtractionResult? {
        RuntimeDiscourseCertificate.validate(p,trace:trace,source:source,referenceDate:reference,calendar:calendar)
    }
    private func replacing(_ trace: RuntimeRuleTrace,output: [ExtractedThought],segments: [String]? = nil) -> RuntimeRuleTrace {
        .init(original:trace.original,normalized:trace.normalized,corrected:trace.corrected,creating:trace.creating,
            repairs:trace.repairs,correctedWordRawIDs:trace.correctedWordRawIDs,propositions:trace.propositions,
            segmentQuotes:segments ?? trace.segmentQuotes,segmentRoles:trace.segmentRoles,
            unmatchedSegments:trace.unmatchedSegments,unassignedWordIDs:trace.unassignedWordIDs,
            captureOnlyWordIDs:trace.captureOnlyWordIDs,group:trace.group,output:output)
    }
    private func row(_ item: ExtractedThought,analysis: String? = nil,title: String? = nil,organization: OrganizedThought? = nil) -> ExtractedThought {
        .init(sourceQuote:item.sourceQuote,rawQuote:item.rawQuote,wasRepaired:item.wasRepaired,
            analysisText:analysis ?? item.analysisText,suggestedTitle:title ?? item.suggestedTitle,
            organization:organization ?? item.organization,confidence:item.confidence,needsReview:item.needsReview,
            sourceUnitIDs:item.sourceUnitIDs,shoppingGroup:item.shoppingGroup)
    }
    private func organization(_ item: ExtractedThought,kind: ItemType? = nil,person: String? = nil,due: Date? = nil,temporal: TemporalIntent? = nil) -> OrganizedThought {
        let o = item.organization
        return .init(itemType:kind ?? o.itemType,category:o.category,priority:o.priority,personName:person ?? o.personName,
            dueDate:due ?? o.dueDate,reminderDate:o.reminderDate,reminderDelivery:o.reminderDelivery,
            recurrenceRule:o.recurrenceRule,needsClarification:o.needsClarification,
            temporalIntent:temporal ?? o.temporalIntent,locationIntent:o.locationIntent,state:o.state)
    }
    func testCompleteActualLongSourceIsIndependentlyCertified() throws {
        let (p,t) = propose(full); XCTAssertEqual(p.items.count,6); XCTAssertNotNil(validate(p,t,source:full))
        XCTAssertEqual(p.items.filter { $0.organization.personName == "June" }.count,1)
        XCTAssertEqual(p.items.map { $0.organization.itemType },[.task,.note,.task,.note,.personFollowUp,.idea])
        XCTAssertTrue(p.items.allSatisfy { !$0.needsReview && $0.organization.reminderDate == nil })
    }
    func testObserverIsObservationalAndMissingTraceCannotApprove() {
        let (p,t) = propose(full)
        let ordinary = RuleBasedThoughtExtractor.process(full,referenceDate:reference,calendar:calendar)
        XCTAssertEqual(p.items,ordinary.items); XCTAssertEqual(p.operations,ordinary.operations)
        XCTAssertNotNil(t); XCTAssertNil(validate(p,nil,source:full))
    }
    func testRenamedSourceFactsAndRepeatedUnicodeOccurrencesAreCurrentOnly() {
        let renamed = full.replacingOccurrences(of:"Asha",with:"Mina").replacingOccurrences(of:"Jonah",with:"Áine")
            .replacingOccurrences(of:"June",with:"Noé").replacingOccurrences(of:"Priya",with:"Tariq")
            .replacingOccurrences(of:"volunteer rota",with:"access map").replacingOccurrences(of:"the rota",with:"the map")
        let (p,t) = propose(renamed); XCTAssertNotNil(validate(p,t,source:renamed))
        XCTAssertEqual(p.items.first { $0.organization.personName == "Noé" }?.analysisText,"email Noé the final access map once Tariq has approved it")
        XCTAssertFalse(p.items.contains { $0.organization.personName == "June" })
    }
    func testWrongCurrentRolesObjectAndConditionFailDespiteFullCoverage() throws {
        let (p,maybeTrace) = propose(full); let t = try XCTUnwrap(maybeTrace); let index = try XCTUnwrap(p.items.firstIndex { $0.organization.personName == "June" })
        let original = p.items[index]
        for corrupt in [
            row(original,organization:organization(original,person:"Priya")),
            row(original,analysis:"email June the rota once Priya has approved it",title:"email June the rota once Priya has approved it"),
            row(original,analysis:"email June the final volunteer rota",title:"email June the final volunteer rota"),
            row(original,analysis:"email June the final volunteer rota before Priya has approved it",title:"email June the final volunteer rota before Priya has approved it"),
            row(original,organization:organization(original,due:calendar.date(byAdding:.day,value:1,to:reference)!))
        ] {
            var items = p.items; items[index] = corrupt
            XCTAssertNil(validate(.init(items:items,method:.rules),replacing(t,output:items),source:full))
        }
    }
    func testWrongPurposesAndDuplicateIntentionFailWithUnchangedSource() throws {
        let (p,maybeTrace) = propose(full); let t = try XCTUnwrap(maybeTrace)
        for (index,kind) in [(1,ItemType.task),(2,.note),(3,.task),(5,.task)] {
            var items = p.items; items[index] = row(items[index],organization:organization(items[index],kind:kind))
            XCTAssertNil(validate(.init(items:items,method:.rules),replacing(t,output:items),source:full))
