    /// Deliberately corrupt producer seam: exact occurrence coverage must not
    /// license burying a current directive or a different report owner.
    private func seam(_ groups: [[String]], meanings: [(String, ItemType, String?)]) -> (ThoughtExtractionResult,RuntimeRuleTrace,String) {
        let sentences = groups.flatMap { $0 }
        let source = sentences.joined(separator:". ")
        let ledger = SourceUnitLedger(source)
        var cursor = source.startIndex,ids: [Set<Int>] = [],propositions: [RuntimeRuleTrace.Proposition] = []
        for (index,sentence) in sentences.enumerated() {
            let range = source.range(of:sentence,range:cursor..<source.endIndex)!
            cursor = range.upperBound
            let owned = ledger.ids(in:range); ids.append(owned)
            propositions.append(.init(segment:index,range:NSRange(range,in:source),wordIDs:owned))
        }
        var start = 0,items: [ExtractedThought] = []
        for (group,meaning) in zip(groups,meanings) {
            let own = ids[start..<start+group.count].reduce(into:Set<Int>()) { $0.formUnion($1) }; start += group.count
            let quote = group.joined(separator:" … ")
            let org = OrganizedThought(itemType:meaning.1,category:.general,priority:.normal,
                personName:meaning.2,dueDate:nil,reminderDate:nil,reminderDelivery:.none,
                recurrenceRule:nil,needsClarification:false,state:.resolved)
            items.append(.init(sourceQuote:quote,rawQuote:quote,wasRepaired:false,analysisText:meaning.0,
                suggestedTitle:meaning.0,organization:org,confidence:1,needsReview:false,sourceUnitIDs:own))
        }
        let p = ThoughtExtractionResult(items:items,method:.rules)
        let t = RuntimeRuleTrace(original:source,normalized:source,corrected:source,creating:source,repairs:[],
            correctedWordRawIDs:ledger.words.indices.map { Set([$0]) },propositions:propositions,
            segmentQuotes:sentences,segmentRoles:[],unmatchedSegments:[],unassignedWordIDs:[],captureOnlyWordIDs:[],group:nil,output:items)
        return (p,t,source)
    }
    func testLatestNegativeBehaviorAndUnlicensedCurrentCommandsDeclineEvenWithAlignedProducer() {
        let email = "email Luma the final dock timetable once Zoya has approved it"
        let idea = "There is an idea for a folding map stand"
        let (p,t,s) = seam([[email,"That difference matters because I think I will not email that timetable"],[idea]],
            meanings:[(email,.personFollowUp,"Luma"),(idea,.idea,nil)])
        XCTAssertNil(validate(p,t,source:s))
        for tail in ["unlock the courtyard gate","rinse the sample cup","delete the unused file","set an alarm for seven","degauss the sensor"] {
            let root = "I need to print the access board"
            let (p,t,s) = seam([[root,"Last time people used the wrong entrance, and " + tail],[idea]],
                meanings:[(root,.task,nil),(idea,.idea,nil)])
            XCTAssertNil(validate(p,t,source:s),tail)
            let actual = propose(s); XCTAssertNil(validate(actual.0,actual.1,source:s),"actual producer: " + tail)
        }
        let negative = full.replacingOccurrences(of:"That difference matters because I think two people are still swapping slots",
            with:"That difference matters because I think I will not email that rota")
        let actual = propose(negative); XCTAssertNil(validate(actual.0,actual.1,source:negative))
        for tail in ["Last time the doors were locked. The job to print the access board is cancelled",
                     "Last time the doors were locked although the print task’s cancelled now",
                     "Last time the doors were locked but it is no longer needed",
                     "Last time people used the wrong entrance but unlock the courtyard gate",
                     "Last time people used the wrong entrance and the task is to degauss the sensor",
                     "Last time people used the wrong entrance and my task is to unlock the courtyard gate",
                     "Last time people used the wrong entrance and my job is to call the caretaker",
                     "Last time people used the wrong entrance. Unlock the courtyard gate",
                     "Last time people used the wrong entrance — degauss the sensor",
                     "Last time people used the wrong entrance: rinse the sample cup",
                     "Last time people used the wrong entrance and we have an obligation to unlock the courtyard gate",
                     "That difference matters because I think I have decided not to email that timetable",
                     "That difference matters because I think I am refusing to email that timetable",
                     "That difference matters because I think I refuse to email that timetable",
                     "That difference matters because I think the email to Luma is cancelled",
                     "That difference matters because I think it is cancelled",
                     "That difference matters because I think the timetable is being cancelled",
                     "I am not changing any of the shifts but will unlock doors myself in this recording",
                     "I am not changing any of the shifts and I will unlock the courtyard gate myself in this recording"] {
            let root = tail.hasPrefix("I am") || tail.hasPrefix("That difference") ? email : "I need to print the access board"
            let (p,t,s) = seam([[root,tail],[idea]],meanings:[(root,root == email ? .personFollowUp : .task,root == email ? "Luma" : nil),(idea,.idea,nil)])
            XCTAssertNil(validate(p,t,source:s),tail)
            let actual = propose(s); XCTAssertNil(validate(actual.0,actual.1,source:s),"actual producer: " + tail)
        }
    }
