    func testLFCRLFAndCRScopeBoundariesDeclineIdenticalCoveredProposal() throws {
        let (p,maybeTrace) = propose(full); let t = try XCTUnwrap(maybeTrace)
        for breakText in ["\n\n","\r\n\r\n","\r\r"] {
            let source = full.replacingOccurrences(of:"chase. I need to print",with:"chase." + breakText + "I need to print")
            let changed = RuntimeRuleTrace(original:source,normalized:t.normalized,corrected:t.corrected,creating:t.creating,
                repairs:t.repairs,correctedWordRawIDs:t.correctedWordRawIDs,propositions:t.propositions,
                segmentQuotes:t.segmentQuotes,segmentRoles:t.segmentRoles,unmatchedSegments:t.unmatchedSegments,
                unassignedWordIDs:t.unassignedWordIDs,captureOnlyWordIDs:t.captureOnlyWordIDs,group:t.group,output:t.output)
            XCTAssertNil(validate(p,changed,source:source),String(reflecting:breakText))
            let actual = propose(source); XCTAssertNil(validate(actual.0,actual.1,source:source))
        }
    }
