#if canImport(FoundationModels)
@available(iOS 26.4, *)
final class RuntimeDynamicPointerPlanTests: XCTestCase {
    private func row(_ ids: [Int],_ purpose: RuntimeFoundationInterpreter.Purpose = .task) -> RuntimeFoundationInterpreter.FirstOutlineRow {
        .init(evidence:ids,purpose:purpose,requiresRewrite:false,needsReview:false)
    }
    private func decode(_ json: String,_ source: String) throws -> [RuntimeFoundationInterpreter.FirstOutlineRow]? {
        try RuntimeFoundationInterpreter.decodeDynamicOutline(GeneratedContent(json:json),units:RuntimeIndexedSource(source))
    }
    func testSchemaContainsOnlyExactCurrentIdentifiersAndNoFirstStageAnchor() throws {
        let units = RuntimeIndexedSource("Call Mom. Buy two bags.")
        let schema = try XCTUnwrap(RuntimeFoundationInterpreter.dynamicOutlineSchema(units))
        let text = String(decoding:try JSONEncoder().encode(schema),as:UTF8.self)
        XCTAssertTrue(text.contains("\"u0\""));XCTAssertTrue(text.contains("\"u1\""));XCTAssertFalse(text.contains("\"u2\""))
        XCTAssertFalse(text.contains("\"anchor\""));XCTAssertFalse(text.contains("\"currentMeaning\""))
        XCTAssertNil(try RuntimeFoundationInterpreter.dynamicOutlineSchema(RuntimeIndexedSource(" \n")))
    }
    func testDecoderRejectsUnknownDuplicateUnsortedAndEmptyCurrentIDs() throws {
        for ids in ["[]","[\"u2\"]","[\"u00\"]","[\"u0\",\"u0\"]","[\"u1\",\"u0\"]","[\"u0\",\"foreign_saved_id\"]"] {
            let json = "{\"items\":[{\"evidence\":" + ids + ",\"purpose\":\"task\",\"requiresRewrite\":false,\"needsReview\":false}]}"
            XCTAssertNil(try decode(json,"Call Mom. Buy two bags."),ids)
        }
    }
    func testDecoderPreservesExactPurposeFlagsAndCannotGuessMissingFields() throws {
        let json = #"{"items":[{"evidence":["u0"],"purpose":"inventory","requiresRewrite":false,"needsReview":true}]}"#
        let rows = try XCTUnwrap(decode(json,"Inventory: two bags."))
        XCTAssertEqual(rows.count,1);XCTAssertEqual(rows[0].evidence,[0]);XCTAssertEqual(rows[0].purpose,.inventory)
        XCTAssertTrue(rows[0].needsReview);XCTAssertFalse(rows[0].requiresRewrite)
        XCTAssertNil(try decode(json.replacingOccurrences(of:"inventory",with:"Inventory"),"Inventory: two bags."))
        XCTAssertThrowsError(try decode(json.replacingOccurrences(of:",\"needsReview\":true",with:""),"Inventory: two bags."))
        XCTAssertThrowsError(try decode(json.replacingOccurrences(of:"false",with:"\"false\""),"Inventory: two bags."))
    }
    func testProvisionalPlanRequiresEveryCurrentUnitIncludingTail() throws {
        let units = RuntimeIndexedSource("Call Mom. Buy two bags.")
        XCTAssertNil(RuntimeFoundationInterpreter.stagedOutlinePlan([row([0])],units:units))
        XCTAssertNil(RuntimeFoundationInterpreter.stagedOutlinePlan([row([0]),row([2])],units:units))
        let plan = try XCTUnwrap(RuntimeFoundationInterpreter.stagedOutlinePlan([row([0]),row([1],.shopping)],units:units))
        XCTAssertTrue(plan.sharedRows.isEmpty);XCTAssertEqual(plan.items.count,2)
        XCTAssertTrue(RuntimeFoundationInterpreter.validOwnership(plan.items,units:units))
    }
    func testSharedEvidenceIsProvisionalUntilBothLiteralAnchorsAreCompleted() throws {
        let units = RuntimeIndexedSource("Call Mom and call my brother’s partner.")
        let plan = try XCTUnwrap(RuntimeFoundationInterpreter.stagedOutlinePlan([row([0]),row([0])],units:units))
        XCTAssertEqual(plan.sharedRows,[0,1]);XCTAssertFalse(RuntimeFoundationInterpreter.validOwnership(plan.items,units:units))
        let revisions = [RuntimeFoundationInterpreter.IndexedRevision(row:0,anchor:"Call Mom",currentMeaning:"Call Mom",directContact:"Mom"),
            .init(row:1,anchor:"call my brother’s partner",currentMeaning:"call my brother’s partner",directContact:"my brother’s partner")]
        let complete = try XCTUnwrap(RuntimeFoundationInterpreter.completingStagedPlan(plan.items,revisions:revisions,requestedRows:[0,1],sharedRows:plan.sharedRows,units:units))
        XCTAssertTrue(RuntimeFoundationInterpreter.validOwnership(complete,units:units))
        var forged = revisions;forged[1].anchor = "Call my brother"
        XCTAssertNil(RuntimeFoundationInterpreter.completingStagedPlan(plan.items,revisions:forged,requestedRows:[0,1],sharedRows:plan.sharedRows,units:units))
        forged = revisions;forged[1].anchor = "call my brother"
        XCTAssertNil(RuntimeFoundationInterpreter.completingStagedPlan(plan.items,revisions:forged,requestedRows:[0,1],sharedRows:plan.sharedRows,units:units),"A truncated nested relation cannot pass ownership")
    }
    func testAllRequestedRevisionsAreAtomicWithoutMissingDuplicateOrExtraRows() throws {
        let units = RuntimeIndexedSource("Call Mom and call my brother’s partner.")
        let plan = try XCTUnwrap(RuntimeFoundationInterpreter.stagedOutlinePlan([row([0]),row([0])],units:units))
        let a = RuntimeFoundationInterpreter.IndexedRevision(row:0,anchor:"Call Mom",currentMeaning:"Call Mom",directContact:"Mom")
        let b = RuntimeFoundationInterpreter.IndexedRevision(row:1,anchor:"call my brother’s partner",currentMeaning:"call my brother’s partner",directContact:"my brother’s partner")
        var empty = b;empty.currentMeaning = ""
        var extra = b;extra.row = 2
        for revisions in [[a],[a,a],[a,empty],[a,extra],[a,b,b]] {
            XCTAssertNil(RuntimeFoundationInterpreter.completingStagedPlan(plan.items,revisions:revisions,requestedRows:[0,1],sharedRows:[0,1],units:units))
        }
        XCTAssertNil(RuntimeFoundationInterpreter.completingStagedPlan(plan.items,revisions:[a,b],requestedRows:[0],sharedRows:[0,1],units:units))
    }
    func testNonsharedRevisionCannotIntroduceFreeAnchor() throws {
        let units = RuntimeIndexedSource("Call Mom.")
        let plan = try XCTUnwrap(RuntimeFoundationInterpreter.stagedOutlinePlan([row([0])],units:units))
        let free = RuntimeFoundationInterpreter.IndexedRevision(row:0,anchor:"Call Mom",currentMeaning:"Call Mom",directContact:"Mom")
        XCTAssertNil(RuntimeFoundationInterpreter.completingStagedPlan(plan.items,revisions:[free],requestedRows:[0],sharedRows:[],units:units))
        var plain = free;plain.anchor = ""
        XCTAssertNotNil(RuntimeFoundationInterpreter.completingStagedPlan(plan.items,revisions:[plain],requestedRows:[0],sharedRows:[],units:units))
    }
    func testDynamicAdapterHasNoThirtyIntentionPlanCapAndKeepsLastUnit() throws {
        let source = (1...31).map { "Buy \($0) cloth bags." }.joined(separator:" ")
        let units = RuntimeIndexedSource(source);XCTAssertEqual(units.units.count,31)
        let schema = try XCTUnwrap(RuntimeFoundationInterpreter.dynamicOutlineSchema(units))
        let text = String(decoding:try JSONEncoder().encode(schema),as:UTF8.self);XCTAssertTrue(text.contains("\"u30\""))
        let plan = try XCTUnwrap(RuntimeFoundationInterpreter.stagedOutlinePlan(units.units.indices.map { row([$0],.shopping) },units:units))
        XCTAssertEqual(plan.items.count,31);XCTAssertEqual(plan.items.last?.evidence,[30]);XCTAssertTrue(plan.sharedRows.isEmpty)
    }
}
