final class RuntimeCurrentCorrectionProofTests: XCTestCase {
    func testInheritedObjectReplacementRetainsFullTopicClockAndLiteralRelation() throws {
        for (old,new,topic,repeatNoun) in [("Mom","my great-uncle","the astronomy booklet","booklet"),("Nima","my brother’s partner","the copper lantern","lantern"),("Dad","Savi","the garden plan","garden plan")] {
