            XCTAssertEqual(proof.action,"Ask \(new) about \(topic) tomorrow");XCTAssertEqual(proof.recipient,new)
        }
    }
    func testInheritedReplacementCannotGuessObjectActorConditionOrQuotation() {
        let source = "Ask Mom about the astronomy booklet tomorrow. Actually ask my great-uncle; same booklet."
        for bad in [source.replacingOccurrences(of:"same booklet",with:"same cover"),source.replacingOccurrences(of:"same booklet",with:"same thing"),source.replacingOccurrences(of:"same booklet",with:"same it"),source.replacingOccurrences(of:"same booklet",with:"same question"),source.replacingOccurrences(of:"Actually ask",with:"Actually do not ask"),source.replacingOccurrences(of:"tomorrow.",with:"tomorrow if Mom agrees."),source.replacingOccurrences(of:"my great-uncle",with:"their father"),"Lumi said, \"" + source + "\"",source + " Do not make that call.",source.replacingOccurrences(of:"booklet tomorrow",with:"booklet and buy a lamp tomorrow")] {
            XCTAssertNil(RuntimeCommunicationReading.read(bad),bad)
        }
    }
    func testJointCallProofRetainsParticipantsTopicChoiceAndNoAlert() throws {
        let source = "I thought of separate calls to Mom and my stepdad about the holiday seating. Actually make it one call with both of them together on November 22. That joint call is the final choice, no timed alert."
        let proof = try XCTUnwrap(RuntimeJointCallReading.read(source))
        XCTAssertEqual(proof.action,"One joint call with Mom and my stepdad about the holiday seating on November 22, no timed alert")
        let unfamiliar = source.replacingOccurrences(of:"Mom",with:"Neri").replacingOccurrences(of:"my stepdad",with:"my aunt’s husband").replacingOccurrences(of:"holiday seating",with:"museum rota").replacingOccurrences(of:"November 22",with:"December 8")
        XCTAssertEqual(RuntimeJointCallReading.read(unfamiliar)?.action,"One joint call with Neri and my aunt’s husband about the museum rota on December 8, no timed alert")
        for bad in [source.replacingOccurrences(of:"final choice",with:"possible choice"),source.replacingOccurrences(of:"no timed alert",with:"remind me at nine"),source.replacingOccurrences(of:"my stepdad",with:"their father"),source.replacingOccurrences(of:"both of them",with:"one of them"),source.replacingOccurrences(of:"November 22",with:"November 99"),source.replacingOccurrences(of:"holiday seating",with:"holiday seating if Dad agrees"),source + " I withdraw that choice.","Lumi said, \"" + source + "\"",source.replacingOccurrences(of:"Mom and my stepdad",with:"Mom and Mom")] {
            XCTAssertNil(RuntimeJointCallReading.read(bad),bad)
        }
    }
}
