    func testCorrectSourceProofCannotAuthorizeWrongOwnerInvalidDayOrAdditionalAct() throws {
        var calendar = Calendar(identifier:.gregorian);calendar.timeZone = TimeZone(identifier:"America/Toronto")!
        let reference = ISO8601DateFormatter().date(from:"2026-11-16T14:00:00Z")!
        func lower(_ source:String,_ purpose:RuntimeFoundationInterpreter.Purpose,_ meaning:String) -> ThoughtExtractionResult? {
            let units = RuntimeIndexedSource(source)
            return RuntimeFoundationInterpreter.validateIndexed(.init(items:[.init(evidence:Array(units.units.indices),purpose:purpose,currentMeaning:meaning,directContact:"",needsReview:false)]),source:source,units:units,referenceDate:reference,calendar:calendar,rules:.init(items:[],method:.rules),context:.empty)
