    func testProofsUseCompleteCurrentCorrectionAndPreserveOwnerSpecificAllocation() throws {
        let source = "Buy four coils of orange twine for Jani no make Jani three coils and add two coils for me those allocations stay separate",units = RuntimeIndexedSource(source)
        let item = RuntimeFoundationInterpreter.IndexedItem(evidence:Array(units.units.indices),purpose:.shopping,currentMeaning:"",directContact:"",needsReview:false)
        let proof = try XCTUnwrap(RuntimeFoundationInterpreter.currentRevisionProofs([item],requestedRows:[0],sharedRows:[],units:units)[0])
        let entries = try XCTUnwrap(RuntimeAllocationReading.entries(proof.meaning))
