        XCTAssertNotEqual(RuntimeAllocationReading.entries(wrong),RuntimeAllocationReading.expected(source))
        let schema = try XCTUnwrap(RuntimeFoundationInterpreter.dynamicRevisionSchema(requestedRows:Set(0...30),sharedRows:[],proofRows:Set(0...30)))
        let text = String(decoding:try JSONEncoder().encode(schema),as:UTF8.self)
        XCTAssertTrue(text.contains("\"r30\""));XCTAssertFalse(text.contains("\"currentMeaning\""));XCTAssertFalse(text.contains("\"anchor\""))
    }
}
#endif

