final class RuntimeDynamicPointerSemanticFalsifierTests: XCTestCase {
    private var calendar: Calendar { var c = Calendar(identifier:.gregorian); c.timeZone = TimeZone(identifier:"America/Toronto")!; return c }
    private var reference: Date { ISO8601DateFormatter().date(from:"2026-11-16T14:00:00Z")! }
    private func read(_ source:String,_ items:[RuntimeFoundationInterpreter.IndexedItem]) -> ThoughtExtractionResult? {
        RuntimeFoundationInterpreter.validateIndexed(.init(items:items),source:source,units:RuntimeIndexedSource(source),
            referenceDate:reference,calendar:calendar,rules:.init(items:[],method:.rules),context:.empty)
    }
    func testNarrativeFiniteProofDiagnosticUsesOnlySyntheticFixtures() {
        let fixtures = ["Save one connected Memory about the prism stand. Nori made it; Oriel owns it. The label is PRISM-004. Nori said, \"Return it tomorrow.\" I have not adopted that request. Its earlier green finish is now blue; the change was completed in 2021.",
            "Keep one coherent Memory about the rehearsal hall. My cousin thinks the sloped floor caused the vibration. I did not measure the floor, so I should not turn that explanation into a confirmed conclusion. These are past events and I am not giving myself jobs."]
        for source in fixtures {
            let heading = source.range(of:#"(?i)^\s*(?:keep|save|preserve)(?:\s+(?:the\s+following|this)\s+as)?\s+one\s+(?:(?:connected|coherent)\s+)?(?:memory|note|account)(?:\s+(?:about|of)\s+[^.!?:]+)?\s*[.:]"#,options:.regularExpression)!
            let body = String(source[heading.upperBound...])
            for (i,unit) in RuntimeIndexedSource(body).units.enumerated() {
                let text = QuotedSpeechScope.voiceProjection(in:unit.text)!.ownVoiceText
                let context = SentenceContextCache.context(for:text)
                let labels = context.tokens.map { $0.text + ":" + ($0.lexicalClass?.rawValue ?? "nil") }
                print("SYNTHETIC-NARRATIVE-TOKENS unit=\(i) text=\(text) disabled=\(SentenceContext.taggerDisabledForEvaluation) tokens=\(labels)")
            }
            let result = RuntimeExampleLibrary.$developmentObserver.withValue({ print("SYNTHETIC-NARRATIVE-DIAGNOSTIC \($0)") }) {
                RuntimeIndependentFramePlan.coherentNarrative(source)
            }
            XCTAssertNotNil(result)
        }
    }
