            XCTAssertEqual(result.items.count,1);XCTAssertEqual(result.items[0].sourceQuote,source)
            XCTAssertEqual(result.items[0].organization.itemType,.note);XCTAssertFalse(result.items[0].needsReview)
            XCTAssertNil(result.items[0].organization.personName);XCTAssertNil(result.items[0].organization.dueDate);XCTAssertNil(result.items[0].organization.reminderDate)
        }
        for body in [
            "I should not turn that explanation into a confirmed conclusion.",
            "I should not turn the release valve tomorrow.",
            "I should not send that conclusion to Dad until the test finishes.",
            "Nori said, I have not adopted that request.",
            "I have not accepted the parcel.",
            "I did not measure the floor. I still need to measure it tomorrow.",
            "Nori wrote, \"Call Dad tomorrow.\" I have not adopted that request; rinse the flask tonight.",
            "Nori wrote, \"Call Dad tomorrow.\" I had not adopted that request, but I accept it now.",
            "My cousin thinks the floor caused the vibration. I should not turn that explanation into a confirmed conclusion, and I should not turn off the heater tonight.",
            "My cousin thinks the floor caused the vibration. I did not measure the floor; rinse the gauge tomorrow. These are past events and I am not giving myself jobs."
        ] { XCTAssertNil(RuntimeIndependentFramePlan.coherentNarrative("Save one Memory about the trial. " + body),body) }
