            for item in result.items { XCTAssertFalse(item.needsReview);XCTAssertEqual(item.organization.dueDate,calendar.date(from:DateComponents(year:2026,month:11,day:17,hour:9)));XCTAssertNil(item.organization.reminderDate) }
        }
