            ("Buy two jumpers for Mom tomorrow.",.task,.shopping,.shopping)]
        for (source,wrong,right,kind) in cases {
            var row = RuntimeFoundationInterpreter.IndexedItem(evidence:[0],purpose:wrong,currentMeaning:"",directContact:"",needsReview:false)
            if let result = read(source,[row]) { for item in result.items where !item.needsReview { XCTAssertEqual(item.organization.itemType,kind,source);XCTAssertNil(item.organization.personName) } }
            row.purpose = right;let result = try XCTUnwrap(read(source,[row]),source)
            XCTAssertEqual(result.items[0].organization.itemType,kind);XCTAssertFalse(result.items[0].needsReview)
            XCTAssertNil(result.items[0].organization.personName);XCTAssertNil(result.items[0].organization.reminderDate)
