        let rows = [RuntimeFoundationInterpreter.IndexedItem(evidence:Array(RuntimeIndexedSource(source).units.indices),purpose:.task,currentMeaning:"Email Ada about the invoice",directContact:"Ada and pack the blanket",needsReview:false)]
        XCTAssertNil(read(source,rows))
        let valid = "Email Noé about the invoice. Actually email Ada, not Noé; the invoice is still the subject."
        let row = RuntimeFoundationInterpreter.IndexedItem(evidence:Array(RuntimeIndexedSource(valid).units.indices),purpose:.task,currentMeaning:"Email Ada about the invoice",directContact:"Ada",needsReview:false)
        let result = try XCTUnwrap(read(valid,[row]));XCTAssertEqual(result.items[0].organization.personName,"Ada");XCTAssertEqual(result.items[0].suggestedTitle,"Email Ada about the invoice")
    }
    func testOneSharedAnchorCannotCombineIndependentActionPredicates() {
        let source = "I will wash the apron and pack the blanket and clean the gauge, all tomorrow at 9 AM."
        XCTAssertNil(read(source,[anchored([0],"wash the apron and pack the blanket"),anchored([0],"clean the gauge")]))
        let ordered = "I will wash the apron and then pack the blanket and clean the gauge, all tomorrow at 9 AM."
        XCTAssertNil(read(ordered,[anchored([0],"wash the apron and then pack the blanket"),anchored([0],"clean the gauge")]))
    }
    func testDetachedAllClockCannotBeAppliedToAnUnprovedSubset() {
        let source = "Wash the apron. Pack the blanket. Clean the gauge. All tomorrow at 9 AM."
        let third = RuntimeFoundationInterpreter.IndexedItem(evidence:[2],purpose:.task,currentMeaning:"",directContact:"",needsReview:false)
        XCTAssertNil(read(source,[anchored([0,3],"Wash the apron"),anchored([1,3],"Pack the blanket",.packing),third]))
    }
    func testLaterHeldCurrentClockCorrectionCannotLeaveEarlierTasksConfidentlyStale() {
        let source = "I will wash the apron and pack the blanket, both tomorrow at 9 AM. Actually move them to Friday at 11 AM."
        let held = RuntimeFoundationInterpreter.IndexedItem(evidence:[1],purpose:.review,currentMeaning:"",directContact:"",needsReview:true)
        if let result = read(source,[anchored([0],"wash the apron"),anchored([0],"pack the blanket",.packing),held]) {
            XCTAssertTrue(result.items.allSatisfy { $0.needsReview || !$0.organization.itemType.isActionable },"A separate review row is not permission to create stale earlier tasks")
        }
    }
    func testUnresolvedEarlierCurrentChangeKeepsIndependentLaterTaskUsable() throws {
        let source = "I will wash the apron and pack the blanket, both tomorrow at 9 AM. Actually move them to Friday at 11 AM. Call Mom tomorrow."
        let held = RuntimeFoundationInterpreter.IndexedItem(evidence:[1],purpose:.review,currentMeaning:"",directContact:"",needsReview:true)
        let later = RuntimeFoundationInterpreter.IndexedItem(evidence:[2],purpose:.task,currentMeaning:"",directContact:"",needsReview:false)
        let result = try XCTUnwrap(read(source,[anchored([0],"wash the apron"),anchored([0],"pack the blanket",.packing),held,later]))
        XCTAssertEqual(result.items.count,4);XCTAssertTrue(result.items[0].needsReview);XCTAssertTrue(result.items[1].needsReview)
        XCTAssertFalse(result.items[3].needsReview);XCTAssertTrue(result.items[3].organization.itemType.isActionable)
        XCTAssertTrue(result.items[3].analysisText.contains("Call Mom"));XCTAssertNil(result.items[3].organization.reminderDate)
    }
    func testCompleteDetachedAllClockKeepsEveryIndependentTask() throws {
        let source = "Wash the apron. Pack the blanket. Clean the gauge. All tomorrow at 9 AM."
        let result = try XCTUnwrap(read(source,[anchored([0,3],"Wash the apron"),anchored([1,3],"Pack the blanket",.packing),anchored([2,3],"Clean the gauge")]))
        XCTAssertEqual(result.items.count,3)
        for item in result.items { XCTAssertFalse(item.needsReview);XCTAssertEqual(item.organization.dueDate,calendar.date(from:DateComponents(year:2026,month:11,day:17,hour:9)));XCTAssertNil(item.organization.reminderDate) }
    }
    func testOnePackingPredicateKeepsCompleteMembershipWithoutSplittingObjects() throws {
        let source = "I will pack the apron and blanket and clean the gauge, both tomorrow at 9 AM."
        let result = try XCTUnwrap(read(source,[anchored([0],"pack the apron and blanket",.packing),anchored([0],"clean the gauge")]))
        XCTAssertEqual(result.items.count,2);XCTAssertTrue(result.items.allSatisfy { !$0.needsReview })
        XCTAssertTrue(result.items[0].suggestedTitle?.contains("apron and blanket") == true)
    }
    func testCurrentRecipientCorrectionCannotAbsorbAnotherExecutiveTopicClause() {
        let source = "Email Noé about the invoice and pack the blanket. Actually email Ada, not Noé; the invoice and pack the blanket is still the subject."
        XCTAssertNil(RuntimeCommunicationReading.read(source))
        for relative in ["my brother’s partner","my stepmother’s sister","Dad"] {
            let source = "Email Noé about the invoice. Actually email \(relative), not Noé; the invoice is still the subject."
            XCTAssertEqual(RuntimeCommunicationReading.read(source)?.recipient,relative)
        }
    }
    func testFullNamedOwnerAndThirdPersonFamilyLiteralsUseActualContactDelimiter() {
        for recipient in ["their grandmother","my brother's partner","Uncle Bob’s sister","Mary Jane’s brother"] {
            let source = "Ask \(recipient) about the rehearsal pass."
            XCTAssertEqual(RuntimeCommunicationReading.read(source)?.recipient,recipient,source)
        }
        for recipient in ["Ada and pack the blanket","Noé and Ada’s brother","their grandmother and rinse the flask"] {
            let source = "Ask \(recipient) about the rehearsal pass."
            XCTAssertNil(RuntimeCommunicationReading.read(source),source)
        }
    }
}

@available(iOS 26.4, *)
final class RuntimeMergedClockOwnershipTests: XCTestCase {
    private var calendar: Calendar { var c = Calendar(identifier: .gregorian); c.timeZone = TimeZone(identifier: "America/Toronto")!; return c }
    private var reference: Date { ISO8601DateFormatter().date(from: "2026-11-16T14:00:00Z")! }
    private func read(_ source: String, _ rows: [RuntimeFoundationInterpreter.IndexedItem]) -> ThoughtExtractionResult? {
        RuntimeFoundationInterpreter.validateIndexed(.init(items: rows), source: source, units: RuntimeIndexedSource(source),
            referenceDate: reference, calendar: calendar, rules: .init(items: [], method: .rules), context: .empty)
    }
    private func row(_ ids: [Int]) -> RuntimeFoundationInterpreter.IndexedItem {
        .init(evidence: ids, purpose: .task, currentMeaning: "", directContact: "", needsReview: false)
    }
    private let datedFamily = "Ask my stepmother’s sister about the rehearsal pass on November 18. Tell Rida to ask their brother about the spare baton on November 20; I am contacting Rida, not that brother. Return Umi’s shoulder rest to my niece November 23. Umi remains owner and my niece is only recipient."

    // Exact accepted Source19 outline from sealed MD02 BOTH-mode failures.
    func testMergedIndependentDatesAreHeldWithoutDamagingIndependentLastAction() throws {
        let result = try XCTUnwrap(read(datedFamily, [row([0, 1, 2]), row([3, 4])]))
        XCTAssertEqual(result.items.count, 2)
        XCTAssertTrue(result.items[0].needsReview)
        XCTAssertNil(result.items[0].organization.dueDate)
        XCTAssertNil(result.items[0].organization.reminderDate)
        XCTAssertEqual(result.items[0].organization.temporalIntent.kind, .none)
        XCTAssertTrue(result.items[0].analysisText.contains("November 18"))
        XCTAssertTrue(result.items[0].analysisText.contains("November 20"))
        XCTAssertFalse(result.items[1].needsReview)
        XCTAssertEqual(result.items[1].organization.temporalIntent.day, CalendarDay(year: 2026, month: 11, day: 23))
    }

    func testSeparateCurrentDateOwnersRemainUsableWithTheirOwnFamilyRoles() throws {
        let result = try XCTUnwrap(read(datedFamily, [row([0]), row([1, 2]), row([3, 4])]))
        XCTAssertEqual(result.items.count, 3)
        for (item, day) in zip(result.items, [18, 20, 23]) {
            XCTAssertFalse(item.needsReview)
            XCTAssertEqual(item.organization.temporalIntent.day, CalendarDay(year: 2026, month: 11, day: day))
            XCTAssertNil(item.organization.reminderDate)
        }
        XCTAssertTrue(result.items[0].analysisText.contains("stepmother’s sister"))
        XCTAssertTrue(result.items[1].analysisText.contains("their brother"))
        XCTAssertTrue(result.items[2].analysisText.contains("Umi’s shoulder rest to my niece"))
    }

    func testUndatedIndependentActionCannotBorrowAnotherActionsDate() throws {
        let result = try XCTUnwrap(read("Call Mom tomorrow. Wash the apron.", [row([0, 1])]))
        XCTAssertTrue(result.items[0].needsReview)
        XCTAssertNil(result.items[0].organization.dueDate)
        XCTAssertEqual(result.items[0].organization.temporalIntent.kind, .none)
    }

    func testSameClockAndHistoricalContextDoNotCreateAnUnnecessaryHold() throws {
        for source in ["Call Mom tomorrow. Wash the apron tomorrow.",
                       "Call Mom tomorrow. The recital was on November 20.",
                       "Call Mom tomorrow. Mom said, \"The recital is on November 20.\""] {
            let result = try XCTUnwrap(read(source, [row(Array(RuntimeIndexedSource(source).units.indices))]), source)
            XCTAssertFalse(result.items[0].needsReview, source)
            XCTAssertEqual(result.items[0].organization.temporalIntent.day, CalendarDay(year: 2026, month: 11, day: 17), source)
        }
    }

    func testReportedContextCannotOverrideALaterOwnVoiceWithdrawal() {
        let source = "Call Mom tomorrow. Mom said, \"The recital is on November 20.\" I do not want to call Mom."
        let units = RuntimeIndexedSource(source)
        XCTAssertNil(RuntimeFoundationInterpreter.currentActionWithQuotedContext(Array(units.units.indices), units: units))
        if let result = read(source, [row(Array(units.units.indices))]) {
            XCTAssertTrue(result.items.allSatisfy { $0.needsReview || !$0.organization.itemType.isActionable })
        }
    }

    func testQuotedRequestCannotSupplyAnInventedCurrentActionOrItsClock() {
        let source = "Mom said, \"Call Dad tomorrow at 9 AM.\" Dad said, \"The recital is on November 20.\""
        let units = RuntimeIndexedSource(source)
        XCTAssertNil(RuntimeFoundationInterpreter.currentActionWithQuotedContext(Array(units.units.indices), units: units))
        if let result = read(source, [row(Array(units.units.indices))]) {
            XCTAssertTrue(result.items.allSatisfy { $0.needsReview || !$0.organization.itemType.isActionable })
            XCTAssertTrue(result.items.allSatisfy { $0.organization.reminderDate == nil })
        }
    }
}

@available(iOS 26.4, *)
final class RuntimeSpokenIntentionLabelTests: XCTestCase {
    private var calendar: Calendar { var c = Calendar(identifier: .gregorian); c.timeZone = TimeZone(identifier: "America/Toronto")!; return c }
    private var reference: Date { ISO8601DateFormatter().date(from: "2026-11-16T14:00:00Z")! }
    private let source = "first job weigh the kite frame tomorrow keep the fact that Rivo supplied the fabric but the seam repair date is unknown middle job buy four coils of orange twine for Jani no make Jani three coils and add two coils for me those allocations stay separate another middle note the field gate sign is coded AIR-0006 do not turn it into a date last job tell Luma to ask their uncle about the launch whistle on November 24 i am contacting Luma not that uncle no timed alerts"
    private func read(_ text: String, _ rows: [RuntimeFoundationInterpreter.IndexedItem]) -> ThoughtExtractionResult? {
        RuntimeFoundationInterpreter.validateIndexed(.init(items:rows),source:text,units:RuntimeIndexedSource(text),referenceDate:reference,calendar:calendar,rules:.init(items:[],method:.rules),context:.empty)
    }
    func testExplicitOwnLabelsSeparateTheCompleteUnpunctuatedCapture() {
        let units = RuntimeIndexedSource(source)
        XCTAssertEqual(units.units.count,5)
        XCTAssertTrue(RuntimeProposalGuard.covers(source,quotes:units.units.map(\.text)))
        if units.units.count == 5 {
            XCTAssertTrue(units.units[0].text.hasPrefix("first job weigh"))
            XCTAssertTrue(units.units[1].text.hasPrefix("keep the fact"))
            XCTAssertTrue(units.units[2].text.hasPrefix("middle job buy"))
            XCTAssertTrue(units.units[3].text.hasPrefix("another middle note"))
            XCTAssertTrue(units.units[4].text.hasPrefix("last job tell"))
            XCTAssertTrue(units.units[4].text.hasSuffix("no timed alerts"))
        }
    }
    func testReportedAndQuotedLabelsDoNotBecomeCurrentIntentionBoundaries() {
        let reported = "Nori said first job call Mom tomorrow and last job wash the apron."
        XCTAssertEqual(RuntimeIndexedSource(reported).units.count,1)
        let quoted = "first job copy the label \"middle job buy four coils last job call Dad\" tomorrow"
        XCTAssertEqual(RuntimeIndexedSource(quoted).units.count,1)
        XCTAssertTrue(RuntimeProposalGuard.covers(quoted,quotes:RuntimeIndexedSource(quoted).units.map(\.text)))
    }
    func testWholeCaptureCannotBecomeOneAcceptedTaskWithFirstJobsClock() {
        let units = RuntimeIndexedSource(source)
