    func testCorrectedCurrentAllocationUsesOnlyItsCurrentBeneficiariesAndProduct() throws {
        let text = "Buy four coils of orange twine for Jani no make Jani three coils and add two coils for me those allocations stay separate"
        let entries = try XCTUnwrap(RuntimeAllocationReading.expected(text))
        XCTAssertEqual(entries.map(\.quantity),[3,2])
        XCTAssertEqual(entries.map(\.owner),["jani","me"])
        XCTAssertEqual(entries.map(\.object),["orange twine","orange twine"])
        for wrong in [text.replacingOccurrences(of:"make Jani",with:"make Nori"),text + " unless Mom agrees",text.replacingOccurrences(of:"three coils",with:"three cartons")] {
            XCTAssertNil(RuntimeAllocationReading.expected(wrong))
        }
