    func testSeparateCurrentRowsKeepBothDatesAndTheCompleteCorrectedList() throws {
        let units = RuntimeIndexedSource(source)
        XCTAssertEqual(units.units.count,5)
        guard units.units.count == 5 else { return }
        let purposes: [RuntimeFoundationInterpreter.Purpose] = [.task,.note,.shopping,.note,.task]
        var rows = purposes.indices.map { RuntimeFoundationInterpreter.IndexedItem(evidence:[$0],purpose:purposes[$0],currentMeaning:"",directContact:"",needsReview:false) }
        rows[2].currentMeaning = "Buy 3 coils of orange twine for Jani and 2 coils for me"
        let result = try XCTUnwrap(read(source,rows))
        XCTAssertEqual(result.items.count,5)
        XCTAssertTrue(result.items.allSatisfy { !$0.needsReview })
        XCTAssertEqual(result.items[0].organization.dueDate,ISO8601DateFormatter().date(from:"2026-11-17T05:00:00Z"))
        XCTAssertEqual(result.items[4].organization.dueDate,ISO8601DateFormatter().date(from:"2026-11-24T05:00:00Z"))
        XCTAssertEqual(result.items[2].organization.itemType,.shopping)
        XCTAssertEqual(result.items[1].organization.itemType,.note)
        XCTAssertEqual(result.items[3].organization.itemType,.note)
        XCTAssertTrue(result.items.allSatisfy { $0.organization.reminderDate == nil })
        XCTAssertTrue(RuntimeProposalGuard.covers(source,quotes:result.items.map(\.sourceQuote)))
        XCTAssertTrue(result.items[4].analysisText.contains("their uncle") == true)
        XCTAssertTrue(result.items[3].rawQuote.contains("AIR-0006"))
    }
    func testHeldCorrectionPreservesIndependentlyClearFirstAndLastIntentions() throws {
        let units = RuntimeIndexedSource(source)
        guard units.units.count == 5 else { return XCTFail("explicit current sequence was not indexed") }
        let purposes: [RuntimeFoundationInterpreter.Purpose] = [.task,.note,.shopping,.note,.task]
        let rows = purposes.indices.map { RuntimeFoundationInterpreter.IndexedItem(evidence:[$0],purpose:purposes[$0],currentMeaning:"",directContact:"",needsReview:$0 == 2) }
        let result = try XCTUnwrap(read(source,rows))
        XCTAssertEqual(result.items.count,5)
        XCTAssertTrue(result.items[2].needsReview)
        XCTAssertFalse(result.items[0].needsReview)
        XCTAssertFalse(result.items[4].needsReview)
        XCTAssertTrue(result.items[2].rawQuote.contains("no make Jani three coils"))
        XCTAssertTrue(result.items[2].rawQuote.contains("add two coils for me"))
    }
    func testReportedLaterLabelRetainsItsOriginalMatrix() {
        let text = "first job call Mom tomorrow. Nori said middle job wash the apron tomorrow. last job call Dad Friday."
        let units = RuntimeIndexedSource(text)
        XCTAssertEqual(units.units.count,3)
        XCTAssertFalse(units.units.contains { $0.text.hasPrefix("middle job") })
        XCTAssertTrue(units.units.contains { $0.text.hasPrefix("Nori said middle job") })
