    func testExplicitSpokenIdeaDoesNotBecomeAPurchase() throws {
        let text = "first job call Mom. second idea buy a sailboat."
        let rows: [RuntimeFoundationInterpreter.IndexedItem] = [
            .init(evidence:[0],purpose:.task,currentMeaning:"",directContact:"",needsReview:false),
            .init(evidence:[1],purpose:.idea,currentMeaning:"",directContact:"",needsReview:false)]
        let result = try XCTUnwrap(read(text,rows))
