        XCTAssertNil(RuntimeAllocationReading.expected(prefix + "me and call Dad Friday"))
        XCTAssertEqual(try XCTUnwrap(RuntimeAllocationReading.expected(prefix + "my aunt")).last?.owner,"my aunt")
    }
    func testOrphanObjectsRemainUnresolvedWithAnyTimeAdjunct() {
        for own in ["I will do that on November 18.","I will finish it next week."] {
            let text = own + " Mom said, \"Call Dad November 20.\""
            let units = RuntimeIndexedSource(text)
            XCTAssertNil(RuntimeFoundationInterpreter.currentActionWithQuotedContext(Array(units.units.indices),units:units),own)
        }
    }
    func testEachClearLabelledIntentionRemainsIndependentlyReadable() {
        let units = RuntimeIndexedSource(source)
        let purposes: [RuntimeFoundationInterpreter.Purpose] = [.task,.note,.shopping,.note,.task]
        guard units.units.count == purposes.count else { return XCTFail("source units mismatch") }
        for index in units.units.indices {
            let text = units.units[index].text
            let row = RuntimeFoundationInterpreter.IndexedItem(evidence:[0],purpose:purposes[index],currentMeaning:index == 2 ? "Buy 3 coils of orange twine for Jani and 2 coils for me" : "",directContact:"",needsReview:false)
            let result = read(text,[row])
            XCTAssertNotNil(result,"independent current unit \(index) rejected")
            print("SOURCE21_SYNTHETIC_UNIT index=\(index) accepted=\(result != nil) today=\(ActionabilityReader.read(RuntimeFoundationActionShape.body(text)).belongsOnToday) allocation=\(RuntimeAllocationReading.expected(RuntimeFoundationActionShape.body(text)) != nil)")
        }
    }
    func testNominalTaskDeclarationsCannotShareDifferentClocks() {
        let text = "My task is to call Mom November 18. My task is to call Dad November 20."
        let units = RuntimeIndexedSource(text)
        let row = RuntimeFoundationInterpreter.IndexedItem(evidence:Array(units.units.indices),purpose:.task,currentMeaning:"",directContact:"",needsReview:false)
        XCTAssertEqual(RuntimeFoundationInterpreter.conflictingCurrentClockRows([row],units:units,referenceDate:reference,calendar:calendar),[0])
    }
    func testFactRetentionCannotHideAnIndependentCurrentCommand() {
        let text = "first job weigh the frame tomorrow keep the fact that Nori supplied the fabric and call Dad Friday"
        let units = RuntimeIndexedSource(text)
        guard units.units.count == 2 else { return XCTFail("current fact boundary not retained") }
        let fact = units.units[1].text
        XCTAssertEqual(RuntimeFoundationActionShape.body(fact),fact)
        let result = read(text,[.init(evidence:[0],purpose:.task,currentMeaning:"",directContact:"",needsReview:false),
                              .init(evidence:[1],purpose:.note,currentMeaning:"",directContact:"",needsReview:false)])
        XCTAssertFalse(result?.items.allSatisfy { !$0.needsReview } == true)
    }
    func testIdeaHeadingCannotHideAnotherOwnCommandOrAdoption() {
        for body in ["buy a sailboat and call Mom tomorrow","buy a sailboat but I will call Mom tomorrow"] {
            let text = "first job wash the apron. second idea " + body
            let result = read(text,[.init(evidence:[0],purpose:.task,currentMeaning:"",directContact:"",needsReview:false),
                                  .init(evidence:[1],purpose:.idea,currentMeaning:"",directContact:"",needsReview:false)])
            XCTAssertFalse(result?.items.allSatisfy { !$0.needsReview } == true,body)
        }
    }
