@available(iOS 26.4, *)
final class RuntimeAccountOwnershipTests: XCTestCase {
    private let account = "Keep one Memory about the rehearsal. Nori’s panel smelled of salt after the room flooded. Mom said, \"Call Dad tomorrow.\" I have not adopted that request. Questions I retain here are who carved the bracket and whether the base is clay. A possible return to that room remains an unchosen idea."
    private func read(_ text: String, override: [Int:RuntimeAccountOwnership.Disposition]? = nil) -> ThoughtExtractionResult? {
        let units = RuntimeIndexedSource(text)
        let roles = override ?? Dictionary(uniqueKeysWithValues:units.units.indices.map { ($0,RuntimeAccountOwnership.Disposition.fact) })
        return RuntimeAccountOwnership.validate(roles,source:text,units:units,rules:.init(items:[],method:.rules))
    }
    func testNovelFactualAccountKeepsLiteralOwnershipQuestionsAndDoubt() throws {
        let result = try XCTUnwrap(read(account))
        let item = try XCTUnwrap(result.items.first)
        XCTAssertEqual(result.items.count,1)
        XCTAssertEqual(item.rawQuote,account)
        XCTAssertEqual(item.sourceQuote,account)
        XCTAssertEqual(item.analysisText,account)
        XCTAssertEqual(item.organization.itemType,.note)
        XCTAssertNil(item.suggestedTitle)
        XCTAssertNil(item.organization.personName)
        XCTAssertNil(item.organization.dueDate)
        XCTAssertNil(item.organization.reminderDate)
        XCTAssertNil(item.organization.locationIntent)
        XCTAssertNil(item.organization.recurrenceRule)
        XCTAssertEqual(item.organization.temporalIntent.kind,.none)
        XCTAssertFalse(item.needsReview)
        XCTAssertTrue(result.operations.isEmpty)
    }
    func testFalselyPositiveFactMapsCannotHideCurrentIntentions() {
        let opposites = [
            account + " Call Mom tomorrow.",
            "Keep one Memory about the panel. It smelled of salt because I will call Mom tomorrow.",
            "Keep one Memory about the panel. I want to retain the account and I will varnulate the frame tomorrow.",
            "Keep one Memory about the panel. My task is to call Mom tomorrow.",
            "Keep one Memory about the panel. Text Mom \"Call Dad tomorrow.\"",
            "Keep one Memory about the panel. Remind me tomorrow at 8 AM not to leave paint by the heater.",
            "Keep one Memory about the panel. Cancel my saved \"Return the panel\" task.",
            "Keep one Memory about the panel. I should not return the panel.",
            "Keep one Memory about the panel and call Mom tomorrow.",
            account + " Actually, I agree to do it tomorrow."
        ]
        for text in opposites { XCTAssertNil(read(text),text) }
    }
    func testAttributionAndNonadoptionDoNotAuthorizeTheQuotedCommand() throws {
        let text = "Keep one Memory about Nori’s suggestion. Nori said, \"Call Mom tomorrow.\" I have not adopted that request."
        let result = try XCTUnwrap(read(text))
        XCTAssertTrue(result.items.allSatisfy { !$0.organization.itemType.isActionable && $0.organization.reminderDate == nil })
        XCTAssertNil(read(text + " I will do it tomorrow."))
    }
    func testMissingForeignAndUnresolvedDispositionNeverCreateANote() {
        let units = RuntimeIndexedSource(account)
        var roles = Dictionary(uniqueKeysWithValues:units.units.indices.map { ($0,RuntimeAccountOwnership.Disposition.fact) })
        roles.removeValue(forKey:0);XCTAssertNil(read(account,override:roles))
        roles[0] = .fact;roles[units.units.count] = .fact;XCTAssertNil(read(account,override:roles))
        roles.removeValue(forKey:units.units.count);roles[0] = .unresolved;XCTAssertNil(read(account,override:roles))
        roles[0] = .currentIntent;XCTAssertNil(read(account,override:roles))
        XCTAssertNil(read("The panel smelled of salt after the room flooded."))
    }
    func testARecordingModalCannotExcuseALaterOwnCommitment() {
        XCTAssertNotNil(read("Keep one Memory about the panel. I want to retain the story so I can understand it."))
        XCTAssertNil(read("Keep one Memory about the panel. I want to retain the story because I will call Mom tomorrow."))
    }
    func testWholeCurrentMatrixCannotHideAQuotedMessagePayload() {
        XCTAssertNil(read("Keep one Memory about the panel. Send \"Call Dad tomorrow\" to Mom tomorrow."))
    }
    func testUnresolvedCurrentDirectiveCannotBorrowReportedPermission() {
        XCTAssertNil(read("Keep one Memory about Nori’s request. Nori said, \"Call Mom tomorrow.\" I have not adopted that request. Actually, do that tomorrow."))
    }
    func testInputFirstLongMemorySourcesRemainLiteralWithSuppliedOwnershipMap() throws {
        let sources = [
            "Keep the following as one Memory about the harbour panorama pavilion, with its history, people and uncertainties together. I am not giving myself jobs. The pavilion mattered to me because it let visitors compare the harbour seen through a curved glass panel with the same harbour drawn as a flat silhouette. It was intended as a conversation about perception, rather than a scientific instrument. The words panorama pavilion were chosen by Ivara; choosing that name does not mean she designed the optics. The curved panel was made by Talis, and the stand was built by Liora from salvaged timber.\n\nTalis still owns the curved panel. We borrowed it for the demonstration, and borrowing it did not transfer ownership to Liora or to me. The wooden transport case belongs to our neighbourhood association. I held that case during the first exhibition, but possession at that event is not evidence that I own it personally. The small reference prism was donated by Qasem and now belongs to the association. I want these distinctions retained because the old captions blurred who made, owned, carried and donated the different parts. None of this account asks anyone to return a part today.\n\nThe outdoor trial happened on June 8, 2019, before the pavilion acquired its canvas roof. At that trial the projected skyline leaned slightly toward the harbour wall. The indoor display happened the following September, after Liora raised the left side of the stand. The September display looked straighter, but that observation does not prove the adjustment was the only cause. Ivara says the floor at the indoor venue was also more level. I did not measure either floor, so I should not turn her explanation into a confirmed conclusion. These dates describe past events and are not reminders.\n\nWe had four clear samples and one cloudy sample. Those were demonstration samples already in the case, not amounts to purchase or pack. Two clear samples had rounded corners and the other two had square corners. The cloudy one had a pale crescent near its lower edge. Qasem photographed that crescent before the samples reached the venue, which means it was present before our display. The photograph does not reveal whether the crescent came from casting, cleaning or earlier handling. It would be misleading to say that a particular volunteer damaged the sample merely because they carried the case.\n\nThe old inventory label on the transport case reads PAN-0008-K. The leading zeros and final letter are part of the identifier. The label is attached to the case, not to the curved panel inside it and not to the reference prism. Vey copied the label into the notebook, while Nara has not checked that copy against the original. The notebook also says amber lining, which refers to the colour of the felt lining rather than to the material of the optical panel. These details should remain connected to the objects they describe instead of being distributed across every item in the account.\n\nDuring the first planning conversation, Liora said, \"Replace the cloudy sample before another display.\" I am recording that advice, not adopting it as a current task. Talis answered that the cloudy sample helped visitors notice how imperfect material changes a view. Those are different opinions from different people. Neither statement settles what should happen to the sample. My recollection is that we eventually displayed it beside a clear sample, but I cannot find the final layout photograph, so the exact arrangement remains uncertain. The account should retain the disagreement rather than inventing a unanimous decision.\n\nThree questions belong inside this Memory: who wrote the first sample caption, whether the case originally had a locking clasp, and why the indoor sketch shows a shorter harbour wall. I am preserving the questions for future reference, not choosing a person to ask or claiming that an answer is missing from someone’s work. I also once imagined a second pavilion using coloured shadows. That remains an uncommitted possibility within this history, with no date or permission to build it. What I want to find later is this connected account of the pavilion, not a checklist created from its verbs.",
            "Save this as one coherent Memory of the lantern puppet production called The Quiet Orchard. I am keeping the account so I can understand how the production developed, not asking for another performance to be arranged. The central image was a child finding an orchard by following the light carried by a moth. At the early workshop, the moth was represented by a paper silhouette on a long wire. By the final performance it was a small lantern puppet with a fabric wing. Those were successive versions of the same character, not two separate characters who appeared together.\n\nThe story outline was written by Edda. Sorel designed the moth’s wing, and my cousin Lune made the first paper silhouette. Edda did not make the wing merely because she wrote the story. Lune is my cousin, while the child narrator was performed by Kest, who is Lune’s partner. Kest is not my partner. These relationships are useful context for the production record and do not resolve anyone to a telephone contact. I operated the dimmer at the final performance. That is a completed historical responsibility, not a fresh task to operate it now.\n\nThe wing material belonged to Sorel and was lent to the group. The lantern housing belonged to the theatre cooperative. We borrowed a narrow rehearsal table from Nivan, and it remained Nivan’s table even while Kest carried it between rooms. Four small counterweights were kept in the lantern housing, but only one was used during the final scene. The other three were stored as existing spares. Those counts describe the arrangement at the time and do not request buying, packing or discarding any weights. Carrying, using and owning should stay distinct in the account.\n\nThe first rehearsal was on February 12, 2020. At that rehearsal the paper moth crossed the screen too quickly for the narrator’s last line. Sorel recalls that Edda shortened the line the following week, while Edda recalls slowing the crossing instead. We have no dated rehearsal video that settles which change came first. Both recollections should remain attributed and uncertain. The performance on March 7, 2020 used the lantern moth and included a longer pause beside the orchard gate. The historical pause is a staging detail, not an instruction for an app timer or a future reminder.\n\nA notebook drawing labels the lantern housing QO-0012-L. The numeral twelve in that code is not the number of puppets, weights or tickets. Arven copied the code from a fading tag, and I have not checked the final letter myself. A separate sketch calls the wing olive, which describes its colour under rehearsal lighting. The fabric was not necessarily olive coloured in daylight. We should not rewrite that observation as a permanent material specification. The housing code belongs to the housing, while the uncertain colour description belongs to the wing; the rehearsal table inherits neither detail.\n\nDuring a discussion after the show, Nivan said, \"Cut the final orchard scene and sell the old lantern.\" I did not agree to either suggestion, and the conversation was not an instruction to act. Edda preferred keeping the final scene because the quiet pause gave the narrator room to breathe. Kest thought the pause had been too long, but Kest was describing their experience rather than volunteering to rewrite the production. These are three different perspectives. The account should not assign a decision to the whole group merely because those people spoke in the same room.\n\nThere are still unanswered reference questions about who painted the gate silhouette, whether the original wire was spring steel, and which recording contains the clearest final line. I am not nominating a person to investigate them. An idea of presenting the story with projected rain came up later, but nobody adopted it or scheduled another version. I want that possibility retained within the production’s history rather than turned into a new project. The reason this Memory matters is that its changes grew from conversations, uncertain recollections and shared materials. A shortened task list would lose who contributed what and why the final image felt quiet.",
            "Keep one Memory about the resonant clay wall we tried at the coastal arts room. This is an account of that experiment and the way people interpreted it, not a set of instructions for building a new wall. The idea was to let a visitor touch a hollow clay form and hear how its note differed from the form beside it. We used the word wall because the forms were arranged vertically, although the first version stood on a freestanding timber rack. It was not fixed into the building structure, and describing it as a wall should not erase that distinction.\n\nMy great-aunt Sava suggested arranging the forms by touch rather than by colour. Eren made the rounded forms and Pelin made the angular ones. Sava suggested the arrangement but did not make every object. My partner’s brother, Varo, built the rack; Varo is not my own brother. I drew the first location diagram and carried the display cards to the room. Those contributions are completed history. The rounded forms still belong to Eren, and the angular forms still belong to Pelin. The rack belongs to the arts association, which paid for its timber before our experiment.\n\nThere were six rounded forms and four angular forms at the first trial. Two rounded forms had shallow ridges, while the other four were smooth. One angular form had a narrow opening that produced a softer note than its neighbours. The softer sound did not prove the form was broken. Varo thought the opening was partly blocked, but Pelin thought the clay wall was thicker there. Nobody cut the form open to compare those explanations. I want the disagreement remembered without choosing a cause for them, and without turning the trial counts into a request to buy or make more forms.\n\nThe trial took place on April 16, 2021, during a small afternoon open studio. We moved the rack away from the window halfway through because listeners found the sunlight distracting. Sava recalls that the softer form became easier to hear after the move. Eren believes fewer people were talking at that moment. Both observations may be relevant, but we did not record room noise or sound levels. It would overstate the evidence to say the new position improved the acoustics. The day and afternoon describe an event that already happened, not a future appointment or notification.\n\nThe rack’s handwritten tag reads SOUND-0004-R. Maira transcribed it onto the display sheet; Farun has not checked the transcription. The number four is part of the rack identifier and is not a count of angular forms, even though that separate count was also four. A blue dot on one rounded form marks Eren’s original test piece. That dot is not a shared mark on all the rounded forms and does not indicate association ownership. The tag, test mark and trial quantities need to stay attached to the right objects because their similar numbers once confused the exhibit notes.\n\nAfter the trial, Farun said, \"Replace the quiet form before the next opening.\" I am preserving that suggestion as Farun’s words, not agreeing to replace anything. Pelin wanted the quiet form left in the sequence because the contrast encouraged visitors to listen more closely. Sava wondered whether a cloth backdrop might help, but she did not commit to making one. Nobody chose a new version or scheduled another opening. The quiet form remained in Pelin’s possession after the trial, which is a statement of possession and ownership in that historical account, not a return task for me.\n\nQuestions worth retaining within this Memory are who wrote the final touch instructions, whether the rack feet were level on the studio floor, and which rounded form was used in the publicity photograph. I have not picked a person to ask or claimed that those details are anybody’s unfinished job. A possible outdoor version with sheltered listening alcoves remains only an idea. What I want to recover later is the connected history: different people made, owned, positioned and interpreted the work, and the uncertainty about one quiet note was part of its character. The whole account belongs together even though it contains counts, a code, questions and several people’s opinions.",
            "Save one connected Memory about the neighbourhood tactile route board. I want to retain the story of the board and its sources, including what we do not know, rather than convert the account into errands. The board showed a route from the old cinema to the riverside reading shelter. Its purpose was to compare ways of representing a familiar walk through touch. It was a prototype used in a workshop, not an official navigation aid. Calling it a route board should not imply that anyone certified its accuracy or asked people to rely on it while travelling alone.\n\nSahra chose the two landmarks. My father-in-law’s niece, Nessa, sketched the first outline, so Nessa’s relationship is through my father-in-law and not a daughter of mine. Velin built the cork base, while my own nephew Rafi shaped the raised river line. Nessa owns the original sketch. The neighbourhood centre owns the cork base because Velin donated it after building it. Rafi lent the river strip and still owns that strip. I mounted the workshop captions. Making, donating, lending, carrying and mounting are different contributions, and I want each credited to the person who actually made it.\n\nThe first workshop was on October 3, 2018. We represented the cinema with a triangular block and the reading shelter with a shallow ring. There were nine removable landmark pieces in the storage tray, but only five were used on the first board. Three pieces were brown and six were cream coloured. Those colours do not distinguish owned from borrowed objects. The unused four remained in the tray; that historical count does not mean we need four replacements. The route was shown with two bends, while the sketch contained three, and we never wrote down why the final board differed.\n\nMina recalls that the missing bend was removed to make the board easier to read by touch. Sahra remembers that the cork base was simply too short for Nessa’s first drawing. We have no recording of the decision, and neither account should be presented as confirmed. Nessa later made a longer sketch, but a later sketch does not prove which explanation was right about the earlier board. At a second workshop in December 2018, visitors found the shallow ring difficult to distinguish from the river line. That response concerned the reading-shelter symbol and should not be assigned to the cinema block.\n\nThe centre’s inventory label on the base is WALK-0009-C. Daro copied the label into the workshop book, and Tessa has not verified the final letter. The nine in the identifier is not a promise that nine landmarks appeared on the board. The storage-tray count was separately nine. A red pencil circle on Nessa’s original sketch identifies the proposed shelter position; it is not a stain on the cork base and does not mark every removable piece. The label, circle, quantities and visitor responses belong to different objects, even when a short caption once placed them beside each other.\n\nAfter seeing the second workshop, Tessa said, \"Throw away the ring and buy a taller shelter marker.\" I did not agree to either action, and I am not issuing that quotation as a current instruction. Rafi thought the low ring left more room for exploring the river line. Mina proposed a textured disc as another possibility but did not volunteer to make it. These opinions remained unresolved. Rafi later carried the river strip home because it was his loaned piece, not because the centre had given him ownership of the whole board. The base stayed at the neighbourhood centre.\n\nI want three unanswered questions preserved inside the same account: who wrote the second workshop’s caption, whether the triangular cinema block originally had a rough face, and where the unused cream pieces were stored after December. I am not claiming they are lost or asking a guessed person to find them. A possible board for the hillside route was mentioned much later, but it remains an unchosen idea with no deadline. This Memory should let me revisit the prototype’s connected history, recognise different sources and relationships, and keep its uncertainties visible. A collection of new tasks or unrelated fragments would change what I am trying to preserve."
        ]
        for source in sources {
            guard let result = read(source) else {
                let units = RuntimeIndexedSource(source)
                let vetoes = units.units.enumerated().filter { RuntimeAccountOwnership.hasCurrentIntent($0.element.text) }
                    .map { "u\($0.offset): " + $0.element.text }
                XCTFail("Literal Memory rejected; scoped=\(RuntimeAccountOwnership.scoped(source)) covers=\(RuntimeProposalGuard.covers(source,quotes:units.units.map(\.text))) vetoes=" + vetoes.joined(separator:" | ")); continue
            }
            XCTAssertEqual(result.items.count,1)
            XCTAssertEqual(result.items.first?.rawQuote,source)
            XCTAssertEqual(result.items.first?.analysisText,source)
            XCTAssertEqual(result.items.first?.organization.itemType,.note)
            XCTAssertTrue(result.operations.isEmpty)
            XCTAssertTrue(result.items.allSatisfy { !$0.needsReview && $0.organization.dueDate == nil && $0.organization.reminderDate == nil })
        }
    }

    func testEpistemicAndCognitiveRetentionCannotHideACurrentContinuation() {
        let prefixes = ["I did not measure the floor, so I should not turn her explanation into a confirmed conclusion",
                        "We should not rewrite that observation as a permanent material specification",
                        "What I want to recover later is this connected history",
                        "Keep its uncertainties visible"]
        for prefix in prefixes {
            XCTAssertNotNil(read("Keep one Memory about the panel. " + prefix + "."),prefix)
            XCTAssertNil(read("Keep one Memory about the panel. " + prefix + " and call Mom tomorrow."),prefix)
            XCTAssertNil(read("Keep one Memory about the panel. " + prefix + " because I will varnulate the frame tomorrow."),prefix)
        }
        XCTAssertNil(read("Keep one Memory about the panel. I want the panel moved tomorrow."))
        XCTAssertNil(read("Keep one Memory about the panel. I need the chair painted tomorrow."))
        XCTAssertNil(read("Keep one Memory about the panel. I want the receipt sent to Mom tomorrow."))
        XCTAssertNil(read("Keep one Memory about the panel. Those counts describe the old stock and do not move the boxes tomorrow."))
        XCTAssertNil(read("Keep one Memory about the panel. Alarm for 8 AM tomorrow."))
    }
    func testLaterKnowledgeRetentionHasCurrentLiteralRouting() throws {
        let text = "Keep one Memory about the panel. I want these distinctions retained. I want the disagreement remembered. I want that possibility retained. I want three unanswered questions preserved."
        let units = RuntimeIndexedSource(text)
        let roles = Dictionary(uniqueKeysWithValues:units.units.indices.map { ($0,RuntimeAccountOwnership.Disposition.routing) })
        XCTAssertNotNil(RuntimeAccountOwnership.validate(roles,source:text,units:units,rules:.init(items:[],method:.rules)))
    }
    func testCompactDecisionOwnsCompleteAccountAndPreservesEveryCurrentWord() throws {
        let units = RuntimeIndexedSource(account),rules = ThoughtExtractionResult(items:[],method:.rules)
        let result = try XCTUnwrap(RuntimeAccountOwnership.validateDecision(.retainConnectedMemory,source:account,units:units,rules:rules))
        XCTAssertEqual(result.items.first?.sourceQuote,account);XCTAssertEqual(result.items.first?.analysisText,account)
        XCTAssertEqual(result.items.first?.sourceUnitIDs,Set(SourceUnitLedger(account).words.indices))
        XCTAssertTrue(result.operations.isEmpty);XCTAssertNil(result.items.first?.organization.dueDate)
        for opposite in [account + " I now accept that suggestion.",account + " We’ll call Mom tomorrow.",account + " My own task is to adjust the hinge tomorrow."] {
            XCTAssertNil(RuntimeAccountOwnership.validateDecision(.retainConnectedMemory,source:opposite,units:RuntimeIndexedSource(opposite),rules:rules))
        }
        for decision in [RuntimeAccountOwnership.AccountDecision.containsIndependentCurrentIntent,.unresolved] {
            XCTAssertNil(RuntimeAccountOwnership.validateDecision(decision,source:account,units:units,rules:rules))
        }
        let schema = try XCTUnwrap(RuntimeAccountOwnership.decisionSchema(units))
        let text = String(decoding:try JSONEncoder().encode(schema),as:UTF8.self)
        XCTAssertTrue(text.contains("decision"));XCTAssertFalse(text.contains("u0"))
    }
    func testCompactDecisionRejectsMissingForeignOrInvalidOutput() throws {
        XCTAssertEqual(try RuntimeAccountOwnership.decodeDecision(GeneratedContent(json:#"{"decision":"retainConnectedMemory"}"#)),.retainConnectedMemory)
        for json in [#"{}"#,#"{"decision":"F"}"#,#"{"decision":true}"#,#"{"decision":"retainConnectedMemory","u0":"F"}"#] {
            XCTAssertNil(try RuntimeAccountOwnership.decodeDecision(GeneratedContent(json:json)))
        }
    }
    func testKeyedOwnershipRequiresEveryCurrentIdentifierAndValidCode() throws {
        let units = RuntimeIndexedSource("Keep one Memory about the panel. Nori made it.")
        let good = try GeneratedContent(json:#"{"u0":"R","u1":"F"}"#)
        XCTAssertEqual(try RuntimeAccountOwnership.decode(good,units:units),[0:.routing,1:.fact])
        for json in [#"{"u0":"F"}"#,#"{"u0":"F","u1":"F","u2":"F"}"#,#"{"u0":"F","u1":"Z"}"#,#"{"u0":"F","u1":7}"#,#"{"roles":["routing","fact"]}"#] {
            XCTAssertNil(try RuntimeAccountOwnership.decode(GeneratedContent(json:json),units:units))
        }
        let schema = try XCTUnwrap(RuntimeAccountOwnership.schema(units))
        let serialized = String(decoding:try JSONEncoder().encode(schema),as:UTF8.self)
        XCTAssertFalse(serialized.contains("\"roles\""));XCTAssertTrue(serialized.contains("\"u0\""))
    }

    func testCurrentContinuationAndExistingOwnedFramesCannotBecomeFacts() {
        for text in ["The panel smelled of salt, call Mom tomorrow.",
                     "I want to save this account by emailing it to Mom tomorrow.",
                     "Let’s call Mom tomorrow.","My responsibility is to call Mom tomorrow."] {
            XCTAssertNil(read("Keep one Memory about the panel. " + text),text)
        }
        for text in ["Call records were archived in 2019.","Paint was dry by the end of the workshop."] {
            XCTAssertNotNil(read("Keep one Memory about the panel. " + text),text)
        }
    }

    func testCurrentPracticalCommaAndInflectedPhysicalMeansCannotBecomeFacts() {
        for text in ["The panel smelled of salt, buy milk tomorrow.",
                     "I want to save this account by writing a letter to Mom tomorrow.",
                     "I want my books carried to Mom tomorrow.",
                     "I want that receipt sent to Mom tomorrow.",
                     "I want to save this account by picking up the case tomorrow.",
                     "The tag, test mark and trial quantities need to stay attached to the right objects, buy milk tomorrow."] {
            XCTAssertNil(read("Keep one Memory about the panel. " + text),text)
        }
        for text in ["The panel smelled of salt, paint was dry by the end of the workshop.",
                     "A possible account of writing a letter to Mom remains an unchosen idea.",
                     "The books were carried by Mom in 2019.",
                     "I want each contribution credited to the person who actually made it."] {
            XCTAssertNotNil(read("Keep one Memory about the panel. " + text),text)
        }
    }

}

