#if DEBUG && canImport(FoundationModels)
@available(iOS 26.4, *)
final class RuntimeKnowledgeLoweringSafetyTests: XCTestCase {
    private func indexed(_ source: String, purpose: RuntimeFoundationInterpreter.Purpose,
                         needsReview: Bool = false) -> ThoughtExtractionResult? {
        let units = RuntimeIndexedSource(source)
        let proposal = RuntimeFoundationInterpreter.IndexedProposal(items: [.init(
            evidence: Array(units.units.indices), anchor: "", purpose: purpose,
            currentMeaning: "", directContact: "", needsReview: needsReview)])
        return RuntimeFoundationInterpreter.validateIndexed(proposal, source: source, units: units,
            referenceDate: Date(timeIntervalSince1970: 0), calendar: Calendar(identifier: .gregorian),
            rules: .init(items: [], method: .rules), context: .empty)
    }

    func testReportedImperativeIntroductionKeepsItsMatrixDuringMemoryValidation() throws {
        // The first input is exposed regression material, not fresh gold.
        for source in [
            "A poster said, bring your own chair. That was for an event that has already ended.",
            "Mira said, bring your own cup.",
            "The message says, carry a torch.",
            "A poster said bring your own chair.",
        ] {
            let units = RuntimeIndexedSource(source)
            for unit in units.units {
                XCTAssertFalse(RuntimeAccountOwnership.hasCurrentActForReference(unit.text), unit.text)
            }
            let result = try XCTUnwrap(indexed(source, purpose: .note), source)
            XCTAssertEqual(result.items.count, 1, source)
            let item = try XCTUnwrap(result.items.first)
            XCTAssertEqual(item.analysisText, source)
            XCTAssertEqual(item.sourceQuote, source)
            XCTAssertEqual(item.rawQuote, source)
            XCTAssertEqual(item.organization.itemType, .note)
            XCTAssertFalse(item.needsReview)
            XCTAssertNil(item.organization.dueDate)
            XCTAssertNil(item.organization.reminderDate)
            XCTAssertEqual(item.organization.reminderDelivery, .none)
            XCTAssertTrue(result.operations.isEmpty)
        }
    }

    func testReportedIntroductionCannotWaiveIndependentCurrentTailOrEarlierAction() {
        let report = "A poster said, bring your own chair."
        for source in [
            report + " Mail the parcel.",
            "Mail the parcel. " + report,
            report + " Remind me tomorrow at five PM to mail the parcel.",
            "A poster said, bring your own chair, and I will mail the parcel.",
            "A poster said, bring your own chair, and mail the parcel.",
            "A poster said, bring your own chair, arrange a moisture inspection.",
            "A poster said, bring your own chair; remind me tomorrow to mail the parcel.",
            "A poster said, bring your own chair because I need to mail the parcel.",
            "Mira told me to bring a chair.",
            "I said I will bring a chair.",
            "Tell Mira, bring your own chair.",
        ] {
            for purpose in [RuntimeFoundationInterpreter.Purpose.note, .idea] {
                XCTAssertNil(indexed(source, purpose: purpose), source)
            }
        }
    }

    func testReportIntroductionAddsNoUnclosedOrUnknownQuoteAuthority() {
        for source in [
            "A poster said, 'bring your own chair.",
            "A poster said, “bring your own chair.",
        ] {
            XCTAssertTrue(RuntimeAccountOwnership.hasCurrentActForReference(source), source)
            for purpose in [RuntimeFoundationInterpreter.Purpose.note, .idea] {
                XCTAssertNil(indexed(source, purpose: purpose), source)
            }
        }
        let unknown = "‘Bring your own chair.’"
        XCTAssertEqual(QuotedSpeechScope.matrixVoice(in: unknown), .unresolved)
        let rules = ThoughtExtractionEngine.extractWithRules(unknown)
        XCTAssertTrue(rules.items.contains { $0.needsReview }, unknown)
        XCTAssertTrue(rules.operations.isEmpty)
        XCTAssertFalse(rules.items.contains { $0.organization.itemType.isActionable && !$0.needsReview }, unknown)
    }

    func testResolvedMemoryCannotAbsorbPresentOwnedPluralDeclarations() {
        let declaration = "My actual jobs are to count the crates and label the shelves."
        for source in [declaration,
                       "The spare tape is in the drawer. " + declaration,
                       declaration + " The spare tape is in the drawer.",
                       "Dana said, ‘Use the old cartons.’ " + declaration] {
            for purpose in [RuntimeFoundationInterpreter.Purpose.note, .idea] {
                XCTAssertNil(indexed(source, purpose: purpose), source)
            }
        }
        for source in [
            "My actual jobs are to print the label and file the form, but I already printed it.",
            "My actual jobs are to print the label, but I have not already printed it.",
            "My actual jobs are to print the label, but I would already have printed it."
        ] {
            for purpose in [RuntimeFoundationInterpreter.Purpose.note, .idea] {
                XCTAssertNil(indexed(source, purpose: purpose), source)
            }
        }
    }

    func testPluralStatusPlanCannotBeDowngradedByOptionalInterpreter() async throws {
        let reference = Date(timeIntervalSince1970: 1785765600)
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = try XCTUnwrap(TimeZone(identifier: "America/Toronto"))
        let configuration = RuntimeExampleConfiguration(
            libraryURL: URL(fileURLWithPath: "/not-opened-by-plural-source-status.sqlite"),
            allowProposed: false, retrievalEnabled: false)
        let empty = ThoughtExtractionResult(items: [], method: .appleIntelligence)
        for prefix in ["My actual jobs are to print the label and file the form, but I already printed it.",
                       "Our remaining tasks are to wash the bowl, but we have not already washed it."] {
            for tail in ["", " I need to file the label at 230 tomorrow.",
                         " Change my saved dentist reminder so I call Noor instead of Maya."] {
                let source = prefix + tail
                for permitsOperations in [true, false] {
                    let rules = ThoughtExtractionEngine.extractWithRules(source,
                        referenceDate: reference, calendar: calendar, permitsOperations: permitsOperations)
                    XCTAssertTrue(rules.items.contains { $0.rawQuote == prefix && $0.needsReview }, source)
                    let actual = await RuntimeExampleConfiguration.$testConfiguration.withValue(configuration) {
                        await RuntimeExampleInterpreter.$testInterpretation.withValue(empty) {
                            await ThoughtExtractionEngine.extract(source, referenceDate: reference,
                                calendar: calendar, permitsOnDeviceIntelligence: true,
                                permitsOperations: permitsOperations)
                        }
                    }
                    XCTAssertEqual(actual, rules, source)
                    XCTAssertNil(RuleBasedThoughtExtractor.currentNominalStatusPlan(source,
                        referenceDate: reference, calendar: calendar,
                        rules: .init(items: [], method: .rules)), source)
                }
            }
        }
    }

    func testResolvedMemoryCannotAbsorbIndependentImperativeOrReminderInEitherOrder() {
        for source in [
            "The cellar smells damp after rain. Arrange a moisture inspection and save that observation.",
            "The latch rattles in the wind. Please inspect the hinge and keep that observation as a note.",
            "Keep that observation as a note. Arrange a moisture inspection.",
            "The lens is in the crate. Remind me tomorrow to clean it. Save that observation.",
            "Remind me tomorrow to clean the lens. The lens is in the crate; save that observation.",
            "Save one memory. The shelf is loose; tighten the bracket.",
        ] {
            for purpose in [RuntimeFoundationInterpreter.Purpose.note, .idea] {
                XCTAssertNil(indexed(source, purpose: purpose), source)
            }
        }
    }

    func testResolvedIdeaCannotHideUnprovedCurrentNominalTaskStatus() {
        for source in [
            "My one job is to print the label, but I have not already printed it.",
            "My one job is to print the label, but I already printed the invoice.",
            "My one job is to print the label, but I would already have printed it.",
        ] {
            for purpose in [RuntimeFoundationInterpreter.Purpose.note, .idea] {
                XCTAssertNil(indexed(source, purpose: purpose), source)
            }
        }
    }

    func testProvedReferenceContextCannotWaiveSeparateCurrentActionCoverage() {
        let references = [
            "The gnomon was lent by Jessa, and Miro remembers the base being scratched before delivery; nobody has verified that memory. Keep the loan and uncertainty as one account. I am not promising to polish or replace it.",
            "About the community telescope, I keep mixing up who I need to speak to.",
            "Also, I have decided not to buy any more mint.",
            "The existing projector stays with Maya and is not on that list.",
        ]
        for reference in references {
            for action in ["I need to mail the parcel.", "Remind me tomorrow to clean the lens."] {
                let joined = reference.trimmingCharacters(in: .punctuationCharacters)
                    + ", and " + action
                for source in [reference + " " + action, action + " " + reference, joined] {
                    for purpose in [RuntimeFoundationInterpreter.Purpose.note, .idea] {
                        XCTAssertNil(indexed(source, purpose: purpose), source)
                    }
                }
            }
        }
    }

    func testResolvedIdeaStillAcceptsCompleteExplicitNoncommitment() throws {
        let source = "I was thinking of painting little picture labels for the plants rather than writing their names. That could be a nice small project, but it is still an idea. I have not decided to spend a weekend on it."
        let result = try XCTUnwrap(indexed(source, purpose: .idea))
        XCTAssertEqual(result.items.count, 1)
        XCTAssertEqual(result.items.first?.organization.itemType, .idea)
        XCTAssertFalse(result.items.first?.needsReview ?? true)
        XCTAssertNil(result.items.first?.organization.reminderDate)
        XCTAssertTrue(result.operations.isEmpty)
    }

    func testNonadoptionOrReportRetentionCannotHideCommaOrReasonContinuation() {
        for source in [
            "I have not agreed to print the labels, arrange a moisture inspection.",
            "I have not agreed to print the labels, please mail the parcel.",
            "I have not agreed to print the labels, I will mail the parcel tomorrow.",
            "I have not agreed to print the labels, remind me tomorrow to clean the lens.",
            "Keep what Asha said as a note because it is useful, I will mail the parcel tomorrow.",
            "Keep what Asha said as a note because I need to mail the parcel.",
            "I want to keep what Asha said as a note because it is useful, arrange a moisture inspection.",
            "Keep what Asha said as a note because arrange a moisture inspection.",
        ] {
            for purpose in [RuntimeFoundationInterpreter.Purpose.note, .idea] {
                XCTAssertNil(indexed(source, purpose: purpose), source)
            }
        }
    }

    func testCompleteNonadoptionAndRetainedReportRemainResolvedMemory() throws {
        for source in [
            "I have not agreed to print the labels.",
            "I want to keep what Asha said as a note because her memory may matter.",
        ] {
            let result = try XCTUnwrap(indexed(source, purpose: .note), source)
            XCTAssertEqual(result.items.count, 1, source)
            XCTAssertEqual(result.items.first?.organization.itemType, .note, source)
            XCTAssertFalse(result.items.first?.needsReview ?? true, source)
            XCTAssertTrue(result.operations.isEmpty, source)
            XCTAssertNil(result.items.first?.organization.reminderDate, source)
        }
    }

    func testCompleteIdeaRelativeNonadoptionPreservesItsResolvedIdea() throws {
        for source in [
            "An idea for later is a mural made entirely of leaf silhouettes, not something I have agreed to build.",
            "An idea for later is a garden of paper stars, not something I have agreed to make.",
            "An idea for later is a portable bookstand, not something I have agreed to create.",
        ] {
            let result = try XCTUnwrap(indexed(source, purpose: .idea), source)
            XCTAssertEqual(result.items.count, 1, source)
            XCTAssertEqual(result.items.first?.organization.itemType, .idea, source)
            XCTAssertFalse(result.items.first?.needsReview ?? true, source)
            XCTAssertEqual(result.items.first?.sourceQuote, source, source)
            XCTAssertTrue(result.operations.isEmpty, source)
            XCTAssertNil(result.items.first?.organization.reminderDate, source)
        }
    }

    func testIdeaRelativeNonadoptionCannotHideAnotherOwnAction() {
        let idea = "An idea for later is a mural made entirely of leaf silhouettes, not something I have agreed to build"
        for source in [
            idea + ", please mail the parcel.",
            idea + ", arrange a moisture inspection.",
            idea + ", but I have agreed to print the labels.",
            idea + ". I need to mail the parcel.",
            "I need to mail the parcel. " + idea + ".",
            "An idea for later is a mural, and mail the parcel, not something I have agreed to build.",
            "An idea for later is a mural and I will mail the parcel, not something I have agreed to build.",
            "An idea for later is a mural if I will mail the parcel, not something I have agreed to build.",
        ] {
            for purpose in [RuntimeFoundationInterpreter.Purpose.note, .idea] {
                XCTAssertNil(indexed(source, purpose: purpose), source)
            }
        }
    }

    func testCurrentNominalStatusPlanPrecedesOptionalInterpreterAndPreservesWholePlan() async throws {
        let reference = Date(timeIntervalSince1970: 1785765600)
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = try XCTUnwrap(TimeZone(identifier: "America/Toronto"))
        let configuration = RuntimeExampleConfiguration(
            libraryURL: URL(fileURLWithPath: "/not-opened-by-current-source-status.sqlite"),
            allowProposed: false, retrievalEnabled: false)
        // An empty optional interpretation would lose both source and effects.
        // The actual entry point must consume its independently proved plan first.
        let emptyProposal = ThoughtExtractionResult(items: [], method: .appleIntelligence)
        for prefix in [
            "My one job is to print the label, but I already printed it.",
            "Our remaining task is to wash the bowl, but we no longer need to wash it.",
            "My one job is to print the label, but I have not already printed it.",
            "My one job is to print the label, but Maya already printed the invoice.",
        ] {
            for tail in ["", " I need to mail the parcel.",
                         " I need to file the label at 230 tomorrow.",
                         " Change my saved dentist reminder so I call Noor instead of Maya."] {
                let source = prefix + tail
                for permitsOperations in [true, false] {
                    let rules = ThoughtExtractionEngine.extractWithRules(source,
                        referenceDate: reference, calendar: calendar, permitsOperations: permitsOperations)
                    let direct = await RuntimeExampleInterpreter.$testInterpretation.withValue(emptyProposal) {
                        await RuntimeExampleInterpreter.interpret(source, referenceDate: reference,
                            calendar: calendar, context: .empty, configuration: configuration, rules: rules)
                    }
                    XCTAssertEqual(direct, rules, source)
                    let actual = await RuntimeExampleConfiguration.$testConfiguration.withValue(configuration) {
                        await RuntimeExampleInterpreter.$testInterpretation.withValue(emptyProposal) {
                            await ThoughtExtractionEngine.extract(source, referenceDate: reference,
                                calendar: calendar, permitsOnDeviceIntelligence: true,
                                permitsOperations: permitsOperations)
                        }
                    }
                    XCTAssertEqual(actual, rules, source)
                    XCTAssertFalse(actual.items.isEmpty, source)
                    let claims = actual.items.reduce(into: Set<Int>()) { $0.formUnion($1.sourceUnitIDs) }
                        .union(actual.operations.reduce(into: Set<Int>()) { $0.formUnion($1.sourceUnitIDs) })
                    XCTAssertTrue(SourceUnitLedger(source).unownedMeaningfulIDs(claimed: claims).isEmpty, source)
                }
            }
        }
    }

    func testCurrentNominalStatusPlanCannotCertifyArbitraryCallerRules() {
        let source = "My one job is to print the label, but I have not already printed it."
        let calendar = Calendar(identifier: .gregorian), reference = Date(timeIntervalSince1970: 0)
        XCTAssertNil(RuleBasedThoughtExtractor.currentNominalStatusPlan(source,
            referenceDate: reference, calendar: calendar, rules: .init(items: [], method: .rules)))
        let actual = ThoughtExtractionEngine.extractWithRules(source, referenceDate: reference, calendar: calendar)
        XCTAssertNil(RuleBasedThoughtExtractor.currentNominalStatusPlan(source,
            referenceDate: reference, calendar: calendar,
            rules: .init(items: actual.items, operations: actual.operations, method: .appleIntelligence)))
    }

    func testReferenceOnlyDirectiveBindsFactWithoutCreatingEffects() throws {
        for source in [
            "The warranty card has an expiry of February 28, 2027. Save the date as reference only.",
            "The insurance policy expires on November 12. Keep that date as reference only.",
            "The meeting is on Friday. Record this as context only.",
            "Our parking permit has an expiration date of 2027-04-30. Retain that fact as reference only.",
        ] {
            let result = try XCTUnwrap(RuntimeExplicitReferenceScope.interpret(source), source)
            XCTAssertTrue(result.operations.isEmpty, source)
            XCTAssertEqual(result.items.first?.rawQuote, source)
            XCTAssertEqual(result.items.first?.analysisText, source)
            XCTAssertTrue(result.items.allSatisfy {
                $0.organization.itemType == .note && !$0.needsReview
                    && $0.organization.dueDate == nil && $0.organization.reminderDate == nil
                    && $0.organization.reminderDelivery == .none
            }, source)
            XCTAssertEqual(result.items.reduce(into: Set<Int>()) { $0.formUnion($1.sourceUnitIDs) },
                           Set(SourceUnitLedger(source).words.indices))
            XCTAssertNil(indexed(source, purpose: .task), source)
        }
    }

    func testReferenceOnlyScopeCannotEraseSeparateCurrentActionOrQuotedAdoption() {
        for source in [
            "Call the dentist on Monday. Save the date as reference only.",
            "My task is to clean the windows. Keep that as reference only.",
            "The warranty expires in November. Save the date as reference only. Remind me tomorrow to renew it.",
            #"Dana said, "The warranty expires in November. Save the date as reference only." Call Dana tomorrow."#,
            "The warranty expires in November. Remind me tomorrow to save the date as reference only.",
            "The policy expires in November and call Dana. Save the date as reference only.",
            "The policy expires in November please email Dana. Save the date as reference only.",
            "The call Dana policy expires in November. Save the date as reference only.",
            "The policy is active please review it. Record this as context only.",
        ] {
            XCTAssertNil(RuntimeExplicitReferenceScope.interpret(source), source)
        }
        let source = "The warranty expires in November. Save the date as reference only. Remind me tomorrow to renew it."
        XCTAssertNil(indexed(source, purpose: .note), "Retaining the date cannot hide the independent reminder")
    }

    func testOwnNoncreationDirectiveVetoesStaleCreationWithoutSavedOperation() {
        for source in [
            "I should renew the annual pass, no, I checked and it runs until January, so don't make a renewal task.",
            "I need to pay the fee, actually it was waived, so do not create a payment reminder.",
            "I will buy a replacement, but the old one works; don't add a replacement task.",
            "Don't create a task for the warranty expiry.",
        ] {
            XCTAssertTrue(RuntimeCurrentWithdrawal.hasNonCreationDirective(source), source)
            XCTAssertNil(indexed(source, purpose: .task), source)
        }
        for source in [
            #"Dana said, "Don't create a renewal task." I will renew my own pass tomorrow."#,
            "I should renew the pass, and don't forget to make a renewal task.",
            "I should not make a payment until the fee is confirmed.",
            "Do not create a renewal task unless I ask you to.",
        ] {
            XCTAssertFalse(RuntimeCurrentWithdrawal.hasNonCreationDirective(source), source)
        }
    }

    func testScopedReferenceAndNoncreationVetoPreserveIndependentActionOwners() throws {
        let cases: [(String, [Int], [Int], Bool)] = [
            ("The policy expires in November. Save the date as reference only. Remind me tomorrow to renew the policy.", [0,1], [2], false),
            ("I should renew the pass, no, it is valid, so don't make a renewal task. I need to wash the bowl.", [0], [1], true),
        ]
        for (source, memoryIDs, actionIDs, held) in cases {
            let units = RuntimeIndexedSource(source)
            let note = RuntimeFoundationInterpreter.IndexedItem(evidence: memoryIDs, anchor: "",
                purpose: .note, currentMeaning: "", directContact: "", needsReview: held)
            let task = RuntimeFoundationInterpreter.IndexedItem(evidence: actionIDs, anchor: "",
                purpose: .task, currentMeaning: "", directContact: "", needsReview: false)
            let result = try XCTUnwrap(RuntimeFoundationInterpreter.validateIndexed(.init(items: [note,task]),
                source: source, units: units, referenceDate: Date(timeIntervalSince1970: 0),
                calendar: Calendar(identifier: .gregorian), rules: .init(items: [], method: .rules), context: .empty), source)
            XCTAssertTrue(result.operations.isEmpty, source)
            XCTAssertTrue(result.items.contains { $0.organization.itemType.isActionable && !$0.needsReview }, source)
            XCTAssertTrue(result.items.contains { !$0.organization.itemType.isActionable }, source)
            XCTAssertTrue(SourceUnitLedger(source).unownedMeaningfulIDs(after: result.items).isEmpty, source)
        }
    }

    func testModeledKnowledgeCannotHideOwnedActionsOrAdoption() {
        let sources = ["Save one Memory. My own task is to adjust the hinge tomorrow.",
            "Save one Memory. Our actual tasks are to recalibrate the sensor and varnulate the frame tomorrow.",
            "Save one account of the rehearsal. The scene was too long. We’ll shorten it tomorrow.",
            "Save one account: Nivan said, \"Cut the scene.\" I agreed.",
            "Save one connected Memory. Cancel only the alert on my saved rehearsal reminder; keep its due day.",
            "Save one Memory. Return Evin’s lens to my partner after Rhea confirms the repair.",
            "About the telescope, I keep mixing up who I need to speak to. Call Mom tomorrow.",
            "About the telescope, I keep mixing up who I need to speak to. My own task is to adjust the hinge tomorrow."]
        for source in sources {
            let units = RuntimeIndexedSource(source)
            let proposal = RuntimeFoundationInterpreter.IndexedProposal(items:[.init(evidence:Array(units.units.indices),anchor:"",purpose:.note,currentMeaning:"",directContact:"",needsReview:false)])
            let reading = RuntimeFoundationInterpreter.validateIndexed(proposal,source:source,units:units,
                referenceDate:Date(timeIntervalSince1970:0),calendar:Calendar(identifier:.gregorian),rules:.init(items:[],method:.rules),context:.empty)
            XCTAssertTrue(reading == nil || reading!.items.allSatisfy { $0.needsReview },source)
        }
    }
}
