#if DEBUG
@MainActor
final class RuntimeCandidateDiversityTests: XCTestCase {
    struct Row {
        let id: String
        let blueprint: String
        let shape: String
        var words = "quasar"
        var aliases: [String] = []
        var eligible = true
        var payloadID: String? = nil
    }
    // Synthetic selector controls clone a full reviewed packet solely to keep
    // decoding realistic. These rows are never approval records or app assets.
    private func fixture(_ rows: [Row]) async throws -> URL {
        var configuration = try XCTUnwrap(RuntimeExampleTestFixtures.reviewed)
        configuration.manualReferenceIDs = ["SIR1-316351"]
        let templates = try await RuntimeExampleLibrary.shared.select("synthetic selector control",configuration:configuration)
        let template = try XCTUnwrap(templates.first)
        let original = try XCTUnwrap(JSONSerialization.jsonObject(with:Data(template.payload.utf8)) as? [String:Any])
        let url = FileManager.default.temporaryDirectory.appendingPathComponent("selector-control-" + UUID().uuidString + ".sqlite")
        var opened: OpaquePointer?
        XCTAssertEqual(sqlite3_open(url.path,&opened),SQLITE_OK)
        let db = try XCTUnwrap(opened); defer { sqlite3_close(db) }
        XCTAssertEqual(sqlite3_exec(db,"CREATE TABLE examples(rowid INTEGER PRIMARY KEY,id TEXT UNIQUE,blueprint TEXT,composition_key TEXT,approved INTEGER,payload BLOB); CREATE VIRTUAL TABLE search USING fts5(utterance,mechanism);",nil,nil,nil),SQLITE_OK)
        for row in rows {
            var object = original
            object["id"] = row.payloadID ?? row.id
            object["provenance"] = ["blueprint":row.blueprint]
            object["rule_ids"] = row.aliases
            object["composition_key"] = row.shape
            object["approval"] = ["production_eligible":row.eligible,"status":"synthetic_filter_control"]
            let raw = try JSONSerialization.data(withJSONObject:object,options:[.sortedKeys])
            var compressed = Data(count:Int(compressBound(uLong(raw.count))))
            var length = uLongf(compressed.count)
            let compression = compressed.withUnsafeMutableBytes { out in raw.withUnsafeBytes { input in
                compress2(out.bindMemory(to:Bytef.self).baseAddress,&length,input.bindMemory(to:Bytef.self).baseAddress,uLong(raw.count),Z_BEST_SPEED)
            }}
            XCTAssertEqual(compression,Z_OK); compressed.count = Int(length)
            var statement: OpaquePointer?
            XCTAssertEqual(sqlite3_prepare_v2(db,"INSERT INTO examples(id,blueprint,composition_key,approved,payload) VALUES(?,?,?,1,?)",-1,&statement,nil),SQLITE_OK)
            let insert = try XCTUnwrap(statement)
            let transient = unsafeBitCast(-1,to:sqlite3_destructor_type.self)
            for (i,value) in [row.id,row.blueprint,row.shape].enumerated() {
                XCTAssertEqual(value.withCString { sqlite3_bind_text(insert,Int32(i+1),$0,-1,transient) },SQLITE_OK)
            }
            XCTAssertEqual(compressed.withUnsafeBytes { sqlite3_bind_blob(insert,4,$0.baseAddress,Int32(compressed.count),transient) },SQLITE_OK)
            XCTAssertEqual(sqlite3_step(insert),SQLITE_DONE); sqlite3_finalize(insert)
            let rowID = sqlite3_last_insert_rowid(db)
            XCTAssertEqual(sqlite3_prepare_v2(db,"INSERT INTO search(rowid,utterance,mechanism) VALUES(?,?, '')",-1,&statement,nil),SQLITE_OK)
            let search = try XCTUnwrap(statement)
            XCTAssertEqual(sqlite3_bind_int64(search,1,rowID),SQLITE_OK)
            XCTAssertEqual(row.words.withCString { sqlite3_bind_text(search,2,$0,-1,transient) },SQLITE_OK)
            XCTAssertEqual(sqlite3_step(search),SQLITE_DONE); sqlite3_finalize(search)
        }
        return url
    }
    private func configuration(_ url: URL) -> RuntimeExampleConfiguration {
        .init(libraryURL:url,allowProposed:false,retrievalEnabled:true)
    }
    func testRepeatedBlueprintCannotSpendRaw160SlotsBeforeComplementaryPatterns() async throws {
        let siblings = (0..<200).map { Row(id:String(format:"A%03d",$0),blueprint:"repeated",shape:"shape-\($0)",words:"quasar quasar quasar") }
        let complementary = (0..<5).map { Row(id:"B\($0)",blueprint:"complement-\($0)",shape:"independent-\($0)",words:"quasar padding extra other longer distinct words") }
        let url = try await fixture(siblings + complementary); defer { try? FileManager.default.removeItem(at:url) }
        let store = try RuntimeReferenceStore(url:url,expectedSHA256:nil,allowUnpinnedPrototype:true)
        let selected = try store.select("quasar",configuration:configuration(url))
        XCTAssertEqual(selected.count,6)
        XCTAssertEqual(Set(selected.map(\.provenance.blueprint)).count,6)
        XCTAssertEqual(Set(selected.map { try? (JSONSerialization.jsonObject(with:Data($0.payload.utf8)) as? [String:Any])?["composition_key"] as? String }).count,6)
        XCTAssertEqual(selected.filter { $0.provenance.blueprint == "repeated" }.map(\.id),["A000"])
        XCTAssertEqual(Set(selected.filter { $0.id.hasPrefix("B") }.map(\.id)),Set(complementary.map(\.id)))
    }
    func testDeniedAliasAndPayloadApprovalDoNotOccupyBlueprintOrExcludeEligibleSibling() async throws {
        let rows = [Row(id:"A000",blueprint:"first",shape:"s0",aliases:["heldout-alias"]),
                    Row(id:"A001",blueprint:"first",shape:"s1"),
                    Row(id:"B000",blueprint:"second",shape:"s2",eligible:false),
                    Row(id:"B001",blueprint:"second",shape:"s3"),
                    Row(id:"C000",blueprint:"third",shape:"s4"),
                    Row(id:"D000",blueprint:"denied-base",shape:"s5")]
        let url = try await fixture(rows); defer { try? FileManager.default.removeItem(at:url) }
        let store = try RuntimeReferenceStore(url:url,expectedSHA256:nil,allowUnpinnedPrototype:true)
        var c = configuration(url); c.excludedBlueprints = ["heldout-alias","denied-base"]; c.excludedIDs = ["C000"]
        XCTAssertEqual(try store.select("quasar",configuration:c).map(\.id),["A001","B001"])
    }
    func testCancelledSelectionReturnsNoPartialPoolAndConnectionRemainsUsable() async throws {
        let url = try await fixture([Row(id:"A",blueprint:"one",shape:"one")])
        defer { try? FileManager.default.removeItem(at:url) }
        let store = try RuntimeReferenceStore(url:url,expectedSHA256:nil,allowUnpinnedPrototype:true)
        let c = configuration(url)
        let cancelled = Task { @MainActor in try store.select("quasar",configuration:c) }
        cancelled.cancel()
        do { _ = try await cancelled.value; XCTFail("Cancelled selection must not return a successful pool") }
        catch RuntimeReferenceStore.Failure.selectionInterrupted(let reason) { XCTAssertEqual(reason,"caller") }
        catch { XCTFail("Unexpected cancellation stage: \(error)") }
        XCTAssertEqual(try store.select("quasar",configuration:c).map(\.id),["A"])
    }
    func testEqualScoreRepresentativesDoNotDependOnInsertionOrderAndForeignPayloadFailsClosed() async throws {
        let rows = [Row(id:"Z",blueprint:"same",shape:"z"),Row(id:"A",blueprint:"same",shape:"a"),Row(id:"B",blueprint:"other",shape:"b")]
        let urls = [try await fixture(rows),try await fixture(Array(rows.reversed()))]
        defer { for url in urls { try? FileManager.default.removeItem(at:url) } }
        for url in urls {
            let store = try RuntimeReferenceStore(url:url,expectedSHA256:nil,allowUnpinnedPrototype:true)
            XCTAssertEqual(try store.select("quasar",configuration:configuration(url)).map(\.id),["A","B"])
        }
        let foreign = try await fixture([Row(id:"F",blueprint:"foreign",shape:"f",payloadID:"OTHER")])
        defer { try? FileManager.default.removeItem(at:foreign) }
        let store = try RuntimeReferenceStore(url:foreign,expectedSHA256:nil,allowUnpinnedPrototype:true)
        XCTAssertTrue(try store.select("quasar",configuration:configuration(foreign)).isEmpty)
    }
}
#endif

#if canImport(FoundationModels)
@available(iOS 26.4, *)
final class RuntimeDownstreamRepairTests: XCTestCase {
    private var calendar:Calendar { var c = Calendar(identifier:.gregorian);c.timeZone = TimeZone(identifier:"America/Toronto")!;return c }
    private var moment:Date { ISO8601DateFormatter().date(from:"2026-11-16T14:00:00Z")! }
    private func validate(_ source:String,rows:[RuntimeFoundationInterpreter.IndexedItem]) -> ThoughtExtractionResult? {
        let rules = ThoughtExtractionEngine.extractWithRules(source,referenceDate:moment,calendar:calendar)
        return RuntimeFoundationInterpreter.validateIndexed(.init(items:rows),source:source,units:RuntimeIndexedSource(source),
            referenceDate:moment,calendar:calendar,rules:rules,context:.empty)
    }
    func testCurrentNominalAndPredicateProofSurviveMissingLexicalAssetsWithoutUnknownSuffixPermission() {
        let previous = SentenceContext.taggerDisabledForEvaluation
        SentenceContext.taggerDisabledForEvaluation = true
        defer { SentenceContext.taggerDisabledForEvaluation = previous }
        for phrase in ["the heat mat","a ceramic canopy","counterweight","the resin flange","the cork disk","the roof rib","the pivot socket","the thermal gasket"] {
            XCTAssertTrue(RuntimeCurrentNominalProof.read(phrase),phrase)
        }
        for action in ["trace the roof rib","photograph the pivot socket","measure the cork disk","scan the resin flange","inspect the thermal gasket"] {
            XCTAssertTrue(RuntimeDeclaredTaskPartition.predicate(action),action)
        }
        for phrase in ["the flange delete the draft","the unknownwidget","the flange / run","the flange — run","the flange plus delete","their flange","the flange tomorrow","no roof","neither roof"] {
            XCTAssertFalse(RuntimeCurrentNominalProof.read(phrase),phrase)
        }
    }
    func testWholeReplacementKeepsOnlyCurrentRecipientTopicAndClock() throws {
        let source = "Create one task to text my aunt’s partner about the ceramic canopy on December 2. No, replace that whole plan: call my niece about the counterweight on December 9 instead. Keep only that final task; no timed alert."
        let proof = try XCTUnwrap(RuntimeWholePlanReplacement.read(source))
        XCTAssertEqual(proof.recipient,"my niece");XCTAssertEqual(proof.clock,"December 9")
        let reading = try XCTUnwrap(RuntimeWholePlanReplacement.interpret(source,referenceDate:moment,calendar:calendar))
        XCTAssertEqual(reading.items.count,1);XCTAssertEqual(reading.items[0].organization.temporalIntent.day,CalendarDay(year:2026,month:12,day:9))
        XCTAssertEqual(reading.items[0].sourceQuote,source);XCTAssertNil(reading.items[0].organization.reminderDate)
        XCTAssertFalse(try XCTUnwrap(reading.items[0].suggestedTitle).contains("canopy"))
        let rows = RuntimeIndexedSource(source).units.indices.map { $0 }
        XCTAssertNotNil(validate(source,rows:[.init(evidence:Array(rows),purpose:.task,currentMeaning:proof.action,directContact:proof.recipient,needsReview:false)]))
        XCTAssertNil(validate(source,rows:[.init(evidence:Array(rows),purpose:.task,currentMeaning:proof.action.replacingOccurrences(of:"December 9",with:"December 2"),directContact:proof.recipient,needsReview:false)]))
        XCTAssertNil(validate(source,rows:[.init(evidence:Array(rows),purpose:.task,currentMeaning:proof.action,directContact:"my aunt’s partner",needsReview:false)]))
    }
    func testWholeReplacementDeclinesUnboundQuotedConditionalExtraActAndImpossibleDate() {
        let stem = "Make a task to email Vela about the mask frame on November 18. No, replace that whole plan: phone Rumi about the balance plate on November 22 instead. Keep only that final task; no timed alert."
        for bad in [stem.replacingOccurrences(of:"phone Rumi",with:"phone them"),"Nira said, \"" + stem + "\"",stem.replacingOccurrences(of:"phone Rumi",with:"if it is useful phone Rumi"),stem.replacingOccurrences(of:"balance plate",with:"balance plate and buy paint"),stem.replacingOccurrences(of:"balance plate",with:"balance plate plus delete the draft"),stem.replacingOccurrences(of:"balance plate",with:"balance plate delete the draft"),stem + " Call Vela tomorrow."] {
            XCTAssertNil(RuntimeWholePlanReplacement.read(bad),bad)
        }
        let invalid = stem.replacingOccurrences(of:"November 22",with:"November 31")
        XCTAssertNil(RuntimeWholePlanReplacement.interpret(invalid,referenceDate:moment,calendar:calendar))
        if let proof = RuntimeWholePlanReplacement.read(invalid) {
            XCTAssertNil(validate(invalid,rows:[.init(evidence:Array(RuntimeIndexedSource(invalid).units.indices),purpose:.task,currentMeaning:proof.action,directContact:proof.recipient,needsReview:false)]))
        }
    }
    func testConditionalCommunicationPreservesEventAndPendingFactAndDirectContact() throws {
        let source = "Near the end, after Wren confirms the beam is secure, ask Keza for the pulley width. Wren has inspected a sketch but has not confirmed security."
        let proof = try XCTUnwrap(RuntimeCommunicationReading.read(source))
        XCTAssertEqual(proof.recipient,"Keza");XCTAssertTrue(proof.action.contains("after Wren confirms"));XCTAssertTrue(proof.action.contains("has not confirmed"))
        let evidence = Array(RuntimeIndexedSource(source).units.indices)
        let result = try XCTUnwrap(validate(source,rows:[.init(evidence:evidence,purpose:.task,currentMeaning:"",directContact:"Keza",needsReview:false)]))
        XCTAssertEqual(result.items.first?.organization.personName,"Keza");XCTAssertNil(result.items.first?.organization.reminderDate)
        XCTAssertNil(validate(source,rows:[.init(evidence:evidence,purpose:.task,currentMeaning:"",directContact:"Wren",needsReview:false)]))
    }
    func testConditionalCommunicationCannotAdoptQuotesOrAppendUnownedTasks() {
        for source in ["Sera said, \"After Wren confirms the beam is secure, ask Keza for the pulley width.\"", "After Wren confirms the beam is secure, ask them for the pulley width.","After Wren confirms the beam is secure, ask Keza for the pulley width. Buy four bolts."] {
            XCTAssertNil(RuntimeCommunicationReading.read(source),source)
        }
    }
    func testCapturePositionRoutingKeepsCompletePurchaseAndNegativeReminderSource() {
        let purchase = "Toward the end, buy one bottle of sealant. Do not buy the existing bronze insert."
        XCTAssertEqual(RuntimeFoundationActionShape.body(purchase),"buy one bottle of sealant. Do not buy the existing bronze insert.")
        let reminder = "At the very end, remind me November 27 at 7 PM not to store the sealant beside the display heater. That is a deliberate negative reminder, separate from the purchase."
        XCTAssertEqual(RuntimeFoundationActionShape.body(reminder),"remind me November 27 at 7 PM not to store the sealant beside the display heater. That is a deliberate negative reminder, separate from the purchase.")
        for context in ["Toward the end, Dovan will buy the sealant.","Toward the end of the hall, buy the sealant.","Toward the end, I never agreed to buy the sealant."] {
            XCTAssertEqual(RuntimeFoundationActionShape.body(context),context)
        }
    }
    func testDeclaredSharedTasksRequireExactCardinalityCompleteAnchorsAndTaskPurpose() throws {
        let source = "Around the middle, give me two distinct tasks, to scan the resin flange and to measure the cork disk."
        let rows:[RuntimeFoundationInterpreter.IndexedItem] = [
            .init(evidence:[0],anchor:"scan the resin flange",purpose:.task,currentMeaning:"Scan the resin flange.",directContact:"",needsReview:false),
            .init(evidence:[0],anchor:"measure the cork disk",purpose:.task,currentMeaning:"Measure the cork disk.",directContact:"",needsReview:false)]
        XCTAssertNotNil(validate(source,rows:rows))
        XCTAssertNil(validate(source.replacingOccurrences(of:"two distinct",with:"three distinct"),rows:rows))
        var wrong = rows;wrong[0].purpose = .note;XCTAssertNil(validate(source,rows:wrong))
        wrong = rows;wrong[0].currentMeaning = "Scan the cork disk.";XCTAssertNil(validate(source,rows:wrong))
        XCTAssertNil(validate(source.replacingOccurrences(of:"disk.",with:"disk and polish the steel cap."),rows:rows))
        XCTAssertFalse(RuntimeDeclaredTaskPartition.prefix("Sera said give me two distinct tasks, to",count:2))
        XCTAssertFalse(RuntimeDeclaredTaskPartition.predicate("the resin flange"))
        XCTAssertFalse(RuntimeDeclaredTaskPartition.predicate("scan the flange plus delete the draft"))
        for bad in ["scan the flange / delete the draft","scan the flange — delete the draft","scan the flange secretly","scan their flange","scan the flange without checking","scan the flange delete draft","scan the flange afterwards","scan the flange to Vela","scan the flange and","scan the unknownwidget","trace no roof","trace neither roof"] {
            XCTAssertFalse(RuntimeDeclaredTaskPartition.predicate(bad),bad)
        }
    }
}
#endif


@MainActor
final class RuntimeOperationHandoffTests: XCTestCase {
    private var calendar:Calendar { var c=Calendar(identifier:.gregorian);c.timeZone=TimeZone(identifier:"America/Toronto")!;return c }
    private var moment:Date { ISO8601DateFormatter().date(from:"2026-11-16T14:00:00Z")! }
    private var configuration:RuntimeExampleConfiguration { .init(libraryURL:URL(fileURLWithPath:"/unused-for-injected-boundary"),allowProposed:false,retrievalEnabled:true) }
    func testItemOnlyReviewCannotEraseExactCurrentOperationAndIndependentCreation() async throws {
        for source in ["Cancel the dentist reminder.","Cancel the dentist reminder. Also buy milk.","Mark the dentist reminder complete.","Cancel every reminder.","Tomorrow I need to... never mind"] {
            let rules=ThoughtExtractionEngine.extractWithRules(source,referenceDate:moment,calendar:calendar)
            XCTAssertFalse(rules.operations.isEmpty,source)
            let partition=CaptureOperationDetector.partitionWithOwnership(source)
            let independent=partition.remainder.map { RuleBasedThoughtExtractor.process($0,referenceDate:moment,calendar:calendar,permitsOperations:false).items } ?? []
            if !RuntimeOperationalSourceHandoff.valid(rules,source:source,referenceDate:moment,calendar:calendar) {
                print("HANDOFF_BOUNDARY current=" + source)
                print("HANDOFF_BOUNDARY partition=" + String(describing:partition))
                print("HANDOFF_BOUNDARY rules=" + String(describing:rules.items))
                print("HANDOFF_BOUNDARY independent=" + String(describing:independent))
            }
            XCTAssertTrue(RuntimeOperationalSourceHandoff.valid(rules,source:source,referenceDate:moment,calendar:calendar),source)
            let held=RuntimeSourceInterpreter.recoverableReview(source)
            let result=await RuntimeExampleConfiguration.$testConfiguration.withValue(configuration) {
                await RuntimeExampleTestFixtures.withInterpretation(held) {
                    await ThoughtExtractionEngine.extract(source,referenceDate:moment,calendar:calendar)
                }
            }
            XCTAssertEqual(result.operations,rules.operations,source)
            XCTAssertEqual(result.items,rules.items,source)
        }
    }
    func testChangedTargetMissingCreationAndQuotedOrDeniedSourceCannotUseHandoff() {
        let source="Cancel the dentist reminder. Also buy milk."
        let correct=ThoughtExtractionEngine.extractWithRules(source,referenceDate:moment,calendar:calendar)
        let other=ThoughtExtractionEngine.extractWithRules("Cancel the gym reminder. Also buy milk.",referenceDate:moment,calendar:calendar)
        XCTAssertFalse(RuntimeOperationalSourceHandoff.valid(other,source:source,referenceDate:moment,calendar:calendar))
        XCTAssertFalse(RuntimeOperationalSourceHandoff.valid(.init(items:[],operations:correct.operations,method:.rules),source:source,referenceDate:moment,calendar:calendar))
        for denied in ["Sera said, \"Cancel the dentist reminder.\"","Do not cancel the dentist reminder.","I did not ask you to cancel the dentist reminder."] {
            XCTAssertFalse(RuntimeOperationalSourceHandoff.valid(correct,source:denied,referenceDate:moment,calendar:calendar),denied)
        }
    }
}


#if canImport(FoundationModels)
@available(iOS 26.4, *)
final class RuntimeFixedOwnershipGraphTests: XCTestCase {
    private var calendar:Calendar { var c=Calendar(identifier:.gregorian);c.timeZone=TimeZone(identifier:"America/Toronto")!;return c }
    private var moment:Date { ISO8601DateFormatter().date(from:"2026-11-16T14:00:00Z")! }
    private func decode(_ json:String,_ units:RuntimeIndexedSource) throws -> [RuntimeFoundationInterpreter.FirstOutlineRow]? {
        try RuntimeFoundationInterpreter.decodeFixedOutline(GeneratedContent(json:json),atoms:RuntimeFoundationInterpreter.fixedOutlineAtoms(units))
    }
    /// Assert actual constrained values: SDK 27 inlines dependency guides.
    /// Local acyclic JSON references also support older schema encodings.
    private func schemaPropertyEnum(_ schema:GenerationSchema,key:String) throws -> [String] {
        let root=try XCTUnwrap(JSONSerialization.jsonObject(with:JSONEncoder().encode(schema)) as? [String:Any])
        let properties=try XCTUnwrap(root["properties"] as? [String:[String:Any]])
        XCTAssertEqual(Set(try XCTUnwrap(root["required"] as? [String])),Set(properties.keys))
        XCTAssertEqual(root["additionalProperties"] as? Bool,false)
        func values(_ input: [String: Any], seen: Set<String> = []) throws -> [String] {
            var node = input, visited = seen
            while let reference = node["$ref"] as? String {
                guard reference.hasPrefix("#/"), visited.insert(reference).inserted else {
                    throw NSError(domain: "InvalidLocalSchemaReference", code: 1)
                }
                var value: Any = root
                for component in reference.dropFirst(2).split(separator: "/") {
                    let key = String(component).replacingOccurrences(of: "~1", with: "/")
                        .replacingOccurrences(of: "~0", with: "~")
                    value = try XCTUnwrap((value as? [String: Any])?[key])
                }
                node = try XCTUnwrap(value as? [String: Any])
            }
            // iOS 26.5 emits an anyOf of singleton string enums; SDK 27's
            // host runtime flattens that same constraint into one enum.
            if let alternatives = node["anyOf"] as? [[String: Any]] {
                XCTAssertFalse(alternatives.isEmpty)
                return try alternatives.flatMap { try values($0, seen: visited) }
            }
            XCTAssertEqual(node["type"] as? String, "string")
            let allowed = try XCTUnwrap(node["enum"] as? [String])
            XCTAssertFalse(allowed.isEmpty, "A closed string schema must enumerate its values")
            return allowed
        }
        return try values(XCTUnwrap(properties[key]))
    }

    func testContextProofCannotStripMemoryOwnershipOrAssumeObjectAliasDistinctness() {
        let clarification="That is a deliberate negative reminder, separate from the purchase."
        for source in ["Next note: remind me tomorrow not to wash the cup.","Next memory: remind me tomorrow not to wash the cup.",
            "Remind me tomorrow not to wash the cup and call Mom tomorrow.",
            "Remind me tomorrow not to wash the cup if Dad agrees.",
            "Remind me November 27 at 7 PM not to store the sealant beside the display heater call Mom tomorrow.",
            "First task: Next memory: remind me tomorrow not to call Mom.",
            "First task: Next note: remind me tomorrow not to call Mom.",
            "First task: Next task: remind me tomorrow not to call Mom."] {
            XCTAssertFalse(RuntimeFoundationInterpreter.currentNegativeReminderContext(clarification,belongsTo:source),source)
        }
        XCTAssertTrue(RuntimeFoundationInterpreter.currentNegativeReminderContext(clarification,belongsTo:"First task: remind me tomorrow not to call Mom."))
        for source in ["Buy one bronze insert.","Buy one packet of bronze inserts."] {
            XCTAssertFalse(RuntimeFoundationInterpreter.currentPurchaseExclusionContext("Do not buy the existing insert.",belongsTo:source),source)
        }
    }
    func testExplicitOwnFactualMemoryCannotBePromotedOrHideAnIndependentAction() throws {
        for source in [
            "My opening intention is a note, not work: the lens pavilion was named by Inara, who did not design its roof.",
            "Our first intention is a memory: the brass canopy was built by my aunt.",
            "Next note: the ceramic ring was already in the cabinet."
        ] {
            XCTAssertTrue(RuntimeFoundationInterpreter.currentDeclaredMemory(source),source)
            XCTAssertEqual(RuntimeFoundationInterpreter.currentSourcePurpose(source),"N",source)
        }
        for source in [
            "My opening intention is a note, not work: Call Mom tomorrow.",
            "Next memory: Buy two bottles of sealant.",
            "My opening intention is a note: the canopy was built by my aunt and call Dad tomorrow.",
            "My opening intention is a note: the canopy was built by my aunt because I'll repair it tomorrow.",
            "Next note: I am going to return the canopy tomorrow.",
            "Next note: I have now agreed to repair the canopy.",
            "Neri said, ‘My opening intention is a note: the canopy was built by my aunt.’",
            "My opening intention is a note: the canopy was built by my aunt while I am going to repair it."
        ] { XCTAssertFalse(RuntimeFoundationInterpreter.currentDeclaredMemory(source),source) }
        let source="My opening intention is a note, not work: the lens pavilion was named by Inara, who did not design its roof. Call Mom tomorrow. Call Dad tomorrow. Call my aunt tomorrow. Call my sister tomorrow. Call my brother tomorrow."
        let units=RuntimeIndexedSource(source),atoms=RuntimeFoundationInterpreter.fixedOutlineAtoms(units)
        XCTAssertEqual(atoms[0].sourcePurposeCode,"N")
        let schema=try XCTUnwrap(RuntimeFoundationInterpreter.fixedOutlineSchema(atoms))
        XCTAssertEqual(try schemaPropertyEnum(schema,key:"u0"),["N"])
        let correct=#"{"u0":4,"u1":0,"u2":0,"u3":0,"u4":0,"u5":0}"#
        XCTAssertNotNil(try RuntimeFoundationInterpreter.decodeIntegerOutline(GeneratedContent(json:correct),atoms:atoms))
        var bad=try XCTUnwrap(JSONSerialization.jsonObject(with:Data(correct.utf8)) as? [String:Int]);bad["u0"]=0
        let wrong=String(decoding:try JSONSerialization.data(withJSONObject:bad,options:.sortedKeys),as:UTF8.self)
        XCTAssertNil(try RuntimeFoundationInterpreter.decodeIntegerOutline(GeneratedContent(json:wrong),atoms:atoms))
    }
    func testAdjacentExistingPurchaseExclusionOwnsOnlyItsProvedList() throws {
        let purchase="Toward the end, buy one packet of felt buttons and one bottle of sealant."
        let exclusion="Do not buy the existing bronze insert."
        XCTAssertTrue(RuntimeFoundationInterpreter.currentPurchaseExclusionContext(exclusion,belongsTo:purchase))
        for pair in [
            ("Do not buy the existing sealant.",purchase),
            ("Do not buy the existing unknownwidget.",purchase),
            ("Do not buy the existing bronze insert and call Mom tomorrow.",purchase),
            (exclusion,"Dovan will buy one packet of felt buttons and one bottle of sealant."),
            (exclusion,"Buy one bottle of sealant if Dad agrees."),
            ("Neri said, ‘Do not buy the existing bronze insert.’",purchase),
            (exclusion,"Buy one bottle of sealant. Buy one packet of felt buttons.")
        ] { XCTAssertFalse(RuntimeFoundationInterpreter.currentPurchaseExclusionContext(pair.0,belongsTo:pair.1),pair.0+" | "+pair.1) }
        let source=purchase+" "+exclusion+" Call Mom tomorrow. Call Dad tomorrow. Call my sister tomorrow. Call my brother tomorrow."
        let units=RuntimeIndexedSource(source),atoms=RuntimeFoundationInterpreter.fixedOutlineAtoms(units)
        XCTAssertEqual(atoms[1].sourceContextOwnerKey,"u0")
        XCTAssertEqual(RuntimeFoundationInterpreter.compactAllowedDecisions(atoms[1],atoms:atoms),["=u0"])
        let schema=try XCTUnwrap(RuntimeFoundationInterpreter.fixedOutlineSchema(atoms))
        XCTAssertEqual(try schemaPropertyEnum(schema,key:"u1"),["=u0"])
        XCTAssertNil(try RuntimeFoundationInterpreter.decodeIntegerOutline(GeneratedContent(json:#"{"u0":1,"u1":0,"u2":0,"u3":0,"u4":0,"u5":0}"#),atoms:atoms))
