    func testQuotedMiddleStructuralPositiveAtomsKeepCurrentSpeakerOwnership() {
        let payloads=[
            "Give me two distinct tasks, to trace the roof rib and to photograph the pivot socket.",
            "Also retain one reference account that the bronze insert came from my cousin, the ceramic ring was already in the cabinet, and Enzo only suspects that the rim chip happened in transit.",
            "Keep the fact that Rivo supplied the fabric but the seam repair date is unknown.",
            "Buy four boxes of steel caps for Jani no make Jani three boxes and add two boxes for me those allocations stay separate."
        ]
        for payload in payloads {
            for (open,close) in [("‘","’"),("'","'")] {
                let source="Neri said, " + open + "Opening. " + payload + " End of report." + close + " Call Mom tomorrow. Call Dad tomorrow. Call my sister tomorrow. Call my brother tomorrow."
                let units=RuntimeIndexedSource(source),atoms=RuntimeFoundationInterpreter.fixedOutlineAtoms(units)
                XCTAssertFalse(QuotedSpeechScope.hasUnclosedQuote(source),source)
                XCTAssertEqual(atoms.count,units.units.count,source)
                let middle=atoms.filter { units.units[$0.unit].text == payload }
                XCTAssertEqual(middle.count,1,source)
                XCTAssertTrue(middle.allSatisfy { $0.anchor.isEmpty && !$0.retainedKnowledge && !$0.allocationPurchase && $0.sourcePurposeCode.isEmpty && $0.sourceContextOwnerKey.isEmpty },source)
                XCTAssertEqual(units.source,source)
            }
        }
    }
