        let rows=try XCTUnwrap(RuntimeFoundationInterpreter.decodeIntegerOutline(GeneratedContent(json:#"{"u0":0,"u1":8,"u2":0,"u3":0,"u4":0,"u5":0}"#),atoms:atoms))
        let plan=try XCTUnwrap(RuntimeFoundationInterpreter.stagedOutlinePlan(rows,units:units))
