    func testLaterConsentAndExplicitDeleteVetoDeniedAgreementEarlyBinding() {
        for text in ["I have not consented to delete that reminder. I have now consented to delete it.",
                     "We have not consented to cancel our booking. We are now consenting to cancel it.",
                     "I have not agreed to cancel that appointment. I've consented to cancel it.",
                     "I have not agreed to remove that appointment. Delete that appointment."] {
            XCTAssertFalse(RuntimeFoundationInterpreter.currentPurposeProofsCanBind(text),text)
            let atoms=RuntimeFoundationInterpreter.fixedOutlineAtoms(RuntimeIndexedSource(text))
            XCTAssertTrue(atoms[0].sourcePurposeCode.isEmpty,text)
        }
        let denied="I have not consented to delete that reminder. Also buy bread."
        XCTAssertTrue(RuntimeFoundationInterpreter.currentPurposeProofsCanBind(denied))
        XCTAssertEqual(RuntimeFoundationInterpreter.fixedOutlineAtoms(RuntimeIndexedSource(denied))[0].sourcePurposeCode,"N")
    }
    func testDeniedAgreementProofUsesCompleteOwnStatusOnlyAndKeepsConsentScope() {
        for text in ["I have not agreed to cancel that appointment.","We haven’t consented to delete our reminder.","I haven't agreed to remove his booking.","I have not consented to cancel my event."] {
            XCTAssertTrue(RuntimeFoundationInterpreter.currentDeniedAgreementStatus(text),text)
            XCTAssertEqual(RuntimeFoundationInterpreter.currentSourcePurpose(text),"N",text)
        }
        for text in ["I have agreed to cancel that appointment.","I have not agreed to cancel that appointment unless June approves.","I have not agreed to cancel that appointment and buy bread.","Mom said I have not agreed to cancel that appointment.","Mom said, ‘I have not agreed to cancel that appointment.’", "I have not agreed to cancel that appointment, but now I have agreed.","I have not agreed to cancel that appointment at eight tomorrow.","I have not agreed to move that appointment."] {
            XCTAssertFalse(RuntimeFoundationInterpreter.currentDeniedAgreementStatus(text),text)
        }
        let later="I have not agreed to cancel that appointment. Actually cancel that appointment tomorrow."
        let units=RuntimeIndexedSource(later),atoms=RuntimeFoundationInterpreter.fixedOutlineAtoms(units)
        XCTAssertEqual(atoms.count,2);XCTAssertTrue(atoms[0].sourcePurposeCode.isEmpty,"Later current correction vetoes early purpose binding")
        XCTAssertTrue(atoms[1].sourceContextOwnerKey.isEmpty,"Later own adoption must never be swallowed as a denied-status detail")
        XCTAssertFalse(RuntimeFoundationInterpreter.currentPurposeProofsCanBind(later))
        for changed in ["I have not agreed to cancel that appointment. I now agree to cancel it.",
                        "I have not agreed to cancel that appointment. Actually remove that appointment.",
                        "I have not agreed to cancel that appointment. Instead buy milk."] {
            let current=RuntimeFoundationInterpreter.fixedOutlineAtoms(RuntimeIndexedSource(changed))
            XCTAssertTrue(current[0].sourcePurposeCode.isEmpty,changed)
        }
        let quoted="Mom said, ‘I have not agreed to cancel that appointment. Also buy bread.’"
        XCTAssertFalse(RuntimeFoundationInterpreter.currentPurposeProofsCanBind(quoted),"Quoted denied change cannot claim an owned-status exemption")
    }
    /// Own SDK accounting, no generation and no semantic/model grade. A
    /// synthetic reserve saturates the base budget to exercise exact omission.
    func testOptionalGroupingPacketAndInstructionsAreAdmittedTogetherAtOwnSDKBoundary() async throws {
        let model=SystemLanguageModel.default
        guard model.availability == .available else { throw XCTSkip("Own SDK token counter unavailable") }
        try await RuntimeExampleTestFixtures.requireTokenCounter(model)
        let base="Read the complete current source; preserve every meaning.",required="CURRENT SOURCE: Call Mom tomorrow. Keep the cobalt pin as a separate fact."
        let hints=#"{"groups":[{"currentUnits":["u0"],"tentativeStoredKind":"personFollowUp"}],"unassignedCurrentUnits":["u1"]}"#
        let promptCost=try await model.tokenCount(for:required)
        let baseCost=try await model.tokenCount(for:Instructions(base)),schemaCost=17
        let saturatedReserve=model.contextSize-promptCost-baseCost-schemaCost
        XCTAssertGreaterThan(saturatedReserve,128)
        let omitted=try await RuntimeFoundationInterpreter.admittedGroupingHints(requiredPrompt:required,
            baseInstructions:base,hints:hints,model:model,schema:schemaCost,reserve:saturatedReserve)
        XCTAssertEqual(omitted.instructions,base)
        XCTAssertEqual(omitted.grouping,"")
        let omittedInstructionCost=try await model.tokenCount(for:Instructions(omitted.instructions))
        let omittedPromptCost=try await model.tokenCount(for:required+omitted.grouping)
        XCTAssertEqual(omittedPromptCost+omittedInstructionCost+schemaCost+saturatedReserve,model.contextSize)
        let admitted=try await RuntimeFoundationInterpreter.admittedGroupingHints(requiredPrompt:required,
            baseInstructions:base,hints:hints,model:model,schema:schemaCost,reserve:128)
        XCTAssertEqual(admitted.grouping,"\nFALLIBLE CURRENT PARSER GROUP SUGGESTIONS DATA (NOT PROOF):\n"+hints)
        XCTAssertTrue(admitted.instructions.hasPrefix(base))
        XCTAssertTrue(admitted.instructions.contains("not approved answers or confidence"))
        let admittedPromptCost=try await model.tokenCount(for:required+admitted.grouping)
        let admittedInstructionCost=try await model.tokenCount(for:Instructions(admitted.instructions))
        XCTAssertLessThanOrEqual(admittedPromptCost+admittedInstructionCost+schemaCost+128,model.contextSize)
        XCTAssertGreaterThan(admittedPromptCost+admittedInstructionCost,promptCost+baseCost)
        let empty=try await RuntimeFoundationInterpreter.admittedGroupingHints(requiredPrompt:required,
            baseInstructions:base,hints:"",model:model,schema:schemaCost,reserve:128)
        XCTAssertEqual(empty.instructions,base);XCTAssertEqual(empty.grouping,"")
        let record:[String:Any]=["scope":"SDK accounting diagnostic only; no generation; synthetic boundary reserve; not model evaluation",
            "ownContextSize":model.contextSize,"basePromptTokens":promptCost,"baseInstructionTokens":baseCost,
            "syntheticSchemaTokens":schemaCost,"syntheticSaturatingReserve":saturatedReserve,
            "omittedPromptTokens":omittedPromptCost,"omittedInstructionTokens":omittedInstructionCost,
            "admittedPromptTokens":admittedPromptCost,"admittedInstructionTokens":admittedInstructionCost,"ampleReserve":128]
        let attachment=XCTAttachment(data:try JSONSerialization.data(withJSONObject:record,options:[.sortedKeys,.prettyPrinted]),uniformTypeIdentifier:"public.json")
        attachment.name="Own-SDK-optional-packet-instruction-boundary-NO-GENERATION";attachment.lifetime = .keepAlways;add(attachment)
    }
    func testCompleteCurrentGroupingPacketKeepsPriorityOverWorkedReferencesAtOwnSDKBoundary() async throws {
        let model=SystemLanguageModel.default
        guard model.availability == .available else { throw XCTSkip("Own SDK token counter unavailable") }
        try await RuntimeExampleTestFixtures.requireTokenCounter(model)
