        let base="Use every current word and actual context. Other captures demonstrate mechanisms only."
        let reference="OTHER CAPTURE: Pack three towels for Dad; the two soap bars are for my sister. RESULT: packing, with separate owners and all quantities retained."
        let hints=#"{"groups":[{"currentUnits":["u0"],"tentativeStoredKind":"personFollowUp"}],"unassignedCurrentUnits":["u1"]}"#
        let schemaCost=17,required="WORKED REFERENCES ABOUT OTHER CAPTURES DATA:\n\n"+current
