        XCTAssertEqual(plain.includedIndices,[0],"The worked reference fits alone at this own measured boundary")
        XCTAssertEqual(hinted.includedIndices,[],"A reference cannot displace the complete admitted current grouping packet")
        XCTAssertEqual(hinted.prompt,required+packet.grouping);XCTAssertEqual(hinted.instructions,packet.instructions)
        XCTAssertEqual(hinted.grouping,packet.grouping);XCTAssertEqual(hinted.groupingReason,"admitted-complete-current-group-packet")
        let actualCost=try await model.tokenCount(for:hinted.prompt)
        XCTAssertEqual(actualCost+chosenCost+schemaCost+reserve,model.contextSize)
        XCTAssertEqual(hinted.referenceFits.count,1);XCTAssertFalse(hinted.referenceFits[0].accepted)
        let withSpace=try await RuntimeFoundationInterpreter.fitStagedPrompt(current:current,addition:"",baseInstructions:base,
            hints:hints,demonstrations:[reference,reference],model:model,schema:schemaCost,reserve:128)
        XCTAssertEqual(withSpace.includedIndices,[0,1]);XCTAssertEqual(withSpace.grouping,packet.grouping)
        XCTAssertTrue(withSpace.prompt.contains(reference));XCTAssertTrue(withSpace.prompt.contains(current))
        let baseCost=try await model.tokenCount(for:Instructions(base)),requiredCost=try await model.tokenCount(for:required)
        let baseReserve=model.contextSize-requiredCost-baseCost-schemaCost
        let omitted=try await RuntimeFoundationInterpreter.fitStagedPrompt(current:current,addition:"",baseInstructions:base,
            hints:hints,demonstrations:[],model:model,schema:schemaCost,reserve:baseReserve)
        XCTAssertTrue(omitted.requiredFits);XCTAssertEqual(omitted.prompt,required);XCTAssertEqual(omitted.instructions,base)
        XCTAssertEqual(omitted.grouping,"");XCTAssertEqual(omitted.groupingReason,"current-group-packet-and-caution-exceed-capacity")
        let overflow=try await RuntimeFoundationInterpreter.fitStagedPrompt(current:current,addition:"",baseInstructions:base,
            hints:hints,demonstrations:[reference],model:model,schema:schemaCost,reserve:model.contextSize)
        XCTAssertFalse(overflow.requiredFits);XCTAssertEqual(overflow.includedIndices,[])
        XCTAssertEqual(overflow.instructions,base);XCTAssertEqual(overflow.grouping,"")
        let record:[String:Any]=["scope":"Own SDK changed grouping-priority boundary only; artificial reserve/schema; no generation/model grade",
            "ownContextSize":model.contextSize,"completeGroupPromptTokens":packetPromptCost,"chosenInstructionTokens":chosenCost,
            "syntheticSchemaTokens":schemaCost,"syntheticSaturatingReserve":reserve,"selectedReferences":["synthetic-other-capture"],
            "plainFittedReferenceIndices":plain.includedIndices,"groupFirstFittedReferenceIndices":hinted.includedIndices,
            "groupingReason":hinted.groupingReason,"omittedReason":omitted.groupingReason,
            "responseConditionedReferences":NSNull(),"completion":"not-generated","cancellation":"none"]
        let attachment=XCTAttachment(data:try JSONSerialization.data(withJSONObject:record,options:[.sortedKeys,.prettyPrinted]),uniformTypeIdentifier:"public.json")
        attachment.name="Own-SDK-complete-current-group-priority-NO-GENERATION";attachment.lifetime = .keepAlways;add(attachment)
    }
    func testGroupingMapsDistinctOriginalOccurrencesAndRetainsDeletedUnitsWithoutApprovingRepair() throws {
        let source="Right, call Mom tomorrow. Call Mom tomorrow. Keep the brass pin."
        var trace:RuntimeRuleTrace?
        let p=RuleBasedThoughtExtractor.process(source,referenceDate:moment,calendar:calendar,permitsOperations:false,traceObserver:{ trace=$0 })
        let t=try XCTUnwrap(trace),units=RuntimeIndexedSource(source)
        XCTAssertEqual(SourceUnitLedger(source).words.count,SourceUnitLedger(t.creating).words.count+1)
        func render(_ changed:RuntimeRuleTrace) -> String {
            RuntimeCurrentGroupingHints.render(source,rules:.init(items:p.items,method:.rules),trace:changed,units:units)
        }
        let (_,groups,unassigned)=try hintPacket(render(t))
        XCTAssertEqual(unassigned,["u0"],"Deleted filler still has its whole immutable original unit accounted for")
        XCTAssertEqual(Set(groups.flatMap { $0["currentUnits"] as! [String] }),["u1","u2"])
        for mutation in 0..<5 {
            var ids=t.correctedWordRawIDs
            switch mutation {
            case 0: ids[1]=ids[0]
            case 1: ids.swapAt(0,1)
            case 2: ids[0].insert(0)
            case 3: ids[0]=Set([999999])
            default: ids[0]=[]
            }
            XCTAssertEqual(render(groupingTrace(t,items:p.items,wordIDs:ids)),"","Corrupt occurrence map \(mutation)")
        }
        let badItems=p.items.map { value -> ExtractedThought in var value=value;value.sourceUnitIDs.insert(SourceUnitLedger(t.creating).words.count);return value }
        XCTAssertEqual(RuntimeCurrentGroupingHints.render(source,rules:.init(items:badItems,method:.rules),trace:groupingTrace(t,items:badItems),units:units),"")
        let changedRepairs=t.repairs.map { r in RuntimeRuleTrace.Repair(kind:r.kind == "disfluency" ? "selfCorrection" : r.kind,input:r.input,output:r.output,removedRawIDs:r.removedRawIDs,inputWordRawIDs:r.inputWordRawIDs) }
        let nonFiller=RuntimeRuleTrace(original:t.original,normalized:t.normalized,corrected:t.corrected,creating:t.creating,
            repairs:changedRepairs,correctedWordRawIDs:t.correctedWordRawIDs,propositions:t.propositions,segmentQuotes:t.segmentQuotes,
            segmentRoles:t.segmentRoles,unmatchedSegments:t.unmatchedSegments,unassignedWordIDs:t.unassignedWordIDs,
            captureOnlyWordIDs:t.captureOnlyWordIDs,group:t.group,output:t.output)
        XCTAssertEqual(render(nonFiller),"")
    }

    private func groupingTrace(_ t:RuntimeRuleTrace,items:[ExtractedThought],creating:String? = nil,wordIDs:[Set<Int>]? = nil) -> RuntimeRuleTrace {
        .init(original:t.original,normalized:t.normalized,corrected:t.corrected,creating:creating ?? t.creating,
            repairs:t.repairs,correctedWordRawIDs:wordIDs ?? t.correctedWordRawIDs,propositions:t.propositions,
            segmentQuotes:t.segmentQuotes,segmentRoles:t.segmentRoles,unmatchedSegments:t.unmatchedSegments,
            unassignedWordIDs:t.unassignedWordIDs,captureOnlyWordIDs:t.captureOnlyWordIDs,group:t.group,output:items)
    }
    private func hintPacket(_ value:String) throws -> ([String:[String]],[[String:Any]],[String]) {
        let object=try XCTUnwrap(JSONSerialization.jsonObject(with:Data(value.utf8)) as? [String:Any])
        XCTAssertEqual(Set(object.keys),["groups","unassignedCurrentUnits"])
        let groups=try XCTUnwrap(object["groups"] as? [[String:Any]]),unassigned=try XCTUnwrap(object["unassignedCurrentUnits"] as? [String])
        var grouped:[String:[String]]=[:]
        for (index,g) in groups.enumerated() {
            XCTAssertEqual(Set(g.keys),["currentUnits","tentativeStoredKind"])
            grouped[String(index)]=try XCTUnwrap(g["currentUnits"] as? [String])
        }
        return (grouped,groups,unassigned)
    }
