    @MainActor
    func testCurrentGardenAndTrainGroupingDiscoveryRetainsCompleteUnitAccountingAndExistingIdeas() throws {
        for (name,source,ideaIDs) in [("Garden",IntentConsolidationTests.gardenScatteredLongCapture,["u6","u7","u8"]),
                                       ("Train",IntentConsolidationTests.trainIdeaLongCapture,["u15","u16","u17"])] {
            var trace:RuntimeRuleTrace?
            let p=RuleBasedThoughtExtractor.process(source,referenceDate:moment,calendar:calendar,permitsOperations:false,traceObserver:{ trace=$0 })
            let t=try XCTUnwrap(trace),units=RuntimeIndexedSource(source)
            let hint=RuntimeCurrentGroupingHints.render(source,rules:.init(items:p.items,operations:p.operations,method:.rules),trace:t,units:units)
            let rows=p.items.map { item -> [String:Any] in
                ["quote":item.sourceQuote,"analysis":item.analysisText,"title":item.suggestedTitle ?? "","kind":item.organization.itemType.rawValue,
                 "wordIDs":item.sourceUnitIDs.sorted(),"needsReview":item.needsReview,"confidence":item.confidence]
            }
            let record:[String:Any]=["source":source,"hint":hint,"actualParserRows":rows,"originalWordCount":SourceUnitLedger(source).words.count,
                "creationWordCount":SourceUnitLedger(t.creating).words.count,"creating":t.creating,"changedRepairStages":t.repairs.filter { $0.input != $0.output }.map(\.kind)]
            let attachment=XCTAttachment(data:try JSONSerialization.data(withJSONObject:record,options:[.sortedKeys,.prettyPrinted]),uniformTypeIdentifier:"public.json")
            attachment.name="Current-\(name)-parser-group-discovery-NOT-MODEL";attachment.lifetime = .keepAlways;add(attachment)
            XCTAssertFalse(hint.isEmpty,name)
            guard !hint.isEmpty else { continue }
            let (_,groups,unassigned)=try hintPacket(hint)
