    func testCurrentRoleBondMatchesWholeAdjacentCurrentSlotsAndDeclinesExtraMeaning() {
        for (action,context) in [
            ("Tell Noe to ask their half-sister about the prism tomorrow;","I am contacting Noe, not that half-sister."),
            ("Tell Arin Lee to ask their brother’s partner about the brass frame;","I am contacting Arin Lee, not that brother’s partner."),
            ("Return Noe’s brass frame to my brother’s partner on December 8.","Noe remains owner and my brother’s partner is only recipient."),
            ("Return Arin Lee’s blue case to Mom.","Arin Lee remains owner and Mom is only recipient.")
        ] { XCTAssertTrue(RuntimeFoundationInterpreter.currentRoleContext(context,belongsTo:action),action+context) }
        let tell="Tell Noe to ask their half-sister about the prism tomorrow;"
        for context in ["I am contacting Zari, not that half-sister.","I am contacting Noe, not that brother.",
                        "I am contacting Noe, not that half-sister and call Mom tomorrow.",
                        "I am contacting Noe, not that half-sister if Dad agrees.",
                        "I am contacting Noe, not that half-sister tomorrow.",
                        "Noe said I am contacting Noe, not that half-sister.",
                        "Actually I am contacting Noe, not that half-sister.",
                        "\"I am contacting Noe, not that half-sister.\""] {
            XCTAssertFalse(RuntimeFoundationInterpreter.currentRoleContext(context,belongsTo:tell),context)
        }
        let clarification="I am contacting Noe, not that half-sister."
        for action in ["Noe said, \"Tell Noe to ask their half-sister about the prism tomorrow;\"",
                       "Tell Noe to ask their half-sister about the prism and call Mom tomorrow;",
                       "Tell Noe to ask their half-sister about the prism if Dad agrees;",
                       "Actually tell Noe to ask their half-sister about the prism;",
                       "Tell Noe to ask their half-sister about the prism; call Mom tomorrow;",
                       "Tell Noe to ask their half-sister about the prism; We agreed to buy milk."] {
            XCTAssertFalse(RuntimeFoundationInterpreter.currentRoleContext(clarification,belongsTo:action),action)
        }
        let physical="Return Noe’s brass frame to my niece November 23."
        for context in ["Zari remains owner and my niece is only recipient.","Noe remains owner and my sister is only recipient.",
                        "Noe remains owner and my niece is only recipient and buy milk.",
                        "Noe remains owner and my niece is only recipient if Dad agrees.",
                        "Noe remains owner and my niece is only recipient tomorrow.",
                        "Noe remains owner and my niece is only recipient; call Mom."] {
            XCTAssertFalse(RuntimeFoundationInterpreter.currentRoleContext(context,belongsTo:physical),context)
        }
        for source in ["Tell Noe to ask their half-sister about the prism. Call Mom tomorrow. I am contacting Noe, not that half-sister.",
                       "Keep the fact that Noe owns the prism. I am contacting Noe, not that half-sister.",
                       "Tell Noe to ask their half-sister about the prism. I am contacting Noe, not that half-sister. I am contacting Noe, not that half-sister."] {
            let atoms=RuntimeFoundationInterpreter.fixedOutlineAtoms(RuntimeIndexedSource(source))
            XCTAssertTrue(atoms.last?.roleContextOwnerKey.isEmpty == true,source)
        }
    }
