    func testFollowupReferenceContinuityStopsSpareCapacityExpansionAndRetainsCompleteCurrentReconciliation() async throws {
        let model=SystemLanguageModel.default
        guard model.availability == .available else { throw XCTSkip("Own SDK token counter unavailable") }
        try await RuntimeExampleTestFixtures.requireTokenCounter(model)
        let current="COMPLETE CURRENT SOURCE AND ACTUAL CONTEXT: Call Mom tomorrow. Actually, call Dad instead. The three red bowls belong to my sister. Keep the entire list and both roles."
        let addition="\nCURRENT OUTLINE AND COMPLETE CURRENT RECONCILIATION: the call recipient is Dad; retain Mom in immutable original wording. Preserve all three bowls and their owner."
        let instructions="Read all current meaning and context. Worked captures are other data; never copy their facts."
        let references=["OTHER CAPTURE: Call Nana, correction call Pop. RESULT: current corrected recipient Pop, original Nana retained.","OTHER CAPTURE: Pack seven cups for the aunt. RESULT: retain seven cups with that owner and packing purpose."]
        let one="WORKED REFERENCES ABOUT OTHER CAPTURES DATA:\n"+references[0]+"\n"+current
        let schema=17,baseCost=try await model.tokenCount(for:Instructions(instructions)),oneCost=try await model.tokenCount(for:one)
        let outlineReserve=model.contextSize-baseCost-schema-oneCost
        XCTAssertGreaterThan(outlineReserve,128)
        let outline=try await RuntimeFoundationInterpreter.fitStagedPrompt(current:current,addition:"",baseInstructions:instructions,hints:"",demonstrations:references,model:model,schema:schema,reserve:outlineReserve)
        XCTAssertEqual(outline.includedIndices,[0])
        // Reproduces the old expansion: a smaller reserve admits an extra
        // mechanism even though the current decision now includes reconciliation.
        let expanded=try await RuntimeFoundationInterpreter.fitStagedPrompt(current:current,addition:addition,baseInstructions:instructions,hints:"",demonstrations:references,model:model,schema:schema,reserve:128)
        XCTAssertEqual(expanded.includedIndices,[0,1])
        let carried=outline.includedIndices.map { references[$0] }
        let bounded=try await RuntimeFoundationInterpreter.fitStagedPrompt(current:current,addition:addition,baseInstructions:instructions,hints:"",demonstrations:carried,model:model,schema:schema,reserve:128)
        XCTAssertTrue(bounded.requiredFits);XCTAssertEqual(bounded.includedIndices,[0])
        XCTAssertEqual(bounded.prompt,"WORKED REFERENCES ABOUT OTHER CAPTURES DATA:\n"+references[0]+"\n"+current+addition)
        XCTAssertEqual(bounded.instructions,instructions);XCTAssertTrue(bounded.prompt.contains(current));XCTAssertTrue(bounded.prompt.hasSuffix(addition))
        let boundedCost=try await model.tokenCount(for:bounded.prompt),expandedCost=try await model.tokenCount(for:expanded.prompt)
        XCTAssertLessThan(boundedCost,expandedCost)
        let record:[String:Any]=["scope":"Own SDK admission diagnostic only; synthetic reserve/schema; no model generation or quality credit","ownContextSize":model.contextSize,"outlineAdmittedIndices":outline.includedIndices,"oldExpansionIndices":expanded.includedIndices,"newFollowupIndices":bounded.includedIndices,"newPromptTokens":boundedCost,"oldPromptTokens":expandedCost,"schemaTokensSynthetic":schema,"outputLimitSynthetic":128,"currentAndReconciliationExact":true,"completion":"not-generated","cancellation":"none","responseConditionedReferences":NSNull()]
        let attachment=XCTAttachment(data:try JSONSerialization.data(withJSONObject:record,options:[.sortedKeys,.prettyPrinted]),uniformTypeIdentifier:"public.json");attachment.name="Own-SDK-followup-reference-continuity-NO-GENERATION";attachment.lifetime = .keepAlways;add(attachment)
    }

