        func certify(_ source:String) throws -> ThoughtExtractionResult? {
            var trace:RuntimeRuleTrace?
            let result=RuleBasedThoughtExtractor.process(source,referenceDate:date,calendar:calendar,permitsOperations:true,traceObserver:{trace=$0})
            let events=CheckedLines()
            let proposal=RuntimeExampleLibrary.$developmentObserver.withValue({events.append($0)}) {
                RuntimeDiscourseCertificate.validate(.init(items:result.items,operations:result.operations,method:.rules),
                    trace:trace,source:source,referenceDate:date,calendar:calendar)
            }
            let attachment=XCTAttachment(string:["CURRENT SOURCE: "+source,"RULES: "+String(reflecting:result),
                "CERTIFICATE: "+String(reflecting:proposal),"BOUNDARY: "+events.text()].joined(separator:"\n"))
            attachment.lifetime = .keepAlways;add(attachment)
