    func testObservedCurrentRulesAndCertificateBoundaryBeforeGeneration() throws {
        var calendar=Calendar(identifier:.gregorian);calendar.timeZone=TimeZone(identifier:"America/Toronto")!
        let date=try XCTUnwrap(calendar.date(from:DateComponents(year:2026,month:10,day:5,hour:9)))
        for (label,source) in [("Club",IntentConsolidationTests.clubEventLongCapture),
                               ("Garden",IntentConsolidationTests.gardenScatteredLongCapture),
