        func eligible(_ source:String,clock:Bool=true) -> Bool {
            let units=RuntimeIndexedSource(source)
            let atoms=RuntimeFoundationInterpreter.fixedOutlineAtoms(units,referenceDate:date,calendar:calendar)
            return RuntimeFoundationInterpreter.fixedOutlineEligible(units,atoms:atoms,
                referenceDate:clock ? date:nil,calendar:clock ? calendar:nil)
        }
        let garden=IntentConsolidationTests.gardenScatteredLongCapture
        XCTAssertTrue(eligible(garden))
        let units=RuntimeIndexedSource(garden)
        let group=Array(17...21).map { units.units[$0].text }.joined(separator:" ")
        for plant in ["parsley","basil","seedlings"] {
            let source=group.replacingOccurrences(of:"parsley",with:plant)
            XCTAssertTrue(eligible(source),source)
            XCTAssertTrue(eligible(source+" Call Mom tomorrow."),"A distinct current task still has its own atom")
            XCTAssertFalse(eligible(source,clock:false))
            for bad in [source.replacingOccurrences(of:"Otherwise water it tomorrow",with:"Otherwise water it tomorrow and call Mom"),
                        source.replacingOccurrences(of:"I can check it.",with:"Call Mom tomorrow."),
                        source.replacingOccurrences(of:"I am not asking the app to monitor the weather",with:"I am asking the app to monitor the weather")] {
                XCTAssertFalse(eligible(bad),bad)
            }
        }
        XCTAssertFalse(eligible("Otherwise call Mom tomorrow."))
        // Syntax selection cannot certify a wrong purpose or remove a unit.
        let correct=[RuntimeFoundationInterpreter.IndexedItem(evidence:Array(17...21),purpose:.task,currentMeaning:"",directContact:"",needsReview:false)]
        XCTAssertFalse(RuntimeFoundationInterpreter.validOwnership(correct,units:units))
        XCTAssertFalse(eligible(IntentConsolidationTests.trainIdeaLongCapture),"Communication payload needs its own complete proof")
    }
    func testAnchoredRetainedIdeaCannotDropWholeCurrentNoncommitment() throws {
        let date=Date(timeIntervalSince1970:1791396000),calendar=Calendar(identifier:.gregorian)
        for object in ["station platform","garden fence","park gate"] {
            let phrase="photograph the same "+object+" from the same spot every time I visit"
            let source="There is an idea I want to keep separately, though: "+phrase+". It might make an interesting series over a year. I am not setting up a recurring reminder for it, just saving the possible project."
            let units=RuntimeIndexedSource(source),rules=ThoughtExtractionEngine.extractWithRules(source,referenceDate:date,calendar:calendar)
            let wrong=RuntimeFoundationInterpreter.IndexedItem(evidence:Array(units.units.indices),anchor:phrase,purpose:.task,currentMeaning:phrase,directContact:"",needsReview:false)
            XCTAssertTrue(RuntimeFoundationInterpreter.validOwnership([wrong],units:units))
