            let attachment=XCTAttachment(string:"ANCHORED WRONG TASK WHOLE SOURCE:\n"+source+"\nANCHOR:\n"+phrase+"\nACTUAL:\n"+String(describing:actual))
            attachment.lifetime = .keepAlways;add(attachment)
            XCTAssertNil(actual,"An anchor cannot adopt the complete current retained idea")
            let correct=RuntimeFoundationInterpreter.IndexedItem(evidence:Array(units.units.indices),purpose:.idea,currentMeaning:"",directContact:"",needsReview:false)
            let accepted=try XCTUnwrap(RuntimeFoundationInterpreter.validateIndexed(.init(items:[correct]),source:source,units:units,referenceDate:date,calendar:calendar,rules:rules,context:.empty))
