    private final class CheckedLines:@unchecked Sendable {
        private let lock=NSLock();private var values:[String]=[]
        func append(_ line:String) { lock.lock();values.append(line);lock.unlock() }
        func text()->String { lock.lock();defer { lock.unlock() };return values.joined(separator:" | ") }
    }
    /// Independent CURRENT source proposals injected after generation. These
    /// diagnostics neither invoke nor grade a model, retrieval, or real data.
    private func persistCheckedCompletePlan(_ valid:ThoughtExtractionResult,source:String) async throws {
        let directory=FileManager.default.temporaryDirectory.appendingPathComponent("checked-complete-plan-"+UUID().uuidString)
        try FileManager.default.createDirectory(at:directory,withIntermediateDirectories:true)
        defer { try? FileManager.default.removeItem(at:directory) }
        let config=ModelConfiguration(url:directory.appendingPathComponent("synthetic.store"),cloudKitDatabase:.none)
        var container:ModelContainer?=try ModelContainer(for:PersistenceController.schema,migrationPlan:SpeakItMigrationPlan.self,configurations:[config])
        var repo:SwiftDataThoughtRepository?=SwiftDataThoughtRepository(modelContext:try XCTUnwrap(container).mainContext,requestsReminderAuthorization:false)
        var saved:CaptureCreationResult?=try await RuntimeExampleTestFixtures.withInterpretation(valid) {
            try await XCTUnwrap(repo).createCaptureResult(text:source,source:.inAppText,createdAt:moment,schedulesReminders:false)
        }
        XCTAssertEqual(try XCTUnwrap(saved).session.originalTranscription,source)
        XCTAssertEqual(try XCTUnwrap(saved).items.count,valid.items.count)
        for (index,item) in try XCTUnwrap(saved).items.enumerated() {
            if let title=valid.items[index].suggestedTitle,!title.isEmpty {
                XCTAssertEqual(item.displayTitle,ThoughtTitleFormatter.polished(title,itemType:valid.items[index].organization.itemType,personName:valid.items[index].organization.personName))
            }
        }
        let states=try XCTUnwrap(saved).items.map { ($0.id,$0.originalTextSegment,$0.displayTitle,$0.itemType,$0.personName,$0.dueDate,$0.reminderDate,$0.needsClarification) }
        _=try await RuntimeExampleTestFixtures.withInterpretation(valid) {
            try await XCTUnwrap(repo).createCaptureResult(text:source,source:.inAppText,createdAt:moment.addingTimeInterval(1),schedulesReminders:false)
        }
        XCTAssertEqual(try XCTUnwrap(container).mainContext.fetchCount(FetchDescriptor<CapturedItem>()),valid.items.count)
        saved=nil;repo=nil;container=nil
        let reopened=try ModelContainer(for:PersistenceController.schema,migrationPlan:SpeakItMigrationPlan.self,configurations:[config])
        let items=try reopened.mainContext.fetch(FetchDescriptor<CapturedItem>())
        XCTAssertEqual(Set(items.map(\.id)),Set(states.map { $0.0 }))
        for expected in states {
            let item=try XCTUnwrap(items.first { $0.id == expected.0 })
            XCTAssertEqual(item.originalTextSegment,expected.1);XCTAssertEqual(item.displayTitle,expected.2)
            XCTAssertEqual(item.itemType,expected.3);XCTAssertEqual(item.personName,expected.4)
            XCTAssertEqual(item.dueDate,expected.5);XCTAssertEqual(item.reminderDate,expected.6);XCTAssertEqual(item.needsClarification,expected.7)
            XCTAssertEqual(item.captureSession?.originalTranscription,source)
            XCTAssertNil(item.locationIntent);XCTAssertNil(RecurrenceStore.rule(for:item.id))
            let display=ItemPresentation.make(for:item,authorization:LocationAuthorization(status:.denied,isPrecise:true,isRegionMonitoringAvailable:true),now:moment,calendar:calendar)
            XCTAssertEqual(display.reviewRequirement == nil,!item.needsClarification)
            if item.itemType == .note || item.itemType == .idea { XCTAssertTrue(item.belongsInMemory);XCTAssertFalse(item.belongsInToday);XCTAssertNil(item.dueDate);XCTAssertNil(item.reminderDate) }
            else {
                XCTAssertEqual(item.belongsInToday, !item.needsClarification)
                XCTAssertFalse(item.belongsInMemory)
                if item.needsClarification { XCTAssertNil(item.dueDate);XCTAssertNil(item.reminderDate) }
            }
        }
    }
