    func testLosslessContextTransportRetainsCompleteSnapshotsAndLiteralRoles() throws {
        let instant=moment.addingTimeInterval(0.123456)
        let original="Nora’s sister’s partner said, \"Keep the receipt and the spare key\". The literal text {\"$string\":0} is part of this saved note."
        let title="Receipt and spare key belonging to Nora’s sister’s partner"
        let temporal=Data("opaque exact temporal bytes including 0\\0 and Unicode é".utf8)
        let snapshot=SavedAtomicRevision.Snapshot(id:UUID(),parentID:UUID(),original:original,title:title,
            kind:"note",category:"general",created:instant,modified:instant,person:"Nora’s sister’s partner",
            due:instant.addingTimeInterval(3600),reminder:instant.addingTimeInterval(3600),completed:nil,
            archived:false,archivedAt:nil,reviewed:true,needsClarification:false,confidence:0.73,priority:2,
            temporal:temporal,location:Data([0,255,7]),semanticState:"resolved",semanticGap:nil,
            parentOriginal:original,parentCreated:instant,temporalKind:"dateOnly",reminderTriggerKind:"none")
        let row=RuntimeCaptureContext.SavedItem(id:snapshot.id.uuidString,title:title,modifiedAt:instant,
            originalText:original,itemType:"note",personName:snapshot.person,dueDate:snapshot.due,
            reminderDate:snapshot.reminder,isReviewed:true,isArchived:false,isCompleted:false,snapshot:snapshot)
        let context=RuntimeCaptureContext(savedItems:[row,row,row],hasHome:true,hasWork:false)
        let ordinary=try RuntimeCurrentContextTransport.originalJSON(context)
        let compact=try XCTUnwrap(RuntimeCurrentContextTransport.projectedJSON(ordinary))
        let expanded=try RuntimeCurrentContextTransport.expandedJSON(compact)
        let canonical=try JSONSerialization.data(withJSONObject:JSONSerialization.jsonObject(with:ordinary),options:[.sortedKeys])
        XCTAssertEqual(expanded,canonical,"Every original field, value, type and omitted optional is preserved")
        XCTAssertLessThan(compact.count,ordinary.count)
        XCTAssertEqual(context.savedItems[0].snapshot,snapshot,"Native full-precision authority stays in process")
        XCTAssertEqual(context.savedItems[0].modifiedAt,instant)
        let decoded=try XCTUnwrap(JSONSerialization.jsonObject(with:expanded) as? [String:Any])
        let saved=try XCTUnwrap(decoded["savedItems"] as? [[String:Any]])
        XCTAssertEqual(saved.count,3);XCTAssertEqual(decoded["hasHome"] as? Bool,true)
        XCTAssertEqual(saved[0]["originalText"] as? String,original)
        let state=try XCTUnwrap(saved[0]["snapshot"] as? [String:Any])
        XCTAssertEqual(state["parentOriginal"] as? String,original)
        XCTAssertEqual(state["temporal"] as? String,temporal.base64EncodedString())
        XCTAssertEqual(state["location"] as? String,Data([0,255,7]).base64EncodedString())
        XCTAssertEqual(state["confidence"] as? Double,0.73);XCTAssertEqual(state["reviewed"] as? Bool,true)
        XCTAssertEqual(saved[0]["personName"] as? String,"Nora’s sister’s partner")
    }
    func testContextTransportPreservesEmptyContractAndRejectsCorruptAliases() throws {
        XCTAssertNil(try RuntimeCurrentContextTransport.projectedJSON(RuntimeCurrentContextTransport.originalJSON(.empty)))
        let literal=String(repeating:"complete literal current long field ",count:10)
        let repeated=RuntimeCaptureContext(savedItems:(0..<3).map { .init(id:"synthetic-context-\($0)",title:literal,modifiedAt:moment,originalText:literal) })
        let raw=try RuntimeCurrentContextTransport.originalJSON(repeated)
        let compact=try XCTUnwrap(RuntimeCurrentContextTransport.projectedJSON(raw))
        let value=try XCTUnwrap(JSONSerialization.jsonObject(with:compact) as? [String:Any])
        for bad:Any in [-1,999999,true,0.5] {
            var corrupt=value;corrupt["context"]=["savedItems":[["title":["$string":bad]]]]
            XCTAssertThrowsError(try RuntimeCurrentContextTransport.expandedJSON(JSONSerialization.data(withJSONObject:corrupt)))
        }
    }
