    func testReadableBinaryAliasesPreserveExactBytesAndRejectCorruptTypes() throws {
        let text="{ \"zone\" : \"America/Toronto\", \"speaker\":\"Mom’s sister’s partner\", \"null\":null, \"empty\":[] }\n"
        let base64=Data(text.utf8).base64EncodedString()
        let rows=(0..<8).map { ["id":"current-\($0)","temporal":base64,"literal":"[3,jsonText] is only a label","flag":true,"null":NSNull()] as [String:Any] }
        let original=try JSONSerialization.data(withJSONObject:["savedItems":rows,"hasHome":false,"hasWork":false],options:[.sortedKeys])
        let projected=try XCTUnwrap(RuntimeCurrentContextTransport.readableProjectedJSON(original))
        XCTAssertEqual(try RuntimeCurrentContextTransport.expandedReadableJSON(projected),original)
        let valid=try XCTUnwrap(try JSONSerialization.jsonObject(with:projected) as? [String:Any]);let context=try XCTUnwrap(valid["context"] as? [Any])
        func replace(_ value:Any,_ replacement:Any,_ changed:inout Bool)->Any {
            guard let array=value as? [Any] else { return value }
            if !changed,array.count == 2,(array[0] as? NSNumber)?.intValue == 3 { changed=true;return replacement }
            return array.map { replace($0,replacement,&changed) }
        }
        for alias:[Any] in [[3,true],[3,NSNull()],[3,"not JSON"],[3,"123"],[3,text,0],[3]] {
            var changed=false,root=valid;root["context"]=replace(context,alias,&changed);XCTAssertTrue(changed)
            XCTAssertThrowsError(try RuntimeCurrentContextTransport.expandedReadableJSON(JSONSerialization.data(withJSONObject:root,options:[.sortedKeys])))
        }
        XCTAssertThrowsError(try RuntimeCurrentContextTransport.expandedTaggedJSON(projected),"Old format must not silently accept tag3")
    }
