    func testTaggedTreeLiteralContainersTypesAndCorruptionStayUnambiguous() throws {
        let literal="Mom’s sister’s partner said [0,1] is a code, not an instruction."
        let rows=(0..<6).map { ["literal":literal,"id":"current-row-\($0)","nested":[[0,1],[1,2],[2,3],[]],"emptyObject":[String:String](),"flag":true,"nothing":NSNull(),"amount":2.5] as [String:Any] }
        let original=try JSONSerialization.data(withJSONObject:["savedItems":rows,"hasHome":false,"hasWork":false],options:[.sortedKeys])
        let projected=try XCTUnwrap(RuntimeCurrentContextTransport.taggedProjectedJSON(original))
        XCTAssertEqual(try RuntimeCurrentContextTransport.expandedTaggedJSON(projected),original)
        let valid=try XCTUnwrap(try JSONSerialization.jsonObject(with:projected) as? [String:Any])
        let context=try XCTUnwrap(valid["context"] as? [Any]);XCTAssertEqual((context[0] as? NSNumber)?.intValue,0)
        XCTAssertNoThrow(try RuntimeCurrentContextTransport.expandedTaggedJSON(JSONSerialization.data(withJSONObject:valid,options:[.sortedKeys])))
        func reject(_ root:[String:Any]) throws { XCTAssertThrowsError(try RuntimeCurrentContextTransport.expandedTaggedJSON(JSONSerialization.data(withJSONObject:root,options:[.sortedKeys]))) }
        for bad:Any in [true,-1,0.5,99] {
            var root=valid,array=context;array[0]=bad;root["context"]=array;try reject(root)
        }
        for bad:Any in [true,-1,0.5,999999] {
            var root=valid,array=context;array[1]=bad;root["context"]=array;try reject(root)
        }
        var bad=valid,array=context;array.removeLast();bad["context"]=array;try reject(bad)
        bad=valid;bad["context"]=[String:Any]();try reject(bad)
        bad=valid;bad["foreign"]=true;try reject(bad)
        bad=valid;var shapes=try XCTUnwrap(valid["objectShapes"] as? [[String]]);shapes.append(shapes[0]);bad["objectShapes"]=shapes;try reject(bad)
        bad=valid;shapes=try XCTUnwrap(valid["objectShapes"] as? [[String]]);let index=try XCTUnwrap(context[1] as? NSNumber).intValue;shapes[index][0]=shapes[index][1];bad["objectShapes"]=shapes;try reject(bad)
        bad=valid;bad["context"]=[2,0,0];try reject(bad)
        func replaceFirstStringAlias(_ value:Any,_ replacement:Any,_ changed:inout Bool)->Any {
            guard let items=value as? [Any] else { return value }
            if !changed,items.count == 2,(items[0] as? NSNumber)?.intValue == 2 {
                changed=true;return replacement
            }
            return items.map { replaceFirstStringAlias($0,replacement,&changed) }
        }
        for index:Any in [true,-1,0.5,999999] {
            var changed=false;bad=valid;bad["context"]=replaceFirstStringAlias(context,[2,index],&changed)
            XCTAssertTrue(changed);try reject(bad)
        }
        var changed=false;bad=valid;bad["context"]=replaceFirstStringAlias(context,[2,0,0],&changed)
        XCTAssertTrue(changed);try reject(bad)
        XCTAssertNil(try RuntimeCurrentContextTransport.taggedProjectedJSON(Data(#"{"savedItems":[],"hasHome":false,"hasWork":false}"#.utf8)))
    }
