    func testObjectShapeAliasesKeepTypesMembershipLiteralMarkersAndRejectCorruption() throws {
        let literal="Literal {\"$object\":[0,[]]} and {\"$string\":0} belongs to Mom’s sister’s partner."
        let rows=(0..<6).map { index -> [String:Any] in
            ["id":"synthetic-shape-\(index)","title":literal,"originalText":literal,
             "reviewed":index % 2 == 0,"nullable":NSNull(),"quantity":index,
             "entries":["first-\(index)","middle-\(index)","last-\(index)"],"fraction":0.123456789]
        }
        let observed=try JSONSerialization.data(withJSONObject:["hasHome":false,"hasWork":true,"savedItems":rows],options:[.sortedKeys])
        let compact=try XCTUnwrap(RuntimeCurrentContextTransport.structuredProjectedJSON(observed))
        XCTAssertEqual(try RuntimeCurrentContextTransport.expandedStructuredJSON(compact),observed)
        let value=try XCTUnwrap(JSONSerialization.jsonObject(with:compact) as? [String:Any])
        let shapes=try XCTUnwrap(value["objectShapes"] as? [[String]])
        XCTAssertEqual(shapes.count,1)
        let context=try XCTUnwrap(value["context"] as? [String:Any])
        let emittedRows=try XCTUnwrap(context["savedItems"] as? [[String:Any]])
        let validAlias=try XCTUnwrap(emittedRows.first?["$object"] as? [Any])
        let validValues=try XCTUnwrap(validAlias[1] as? [Any])
        XCTAssertEqual(validValues.count,shapes[0].count)
        var validRoot=value;validRoot["context"]=["$object":validAlias]
        XCTAssertNoThrow(try RuntimeCurrentContextTransport.expandedStructuredJSON(JSONSerialization.data(withJSONObject:validRoot)))
        for bad:Any in [-1,999999,true,0.5] {
            var corrupt=value;corrupt["context"]=["$object":[bad,validValues] as [Any]]
            XCTAssertThrowsError(try RuntimeCurrentContextTransport.expandedStructuredJSON(JSONSerialization.data(withJSONObject:corrupt)))
        }
        var arity=value;arity["context"]=["$object":[0,[]] as [Any]]
        XCTAssertThrowsError(try RuntimeCurrentContextTransport.expandedStructuredJSON(JSONSerialization.data(withJSONObject:arity)))
        var duplicate=value;duplicate["objectShapes"]=[Array(repeating:"title",count:shapes[0].count)]
        XCTAssertThrowsError(try RuntimeCurrentContextTransport.expandedStructuredJSON(JSONSerialization.data(withJSONObject:duplicate)))
        var extra=value;extra["context"]=["$object":[0,rows[0].values.map { $0 }] as [Any],"foreign":"permission"]
        XCTAssertThrowsError(try RuntimeCurrentContextTransport.expandedStructuredJSON(JSONSerialization.data(withJSONObject:extra)))
        XCTAssertNil(try RuntimeCurrentContextTransport.structuredProjectedJSON(RuntimeCurrentContextTransport.originalJSON(.empty)))
    }
    func testPastExplicitTonightRemainsReviewableWithoutInventingAnotherAlert() throws {
        var calendar=Calendar(identifier:.gregorian)
        calendar.timeZone=TimeZone(identifier:"America/Toronto")!
        let late=try XCTUnwrap(calendar.date(from:DateComponents(year:2026,month:10,day:5,hour:21)))
        let eight=try XCTUnwrap(calendar.date(bySettingHour:20,minute:0,second:0,of:late))
        let organized=ThoughtOrganizer.organize("Remind me at eight tonight to put the railcard in my wallet.",referenceDate:late,calendar:calendar)
        XCTAssertTrue(organized.needsClarification)
        XCTAssertNil(organized.reminderDate)
        XCTAssertEqual(organized.dueDate,eight)
