    func testCompleteDeniedSourceCompactDecisionsRetainAllRowsAndDeclineCorruption() throws {
        for contact in ["Nora","Mom","Dad","my sister","my brother’s partner"] {
            let source="I am correcting this recording not asking you to call \(contact) and cancel her appointment but I will wash the windows and clean the kitchen."
            let units=RuntimeIndexedSource(source)
            let atoms=RuntimeFoundationInterpreter.fixedOutlineAtoms(units,referenceDate:moment,calendar:calendar)
            XCTAssertEqual(atoms.map(\.key),["u0a0","u0a1","u0a2"])
            XCTAssertEqual(atoms.map(\.sourcePurposeCode),["N","T","T"])
            XCTAssertTrue(RuntimeFoundationInterpreter.fixedOutlineEligible(units,atoms:atoms))
            let raw=try GeneratedContent(json:#"{"u0a0":"N","u0a1":"T","u0a2":"T"}"#)
            let decoded=try XCTUnwrap(RuntimeFoundationInterpreter.decodeFixedOutline(raw,atoms:atoms))
            let planned=try XCTUnwrap(RuntimeFoundationInterpreter.stagedOutlinePlan(decoded,units:units))
            XCTAssertEqual(planned.sharedRows,Set([0,1,2]))
            XCTAssertEqual(RuntimeFoundationInterpreter.currentLiteralSharedRows(planned.items,sharedRows:planned.sharedRows,units:units,referenceDate:moment,calendar:calendar),planned.sharedRows)
            let valid=try XCTUnwrap(read(source,planned.items))
            XCTAssertEqual(valid.items.map(\.organization.itemType),[.note,.task,.task])
            XCTAssertTrue(valid.items.allSatisfy { !$0.needsReview && $0.organization.personName == nil
                && $0.organization.reminderDate == nil && $0.organization.dueDate == nil })
            for bad in [#"{"u0a0":"T","u0a1":"T","u0a2":"T"}"#,
                        #"{"u0a0":"N","u0a1":"T"}"#,
                        #"{"u0a0":"N","u0a1":"T","u0a2":"=u0a1"}"#,
                        #"{"u0a0":"N","u0a1":"T","u0a2":"T","foreign":"T"}"#] {
                XCTAssertNil(try RuntimeFoundationInterpreter.decodeFixedOutline(GeneratedContent(json:bad),atoms:atoms),bad)
            }
        }
        let extra="I am correcting this recording not asking you to call Mom and cancel her appointment but I will wash the windows and clean the kitchen. Call Dad tomorrow."
        let refused=RuntimeFoundationInterpreter.fixedOutlineAtoms(RuntimeIndexedSource(extra),referenceDate:moment,calendar:calendar)
        XCTAssertFalse(refused.contains { $0.key == "u0a0" },"incomplete whole source cannot constrain a subset")
    }
    func testWholeDeniedRequestAdmitsOnlyCompleteCurrentDenialAndOwnChores() throws {
        let cases=[
            "I am correcting this recording not asking you to call Nora and cancel her appointment but I will wash the windows and clean the kitchen.",
            "I am correcting the recording not asking you to phone Mom and remove her meeting but I will dust the table and wash the dishes.",
            "I am correcting this recording not asking you to email Dad and delete his booking but I will inspect the garage and clean the floor.",
            "I am correcting this recording not asking you to text my sister and cancel her reminder but I will water the plants and polish the desk."
        ]
        for source in cases {
            let units=RuntimeIndexedSource(source)
            let proof=try XCTUnwrap(RuntimeDeniedRequestPlan.read(units,referenceDate:moment,calendar:calendar),source)
            XCTAssertEqual(proof.map(\.adopted),[false,true,true])
            let rows=proof.map { RuntimeFoundationInterpreter.IndexedItem(evidence:[0],anchor:$0.anchor,
                purpose:$0.adopted ? .task : .note,currentMeaning:$0.anchor,directContact:"",needsReview:false) }
            let valid=try XCTUnwrap(read(source,rows),source)
            XCTAssertEqual(valid.items.map(\.organization.itemType),[.note,.task,.task])
            XCTAssertEqual(valid.items.map(\.suggestedTitle),proof.map { Optional($0.anchor) })
            XCTAssertTrue(valid.items.allSatisfy { $0.sourceQuote == source && $0.rawQuote == source
                && !$0.needsReview && $0.organization.personName == nil && $0.organization.dueDate == nil
                && $0.organization.reminderDate == nil && $0.organization.reminderDelivery == .none
                && $0.organization.locationIntent == nil && $0.organization.recurrenceRule == nil })
            // Shared complete provenance is intentional. This validator's
            // actual ownership contract proves disjoint exact anchors; the
            // older concatenated-quote guard forbids such repeated provenance.
            XCTAssertTrue(RuntimeFoundationInterpreter.validOwnership(rows,units:units))
            XCTAssertEqual(valid.items.reduce(into:Set<Int>()) { $0.formUnion($1.sourceUnitIDs) },
                           Set(SourceUnitLedger(source).words.indices))
            XCTAssertNil(read(source,Array(rows.dropLast())),"missing current chore")
            var wrong=rows;wrong[0].purpose = .task;XCTAssertNil(read(source,wrong),"denied effect cannot become action")
            wrong=rows;wrong[1].currentMeaning=proof[2].anchor;XCTAssertNil(read(source,wrong),"swapped current object")
            wrong=rows;wrong[0].directContact="Nora";XCTAssertNil(read(source,wrong),"no denied contact metadata")
            wrong=rows;wrong[1].needsReview=true;XCTAssertNil(read(source,wrong),"one row cannot waive complete graph")
        }
    }
    func testDeniedRequestProofDeclinesExtraMeaningTimingQuotesAndAmbiguousObjects() {
        let source="I am correcting this recording not asking you to call Nora and cancel her appointment but I will wash the windows and clean the kitchen."
        var bad=[source+" Call Dad tomorrow.","Nora said \""+source+"\"",
                 source.replacingOccurrences(of:"not asking you",with:"asking you"),
                 source.replacingOccurrences(of:"but I will",with:"but Nora will"),
                 source.replacingOccurrences(of:"her appointment",with:"the saved item")]
        for action in ["wash it", "wash the windows tomorrow", "wash the windows if Mom agrees",
                       "wash the windows and call Dad", "wash the windows I will call Dad",
                       "wash the floor spins", "wash the windows before noon", "wash the windows next week",
                       "wash the kitchen but not the floor", "wash the unknown wuggle"] {
            bad.append(source.replacingOccurrences(of:"wash the windows",with:action))
        }
        for input in bad { XCTAssertNil(RuntimeDeniedRequestPlan.read(RuntimeIndexedSource(input),referenceDate:moment,calendar:calendar),input) }
        // Ordinary family work retains its existing literal source path.
        XCTAssertNil(RuntimeDeniedRequestPlan.read(RuntimeIndexedSource("Call Mom tomorrow."),referenceDate:moment,calendar:calendar))
    }
