    func testCurrentPositionRoutingChoosesCompactContractWithoutHidingAnotherAct() {
        func eligible(_ source:String)->Bool {
            let units=RuntimeIndexedSource(source)
            return RuntimeFoundationInterpreter.fixedOutlineEligible(units,atoms:RuntimeFoundationInterpreter.fixedOutlineAtoms(units))
        }
        for prefix in ["In the middle of this capture", "Toward the end", "Near the end", "First", "Next", "Separately"] {
            XCTAssertTrue(eligible(prefix+", buy one packet of felt buttons and one bottle of sealant."),prefix)
            XCTAssertFalse(eligible(prefix+", buy one packet of felt buttons and call Mom tomorrow."),prefix)
            XCTAssertFalse(eligible(prefix+", buy one packet of felt buttons; also call Mom tomorrow and email Dad."),prefix)
        }
        for source in ["At the depot, buy one packet of felt buttons.",
                       "After Dad calls, buy one packet of felt buttons.",
                       "In the middle of this capture, buy milk, then call Mom.",
                       "In the middle of this capture, buy milk and also call Mom.",
                       "Jessa said, \"In the middle of this capture, buy milk and call Mom.\" Call Dad and email Mom.",
                       "In the middle of this capture, buy milk. Both tasks must happen after Dad confirms."] {
            XCTAssertFalse(eligible(source),source)
        }
        let source="In the middle of this capture, buy one packet of felt buttons and one bottle of sealant. Actually cancel those purchases; leave both off."
        let units=RuntimeIndexedSource(source),atoms=RuntimeFoundationInterpreter.fixedOutlineAtoms(units)
        XCTAssertEqual(units.source,source);XCTAssertEqual(atoms.map(\.unit),Array(units.units.indices))
        // Complete current-source ownership remains compulsory even when a
        // routing-only prefix permits the compact output contract.
        XCTAssertFalse(RuntimeFoundationInterpreter.validOwnership([
            .init(evidence:[0],anchor:"",purpose:.shopping,currentMeaning:"",directContact:"",needsReview:false)
        ],units:units))
    }
