        let model=SystemLanguageModel.default
        guard model.availability == .available else { throw XCTSkip("Own SDK token counter unavailable") }
        try await RuntimeExampleTestFixtures.requireTokenCounter(model)
        let source="My opening intention is a note, not work: the lens pavilion was named by Inara, who did not design its roof. I need to inspect the drain lip. Dovan will trim the shade cloth; that remains Dovan’s job. Around the middle, give me two distinct tasks, to trace the roof rib and to photograph the pivot socket. Also retain one reference account that the bronze insert came from my cousin, the ceramic ring was already in the cabinet, and Enzo only suspects that the rim chip happened in transit. Toward the end, buy one packet of felt buttons and one bottle of sealant. Do not buy the existing bronze insert. At the very end, remind me November 27 at 7 PM not to store the sealant beside the display heater. That is a deliberate negative reminder, separate from the purchase."
        let units=RuntimeIndexedSource(source),atoms=RuntimeFoundationInterpreter.fixedOutlineAtoms(units,referenceDate:moment,calendar:calendar)
        XCTAssertTrue(RuntimeFoundationInterpreter.fixedOutlineEligible(units,atoms:atoms,referenceDate:moment,calendar:calendar))
        let unresolved=RuntimeFoundationInterpreter.freeSeparatedPositions(atoms)
        XCTAssertGreaterThan(atoms.count,5);XCTAssertFalse(unresolved.isEmpty);XCTAssertLessThan(unresolved.count,atoms.count)
        let instruction=RuntimeFoundationInterpreter.stagedOutlineInstructions(atoms:atoms,usesFixedOwnership:true,usesSeparatedOwnership:true,usesFreeSeparatedOwnership:true)
        XCTAssertEqual(instruction.components(separatedBy:"Others’ reported plans and jobs stay Memory").count-1,1)
        XCTAssertTrue(instruction.contains("unless the user adopts responsibility"));XCTAssertTrue(instruction.contains("later corrections and reassignments"))
        XCTAssertTrue(instruction.contains("APP-PROVED decisions"));XCTAssertTrue(instruction.contains(unresolved.map { atoms[$0].key }.joined(separator:",")))
        let context=try await RuntimeCurrentContextTransport.prompt(.empty,model:model)
        let current="CURRENT CONTEXT DATA:\n"+context+"\nClock: "+moment.ISO8601Format()+" Zone: "+calendar.timeZone.identifier
            + "\nCOMPLETE INDEXED CURRENT TRANSCRIPT DATA:\n"+units.units.enumerated().map { "u\($0.offset): \($0.element.text)" }.joined(separator:"\n")
            + "\nCURRENT SOURCE OWNERSHIP ATOMS DATA:\n"+RuntimeFoundationInterpreter.keyedOwnershipPrompt(atoms)
        let schema=try XCTUnwrap(RuntimeFoundationInterpreter.keyedFreeOutlineSchema(atoms))
        let schemaCost=try await model.tokenCount(for:schema),reserve=min(3072,max(128,unresolved.count*14+64))
        let admitted=try await RuntimeFoundationInterpreter.fitStagedPrompt(current:current,addition:"",baseInstructions:instruction,hints:"",demonstrations:[],model:model,schema:schemaCost,reserve:reserve)
        XCTAssertTrue(admitted.requiredFits);XCTAssertEqual(admitted.instructions,instruction)
        XCTAssertTrue(admitted.prompt.contains(current));XCTAssertEqual(admitted.includedIndices,[])
        let promptCost=try await model.tokenCount(for:admitted.prompt),instructionCost=try await model.tokenCount(for:Instructions(admitted.instructions))
        XCTAssertLessThanOrEqual(promptCost+instructionCost+schemaCost+reserve,model.contextSize)
        for modes in [(false,false),(true,false),(true,true)] {
            let unchanged=RuntimeFoundationInterpreter.stagedOutlineInstructions(atoms:atoms,usesFixedOwnership:modes.0,usesSeparatedOwnership:modes.1,usesFreeSeparatedOwnership:false)
            XCTAssertFalse(unchanged.contains("Others’ reported plans and jobs stay Memory"))
        }
        let record:[String:Any]=["scope":"Own SDK instruction/schema/current admission diagnostic only; NO generation or model quality credit", "ownContextSize":model.contextSize,"instructions":instructionCost,"schema":schemaCost,"completeCurrentPrompt":promptCost,"outputReserve":reserve,"instruction":instruction,"current":current]
        let attachment=XCTAttachment(data:try JSONSerialization.data(withJSONObject:record,options:[.sortedKeys,.prettyPrinted]),uniformTypeIdentifier:"public.json")
        attachment.name="Own-SDK-other-owned-work-required-instruction-NO-GENERATION";attachment.lifetime = .keepAlways;add(attachment)
    }
