    func testCompleteCurrentPurchasePartitionCannotDropSwapOrBorrowAMemberOrNegativeContext() throws {
        let source="buy one packet of felt buttons and one bottle of sealant. Do not buy the existing bronze insert."
        let units=RuntimeIndexedSource(source)
        XCTAssertEqual(units.units.count,2)
        let rows:[RuntimeFoundationInterpreter.IndexedItem]=[
            .init(evidence:[0,1],anchor:"buy one packet of felt buttons",purpose:.shopping,currentMeaning:"buy one packet of felt buttons. Do not buy the existing bronze insert.",directContact:"",needsReview:false),
            .init(evidence:[0,1],anchor:"one bottle of sealant",purpose:.shopping,currentMeaning:"buy one bottle of sealant. Do not buy the existing bronze insert.",directContact:"",needsReview:false)]
        XCTAssertNotNil(read(source,rows))
        for change in 0..<8 {
            var wrong=rows
            switch change {
            case 0: wrong[1].currentMeaning="buy two bottles of sealant. Do not buy the existing bronze insert."
            case 1: wrong[1].currentMeaning="buy one packet of felt buttons. Do not buy the existing bronze insert."
            case 2: wrong[1].currentMeaning="buy one bottle of sealant."
            case 3: wrong[1].currentMeaning += " Call Mom tomorrow."
            case 4: wrong[1].directContact="Mom"
            case 5: wrong[1].anchor=wrong[0].anchor
            case 6: wrong[1].evidence=[0]
            default: wrong[1].purpose = .packing
            }
            XCTAssertNil(read(source,wrong),"Mutation \(change)")
        }
        XCTAssertNil(read(source,[rows[0]]),"A partial anchored purchase cannot cover the complete list")
        for wrongSource in [source.replacingOccurrences(of:"sealant",with:"sealant if Dad agrees"),
                            source.replacingOccurrences(of:"sealant",with:"sealant tomorrow"),
                            source.replacingOccurrences(of:"sealant",with:"sealant and call Mom"),
                            source.replacingOccurrences(of:"bronze insert.",with:"bronze insert and return Dad's cover."),
                            source+" Actually do not buy either one.",
                            "Inara said, \""+source+"\""] {
            XCTAssertNil(read(wrongSource,rows),wrongSource)
        }
    }

