    func testWholePurchaseWithdrawalGuardPreservesUnrelatedActionsAndQuotedContext() throws {
        for tail in ["Change the furnace filter tomorrow.", "Jessa said, \"Actually cancel those purchases.\""] {
            let source="purchase one packet of felt buttons and one bottle of sealant. "+tail
            let purpose:RuntimeFoundationInterpreter.Purpose=tail.hasPrefix("Jessa") ? .note : .task
            let valid=try XCTUnwrap(read(source,[
                .init(evidence:[0],anchor:"",purpose:.shopping,currentMeaning:"",directContact:"",needsReview:false),
                .init(evidence:[1],anchor:"",purpose:purpose,currentMeaning:"",directContact:"",needsReview:false)
            ]),source)
