            XCTAssertTrue(valid.items[0].analysisText.contains("one packet of felt buttons"))
            XCTAssertTrue(valid.items[0].analysisText.contains("one bottle of sealant"))
        }
        // A plain negative directive is not independently certified as an
        // active Task by the original reader. Test this new purchase guard's
        // scope separately; the original whole-validator safety stays active.
        let unrelated="purchase one packet of felt buttons and one bottle of sealant. Do not call Mom tomorrow."
        let unsupportedTask:[RuntimeFoundationInterpreter.IndexedItem]=[
            .init(evidence:[0],anchor:"",purpose:.shopping,currentMeaning:"",directContact:"",needsReview:false),
            .init(evidence:[1],anchor:"",purpose:.task,currentMeaning:"",directContact:"",needsReview:false)
        ]
        XCTAssertNotNil(RuntimeFoundationInterpreter.provedPurchaseRows(unsupportedTask,units:RuntimeIndexedSource(unrelated)))
        XCTAssertNil(read(unrelated,unsupportedTask),"Original non-adoption guard must still reject this unsupported active Task")
        let source="buy one packet felt buttons and one bottle of sealant. Actually cancel those purchases; leave both off."
        let held=try XCTUnwrap(read(source,[.init(evidence:[0,1,2],anchor:"",purpose:.review,currentMeaning:"",directContact:"",needsReview:true)]))
        XCTAssertEqual(held.items.count,1);XCTAssertTrue(held.items[0].needsReview)
        XCTAssertEqual(held.items[0].analysisText,source);XCTAssertNil(held.items[0].organization.reminderDate)
    }
