    func testFailedPurchaseProofCannotFallThroughToPartialOrStaleMembers() throws {
        for (source,anchor) in [
            ("Buy one packet of felt buttons and one bottle of sealant.","Buy one packet of felt buttons"),
            ("BUY ONE PACKET OF FELT BUTTONS AND ONE BOTTLE OF SEALANT.","BUY ONE PACKET OF FELT BUTTONS"),
            ("buy one packet felt buttons and one bottle of sealant.","buy one packet felt buttons"),
            ("buy one packet of unfamiliarwidget and one bottle of sealant.","buy one packet of unfamiliarwidget")
        ] {
            let row=RuntimeFoundationInterpreter.IndexedItem(evidence:[0],anchor:anchor,purpose:.shopping,currentMeaning:anchor,directContact:"",needsReview:false)
            XCTAssertNil(read(source,[row]),source)
        }
        let source="buy one packet of felt buttons and one bottle of sealant. Do not buy the existing bronze insert. Actually cancel those purchases; leave both off."
        let rows:[RuntimeFoundationInterpreter.IndexedItem]=[
            .init(evidence:[0,1],anchor:"buy one packet of felt buttons",purpose:.shopping,currentMeaning:"buy one packet of felt buttons. Do not buy the existing bronze insert.",directContact:"",needsReview:false),
            .init(evidence:[0,1],anchor:"one bottle of sealant",purpose:.shopping,currentMeaning:"buy one bottle of sealant. Do not buy the existing bronze insert.",directContact:"",needsReview:false),
            .init(evidence:[2,3],purpose:.review,currentMeaning:"",directContact:"",needsReview:true)]
        XCTAssertNil(read(source,rows),"A detached hold cannot authorize the stale purchase members")
        for source in ["Buy one packet of felt buttons and one bottle of sealant.","BUY ONE PACKET OF FELT BUTTONS AND ONE BOTTLE OF SEALANT."] {
            let partition=try XCTUnwrap(RuntimeFoundationInterpreter.currentPurchasePartition(source))
            let complete=partition.anchors.enumerated().map { index,anchor in
                RuntimeFoundationInterpreter.IndexedItem(evidence:[0],anchor:anchor,purpose:.shopping,currentMeaning:partition.actions[index],directContact:"",needsReview:false)
            }
            let valid=try XCTUnwrap(read(source,complete));XCTAssertEqual(valid.items.count,2)
            XCTAssertTrue(valid.items.allSatisfy { !$0.needsReview && $0.organization.itemType == .shopping && $0.organization.dueDate == nil && $0.organization.reminderDate == nil })
        }
        for source in ["buy one packet of felt buttons and one bottle of sealant Friday.","buy one packet of felt buttons and one bottle of sealant if Dad agrees."] {
            XCTAssertNil(RuntimeFoundationInterpreter.currentPurchasePartition(source),source)
        }
    }

