    /// TEST ONLY: grammar cost and decoder compatibility, no generation.
    private func diagnosticCurrentKeyGrammarSchema(_ atoms:[RuntimeFoundationInterpreter.CurrentOwnershipAtom]) throws -> GenerationSchema? {
        let free=RuntimeFoundationInterpreter.freeSeparatedPositions(atoms)
        guard !free.isEmpty,Set(atoms.map(\.key)).count == atoms.count else { return nil }
        let grammar=try Regex(#"(?:task|shopping|packing|inventory|note|idea|question|review|(?:context|correction):u[0-9]+(?:a[0-9]+)?)"#)
        let root=DynamicGenerationSchema(name:"CurrentKeyGrammarDecisions",properties:free.map { index in
            .init(name:atoms[index].key,schema:.init(type:String.self,guides:[.pattern(grammar)]))
        })
        return try GenerationSchema(root:root,dependencies:[])
    }
