                let schemaCost=try await model.tokenCount(for:schema)
                let reserve=fixed ? min(3072,max(128,atoms.count*14+64)) : min(3072,max(768,units.units.count*48+128))
                let admission=try await RuntimeFoundationInterpreter.fitStagedPrompt(current:current,addition:"",baseInstructions:instruction,
                    hints:hints,demonstrations:demonstrations,model:model,schema:schemaCost,reserve:reserve)
                XCTAssertTrue(admission.prompt.isEmpty || admission.prompt.contains(current))
