                    "savedContextRows":context.savedItems.count,"sourceTokens":try await model.tokenCount(for:source),
                    "indexedSourceTokens":try await model.tokenCount(for:indexed),"completeUserContextTokens":try await model.tokenCount(for:actualContext),
                    "currentOnlyTokens":try await model.tokenCount(for:current),"instructionTokens":try await model.tokenCount(for:Instructions(instruction)),
                    "schemaTokens":schemaCost,"outputReserve":reserve,"requiredFits":admission.requiredFits,
                    "finalPromptTokens":try await model.tokenCount(for:admission.prompt),"finalInstructionTokens":try await model.tokenCount(for:Instructions(admission.instructions)),
                    "optionalHintsTokens":try await model.tokenCount(for:admission.grouping),"selectedIDs":selected.map(\.id),
                    "fittedIDs":admission.includedIndices.map { selected[$0].id },"responseConditionedIDs":[],"completion":"NO GENERATION",
                    "actualInferenceOutputTokens":NSNull(),"laterRevisionCosts":NSNull(),"componentCostsNonadditive":true]
                records.append(record)
