    func testLaterOwnRoleVetoKeepsFiniteContractionsAndAdverbsUnresolvedWithoutGrantingAdoption() {
        for later in ["I'm going to wash it.","I’m definitely going to wash it.","We’re now going to wash it.","I'm responsible for the washing.","We're not going to wash it.","I've taken that work.","We’ve taken that work.","I definitely will wash it.","We still have to wash it."] {
            XCTAssertTrue(RuntimeFoundationInterpreter.currentLaterOwnRoleMayChange(later),later)
        }
        for unrelated in ["Dad will wash the frame.","The frame is blue.","That remains Neri’s job."] {
            XCTAssertFalse(RuntimeFoundationInterpreter.currentLaterOwnRoleMayChange(unrelated),unrelated)
        }
        // Declining a bond leaves every current unit for complete decoding;
        // it neither asserts that a denial is adoption nor approves an effect.
        let source="Neri will wash the blue frame; that remains Neri’s job. Call Mom tomorrow. Call Dad tomorrow. Call my sister tomorrow. Call my brother tomorrow."
        let before=RuntimeFoundationInterpreter.fixedOutlineAtoms(RuntimeIndexedSource(source))
        XCTAssertEqual(before[0].sourcePurposeCode,"N");XCTAssertEqual(before[1].sourceContextOwnerKey,"u0")
        for later in ["I'm not going to wash it.","We’re responsible for the washing."] {
            let units=RuntimeIndexedSource(source+" "+later),atoms=RuntimeFoundationInterpreter.fixedOutlineAtoms(units)
            XCTAssertEqual(Set(atoms.map(\.unit)),Set(units.units.indices))
            XCTAssertTrue(atoms[0].sourcePurposeCode.isEmpty);XCTAssertTrue(atoms[1].sourceContextOwnerKey.isEmpty)
        }
    }
