        let rows:[RuntimeFoundationInterpreter.IndexedItem]=[
            .init(evidence:[0],purpose:.task,currentMeaning:"",directContact:"",needsReview:false),root,
            .init(evidence:[2],purpose:.task,currentMeaning:"",directContact:"",needsReview:false)]
        let accepted=try XCTUnwrap(read(source,rows));XCTAssertEqual(accepted.items.count,3)
        let note=accepted.items[1];XCTAssertEqual(note.organization.itemType,.note);XCTAssertFalse(note.needsReview)
        XCTAssertEqual(note.suggestedTitle,units.units[1].text);XCTAssertNil(note.organization.dueDate);XCTAssertNil(note.organization.reminderDate);XCTAssertNil(note.organization.personName)
        root.anchor="the field sign is coded SKY-0088";root.currentMeaning=root.anchor
        XCTAssertNil(RuntimeFoundationInterpreter.provedRetainedMemoryRoot(root,units:units))
        root.anchor=units.units[1].text;root.currentMeaning=root.anchor;root.evidence=[0,1]
        XCTAssertNil(RuntimeFoundationInterpreter.provedRetainedMemoryRoot(root,units:units),"Current action provenance cannot become a factual certificate")
    }
