    func testRetainedKnowledgeDataRejectsForeignPartialDuplicateQuotedAndCurrentActClaims() throws {
        typealias Atom=RuntimeFoundationInterpreter.CurrentOwnershipAtom
        let units=RuntimeIndexedSource(mixedSource),valid=RuntimeFoundationInterpreter.fixedOutlineAtoms(units,referenceDate:moment,calendar:calendar)
        let first=try XCTUnwrap(valid.first(where: \.retainedKnowledge))
        for atoms in [[Atom(key:"u999",unit:999,anchor:"",retainedKnowledge:true)], [Atom(key:"partial",unit:first.unit,anchor:"seam",retainedKnowledge:true)], [first,first]] {
            XCTAssertNil(RuntimeFoundationInterpreter.currentRetainedKnowledgeData(atoms,units:units))
        }
        for source in ["Call Mom tomorrow.","Luma said, \"keep the fact that the gate is blue.\""] {
            let indexed=RuntimeIndexedSource(source),forged=[Atom(key:"u0",unit:0,anchor:"",retainedKnowledge:true)]
            XCTAssertNil(RuntimeFoundationInterpreter.currentRetainedKnowledgeData(forged,units:indexed),source)
        }
