@MainActor
final class RuntimeShortSourceCertificateTests:XCTestCase {
    private var calendar:Calendar { var c=Calendar(identifier:.gregorian);c.timeZone=TimeZone(identifier:"America/Toronto")!;return c }
    private var moment:Date { ISO8601DateFormatter().date(from:"2026-08-03T14:00:00Z")! }
    func testCompleteOrdinaryFramesKeepPurposePersonAndMembership() throws {
        for (source,kind,person) in [("Call Maya",ItemType.personFollowUp,"Maya"),("I need to call Sarah about the invoice",.personFollowUp,"Sarah")] {
            let result=try XCTUnwrap(RuntimeShortSourceCertificate.interpret(source,referenceDate:moment,calendar:calendar));XCTAssertEqual(result.items.count,1)
            XCTAssertEqual(result.items[0].organization.itemType,kind);XCTAssertEqual(result.items[0].organization.personName,person)
            XCTAssertFalse(result.items[0].needsReview);XCTAssertEqual(result.items[0].rawQuote,source)
        }
        let mixed="Call Maya. The spare key is in the blue drawer."
        let result=try XCTUnwrap(RuntimeShortSourceCertificate.interpret(mixed,referenceDate:moment,calendar:calendar))
        XCTAssertEqual(result.items.map(\.organization.itemType),[.personFollowUp,.note]);XCTAssertEqual(result.items.map(\.organization.personName),["Maya",nil])
        XCTAssertTrue(RuntimeProposalGuard.covers(mixed,quotes:result.items.map(\.rawQuote)))
    }
    func testCurrentClockAndIdeaRemainDistinctSpeechActs() throws {
        let source="Remind me tomorrow at 9 AM to water the plants"
        let task=try XCTUnwrap(RuntimeShortSourceCertificate.interpret(source,referenceDate:moment,calendar:calendar)?.items.first)
        let wanted=try XCTUnwrap(calendar.date(from:DateComponents(year:2026,month:8,day:4,hour:9)))
        XCTAssertEqual(task.organization.itemType,.task);XCTAssertEqual(task.organization.reminderDate,wanted)
        for source in ["I have an idea for a weekly planning app","I had an idea for weekly planning to read itself back to me."] {
            let idea=try XCTUnwrap(RuntimeShortSourceCertificate.interpret(source,referenceDate:moment,calendar:calendar)?.items.first)
            XCTAssertEqual(idea.organization.itemType,.idea);XCTAssertNil(idea.organization.reminderDate);XCTAssertEqual(idea.rawQuote,source)
        }
    }
    func testUnknownTailCorrectionsQuotesAndNewCommitmentsMustStillReconcile() {
        for source in ["Maya said call Dad tomorrow","Call Maya and I will buy milk","Call Maya actually call Dad instead","Call Maya if the parcel arrives","Call Maya about the invoice then pay the bill","I have an idea for an app and I will call Maya tomorrow","I have an idea for an app then contact Dad tomorrow","I have an idea for an app call Maya tomorrow","I had an idea for weekly planning to read itself back to me and buy milk","The spare key is in the blue drawer and buy milk","Cancel the saved plumber reminder","Call him tomorrow","Call June 12"] {
            XCTAssertNil(RuntimeShortSourceCertificate.interpret(source,referenceDate:moment,calendar:calendar),source)
        }
        XCTAssertTrue(RuntimeShortSourceCertificate.isDisfluencyOnly("like um you know"))
        XCTAssertFalse(RuntimeShortSourceCertificate.isDisfluencyOnly("like um you know call Mom tomorrow"))
    }
    func testCompleteWeekdayAndLiteralReminderTopicsKeepTimingAndRelationship() throws {
        let friday=try XCTUnwrap(calendar.date(from:DateComponents(year:2026,month:8,day:7)))
        for source in ["Call Mom on Friday","Remind me to call Mom on Friday"] {
            let item=try XCTUnwrap(RuntimeShortSourceCertificate.interpret(source,referenceDate:moment,calendar:calendar)?.items.first)
            XCTAssertEqual(item.organization.personName,"Mom");XCTAssertEqual(item.organization.itemType,.personFollowUp)
            XCTAssertEqual(item.organization.dueDate,friday);XCTAssertEqual(item.organization.temporalIntent.kind,.dateOnly)
            XCTAssertEqual(item.organization.reminderDelivery,source.hasPrefix("Remind") ? .notification : .none)
            XCTAssertEqual(item.rawQuote,source);XCTAssertFalse(item.needsReview)
        }
