@MainActor
final class RuntimeReminderCallbackBoundaryTests:XCTestCase {
    func testRealSerializedDeliveryCallbacksReturnToMainActorBeforeStateAccess() async {
        await ReminderScheduler.waitForPendingSynchronization()
        let previous=ReminderScheduler.delivery
        ReminderScheduler.delivery=ReminderDeliverySink(removeNotifications:{ _ in },cancelAlarm:{ _ in },pendingIdentifiers:{ [] },armedAlarmIDs:{ [] })
        defer { ReminderScheduler.delivery=previous }
        var completion=false,acknowledgment=false
        ReminderScheduler.synchronize([],requestAuthorizationIfNeeded:false,scope:.init(itemIDs:[],captureSessionIDs:[]),onCompletion:{ results in
            MainActor.assertIsolated();XCTAssertTrue(results.isEmpty);completion=true
        },onAcknowledgment:{ report in
            MainActor.assertIsolated();XCTAssertTrue(report.items.isEmpty);acknowledgment=true
        })
        await ReminderScheduler.waitForPendingSynchronization()
        XCTAssertTrue(completion);XCTAssertTrue(acknowledgment)
    }
    func testCurrentUntimedReminderCanRemainATaskWithoutInventedAlert() throws {
        var calendar=Calendar(identifier:.gregorian);calendar.timeZone=TimeZone(identifier:"America/Toronto")!
        let moment=ISO8601DateFormatter().date(from:"2026-08-03T14:00:00Z")!
        let source="remind me to ask Maya about the proposal"
        let reading=ThoughtOrganizer.organize(source,referenceDate:moment,calendar:calendar)
        print("CURRENT SHORT DIAGNOSTIC "+String(describing:reading))
        let item=try XCTUnwrap(RuntimeShortSourceCertificate.interpret(source,referenceDate:moment,calendar:calendar)?.items.first)
        XCTAssertEqual(item.organization.itemType,.personFollowUp);XCTAssertEqual(item.organization.personName,"Maya")
        XCTAssertNil(item.organization.dueDate);XCTAssertNil(item.organization.reminderDate);XCTAssertEqual(item.rawQuote,source)
    }
    func testLiteralDeadlineIsNotAnAlertAndRequestedAlertRetainsDelivery() throws {
        var calendar=Calendar(identifier:.gregorian);calendar.timeZone=TimeZone(identifier:"America/Toronto")!
        let moment=ISO8601DateFormatter().date(from:"2026-08-03T14:00:00Z")!
        let deadline=try XCTUnwrap(RuntimeShortSourceCertificate.interpret("Call Maya tomorrow",referenceDate:moment,calendar:calendar)?.items.first)
        XCTAssertNotNil(deadline.organization.dueDate);XCTAssertNil(deadline.organization.reminderDate);XCTAssertEqual(deadline.organization.reminderDelivery,.none)
        let alert=try XCTUnwrap(RuntimeShortSourceCertificate.interpret("Remind me tomorrow at 9 AM to water the plants",referenceDate:moment,calendar:calendar)?.items.first)
        XCTAssertEqual(alert.organization.reminderDelivery,.notification);XCTAssertEqual(alert.organization.reminderDate,alert.organization.dueDate)
        for source in ["Remind me tomorrow at 25 AM to water the plants","Remind me tomorrow at 0 AM to water the plants","Remind me tomorrow at 13 PM to water the plants","Remind me tomorrow at 9:60 AM to water the plants","Call Maya tomorrow and unlock the cabinet","Remind me when I get home to water the plants","Remind me to call Maya if the proposal arrives","Remind me to call them","Remind me to"] {
            XCTAssertNil(RuntimeShortSourceCertificate.interpret(source,referenceDate:moment,calendar:calendar),source)
        }
    }
}


