    // Independent input meanings sealed a7e45b8c... before these proposals.
    // Synthetic proposal injection is diagnostic ONLY: no generation credit.
    private func check(_ source:String,purpose:RuntimeFoundationInterpreter.Purpose,person:String?=nil,due:Date?=nil,alert:Date?=nil,recurrence:RecurrenceRule?=nil) async throws {
        let previousTime=ReminderDefaults.alertTime;ReminderDefaults.alertTime = .init(hour:9,minute:0)
        let previousRecurrences=RecurrenceStore.snapshots()
        defer { ReminderDefaults.alertTime=previousTime;RecurrenceStore.restore(previousRecurrences) }
        let units=RuntimeIndexedSource(source)
        let row=RuntimeFoundationInterpreter.IndexedItem(evidence:Array(units.units.indices),purpose:purpose,currentMeaning:"",directContact:purpose == .task ? person ?? "" : "",needsReview:false)
        let proposal=RuntimeFoundationInterpreter.IndexedProposal(items:[row])
        let checked=RuntimeFoundationInterpreter.validateIndexed(proposal,source:source,units:units,referenceDate:moment,calendar:calendar,rules:.init(items:[],method:.rules),context:.empty)
        let validation=XCTAttachment(string:"INPUT: "+source+"\nPROPOSAL: "+String(describing:row)+"\nVALIDATED: "+String(describing:checked));validation.lifetime = .keepAlways;add(validation)
        let valid=try XCTUnwrap(checked,"first stage: correct source-grounded proposal validation")
        let interpreted=try XCTUnwrap(valid.items.first)
        XCTAssertEqual(valid.items.count,1);XCTAssertFalse(interpreted.needsReview,"correct task/fact must stay usable")
        XCTAssertFalse(interpreted.organization.needsClarification);XCTAssertEqual(interpreted.organization.personName,person)
        XCTAssertEqual(interpreted.organization.dueDate,due);XCTAssertEqual(interpreted.organization.reminderDate,alert)
        XCTAssertEqual(interpreted.organization.reminderDelivery,alert == nil ? .none : .notification)
        XCTAssertEqual(interpreted.organization.recurrenceRule,recurrence)
        XCTAssertEqual(interpreted.organization.itemType.isActionable,purpose != .note)
        if purpose == .shopping { XCTAssertEqual(interpreted.organization.itemType,.shopping) }
        let directory=FileManager.default.temporaryDirectory.appendingPathComponent("current-seed-diagnostic-"+UUID().uuidString)
        try FileManager.default.createDirectory(at:directory,withIntermediateDirectories:true)
        defer { try? FileManager.default.removeItem(at:directory) }
        let config=ModelConfiguration(url:directory.appendingPathComponent("synthetic.store"),cloudKitDatabase:.none)
        var store:ModelContainer?=try ModelContainer(for:PersistenceController.schema,migrationPlan:SpeakItMigrationPlan.self,configurations:[config])
        var repo:SwiftDataThoughtRepository?=SwiftDataThoughtRepository(modelContext:try XCTUnwrap(store).mainContext,requestsReminderAuthorization:false)
        var result:CaptureCreationResult?=try await RuntimeExampleTestFixtures.withInterpretation(valid) {
            try await XCTUnwrap(repo).createCaptureResult(text:source,source:.inAppText,createdAt:moment,schedulesReminders:false)
        }
        var item:CapturedItem?=result?.items.first
        let id=try XCTUnwrap(item).id
        XCTAssertEqual(result?.session.originalTranscription,source);XCTAssertEqual(item?.originalTextSegment,source)
        if source.hasPrefix("Return ") { XCTAssertTrue(try XCTUnwrap(item).displayTitle.contains("Ivo"));XCTAssertTrue(try XCTUnwrap(item).displayTitle.localizedCaseInsensitiveContains("packing blankets")) }
        XCTAssertEqual(item?.personName,person);XCTAssertEqual(item?.dueDate,due);XCTAssertEqual(item?.reminderDate,alert)
        XCTAssertEqual(item?.belongsInMemory,purpose == .note);XCTAssertEqual(item?.belongsInToday,purpose != .note)
        XCTAssertFalse(try XCTUnwrap(item).needsClarification)
        XCTAssertEqual(RecurrenceStore.rule(for:id),recurrence)
        let presentation=ItemPresentation.make(for:try XCTUnwrap(item),authorization:LocationAuthorization(status:.denied,isPrecise:true,isRegionMonitoringAvailable:true),now:moment,calendar:calendar)
        XCTAssertNil(presentation.reviewRequirement)
        let saved=XCTAttachment(string:"SAVED: "+String(describing:item?.displayTitle)+"\nPRESENTATION: "+String(describing:presentation));saved.lifetime = .keepAlways;add(saved)
        var retry:CaptureCreationResult?=try await RuntimeExampleTestFixtures.withInterpretation(valid) {
            try await XCTUnwrap(repo).createCaptureResult(text:source,source:.inAppText,createdAt:moment.addingTimeInterval(1),schedulesReminders:false)
        }
        XCTAssertEqual(retry?.isDuplicate,true);XCTAssertEqual(retry?.items.map(\.id),[id])
        item=nil;result=nil;retry=nil;repo=nil;store=nil
        let reopened=try ModelContainer(for:PersistenceController.schema,migrationPlan:SpeakItMigrationPlan.self,configurations:[config])
        let rows=try reopened.mainContext.fetch(FetchDescriptor<CapturedItem>())
        XCTAssertEqual(rows.map(\.id),[id]);XCTAssertEqual(rows.first?.captureSession?.originalTranscription,source)
        XCTAssertEqual(rows.first?.personName,person);XCTAssertEqual(rows.first?.dueDate,due);XCTAssertEqual(rows.first?.reminderDate,alert)
        XCTAssertEqual(RecurrenceStore.rule(for:id),recurrence)
    }
    func testFactSeedRetainsItsPersonInMemory() async throws { try await check("Remember that Sarah likes oat milk",purpose:.note,person:"Sarah") }
    func testShoppingSeedKeepsDateOnlyAndRequestedDefaultAlert() async throws { try await check("Remind me to buy milk tomorrow",purpose:.shopping,due:day(4),alert:day(4,9)) }
    func testRecurringSeedKeepsItsRuleAndRequestedDefaultAlert() async throws { try await check("Remind me every Friday to submit my timesheet",purpose:.task,due:day(7,9),alert:day(7,9),recurrence:.init(frequency:.weekly,weekdays:[6])) }
    func testDescribedDentistSeedKeepsExactTimeWithoutContactIdentity() async throws { try await check("Remind me to call the dentist tomorrow at 2 PM",purpose:.task,due:day(4,14),alert:day(4,14)) }
    func testPickupSeedKeepsLiteralPlaceAndDateWithoutLocationTrigger() async throws { try await check("Pick up rental van at Central Depot on Friday",purpose:.task,due:day(7)) }
    func testReturnSeedKeepsRecipientWithoutInventedOwnership() async throws { try await check("Return the packing blankets to Ivo",purpose:.task) }
    func testUntimedReminderSeedRemainsUsableWithoutInventedClock() async throws { try await check("Remind me to ask Maya about the proposal",purpose:.task,person:"Maya") }
    func testPersonalAllergyFactKeepsItsSubjectThroughIndexedSaveAndReopen() async throws { try await check("Sarah is allergic to peanuts",purpose:.note,person:"Sarah") }
    func testNegativePersonalAllergyFactKeepsItsSubjectThroughIndexedSaveAndReopen() async throws { try await check("Sarah is not allergic to shellfish",purpose:.note,person:"Sarah") }
