#if canImport(FoundationModels)
@available(iOS 26.4, *)
@MainActor
final class RuntimeCurrentBoundaryRepairControls:XCTestCase {
    private var calendar:Calendar { var c=Calendar(identifier:.gregorian);c.timeZone=TimeZone(identifier:"America/Toronto")!;return c }
    private var moment:Date { ISO8601DateFormatter().date(from:"2026-08-03T14:00:00Z")! }
    func testFinalCalendarRepairOwnsAcceptedDayAndHourInsteadOfOriginalFirstClock() throws {
        let source = "Set a reminder for Thursday at four in the afternoon, wait, Friday at four in the afternoon, to collect the frames."
        let certified = try XCTUnwrap(RuntimeCompleteLiteralCertificate.interpret(source, referenceDate: moment, calendar: calendar))
        let final = try XCTUnwrap(certified.items.first)
        let expected = calendar.date(from: DateComponents(year: 2026, month: 8, day: 7, hour: 16))
        XCTAssertEqual(certified.items.count, 1)
        XCTAssertEqual(final.organization.dueDate, expected)
        XCTAssertEqual(final.organization.reminderDate, expected)
        XCTAssertEqual(final.organization.temporalIntent.time, .init(hour: 16, minute: 0))
        XCTAssertTrue(final.wasRepaired)
        XCTAssertEqual(final.rawQuote, source)
        XCTAssertFalse(final.sourceQuote.contains("Thursday"))
        let units = RuntimeIndexedSource(source)
        // Even source-present old date words cannot authorize the final clock.
        // The exact current repair supplies the action and timing, never this
        // deliberately stale model proposal.
        let row = RuntimeFoundationInterpreter.IndexedItem(evidence: Array(units.units.indices),
            purpose: .task, currentMeaning: "Collect the frames Thursday at four in the afternoon",
            directContact: "", needsReview: false)
        let result = try XCTUnwrap(RuntimeFoundationInterpreter.validateIndexed(.init(items: [row]),
            source: source, units: units, referenceDate: moment, calendar: calendar,
            rules: .init(items: [], method: .rules), context: .empty))
        XCTAssertEqual(result.items.first?.organization.dueDate, expected)
        XCTAssertEqual(result.items.first?.organization.reminderDate, expected)
        XCTAssertFalse(result.items.first?.needsReview ?? true)
        XCTAssertFalse(result.items.first?.suggestedTitle?.contains("Thursday") ?? true)
    }
    func testCalendarRepairCertificateCannotDeleteOrBorrowAnIndependentAction() {
        for source in [
            "Call Maya Thursday at four in the afternoon, actually Friday at four in the afternoon call Noor.",
            "Nora said set a reminder for Thursday at four in the afternoon, wait, Friday at four in the afternoon, to collect the frames.",
            "If the frames arrive, set a reminder for Thursday at four in the afternoon, wait, Friday at four in the afternoon, to collect the frames.",
            "Set a reminder for Thursday at four in the afternoon, wait, Friday at four in the afternoon, to collect the frames and mail the parcel."
        ] {
            XCTAssertNil(RuntimeCompleteLiteralCertificate.calendarRepair(source, referenceDate: moment, calendar: calendar), source)
        }
    }
    func testCurrentLiteralFactPurchaseAndDescribedEndpointRemainComplete() throws {
        let source="Remember that Sarah likes oat milk"
        let packet=XCTAttachment(string:"CURRENT ADMISSION: "+source+"\nnominal="+String(RuntimeCurrentNominalProof.read("oat milk"))+"\nliteralSarah="+String(RuntimeRecipientReplacement.literalRecipient("Sarah"))+"\nrecipient="+String(describing:PersonMentionResolver.followUpTarget(in:"Call Sarah"))+"\nunits="+String(describing:RuntimeIndexedSource(source).units.map(\.text))+"\noperations="+String(describing:CaptureOperationDetector.partitionWithOwnership(source).operations)+"\nreading="+String(describing:ThoughtOrganizer.organize(source,referenceDate:moment,calendar:calendar)))
        packet.lifetime = .keepAlways;add(packet)
        let fact=try XCTUnwrap(RuntimeShortSourceCertificate.interpret(source,referenceDate:moment,calendar:calendar)?.items.first)
        XCTAssertEqual(fact.organization.itemType,.note);XCTAssertEqual(fact.organization.personName,"Sarah");XCTAssertEqual(fact.organization.category,.people)
        let purchase=try XCTUnwrap(RuntimeShortSourceCertificate.interpret("Buy milk",referenceDate:moment,calendar:calendar)?.items.first)
        XCTAssertEqual(purchase.organization.itemType,.shopping);XCTAssertNil(purchase.organization.reminderDate)
        let call=try XCTUnwrap(RuntimeShortSourceCertificate.interpret("Remind me to call the dentist tomorrow at 2 PM",referenceDate:moment,calendar:calendar)?.items.first)
        XCTAssertEqual(call.organization.itemType,.task);XCTAssertNil(call.organization.personName);XCTAssertEqual(call.organization.reminderDate,calendar.date(from:DateComponents(year:2026,month:8,day:4,hour:14)))
        for bad in ["Remember that Sarah likes oat milk and buy eggs","Buy milk then call Maya","Call the dentist if the proposal arrives","Call them tomorrow"] { XCTAssertNil(RuntimeShortSourceCertificate.interpret(bad,referenceDate:moment,calendar:calendar),bad) }
    }
    func testContextualNounArgumentCannotHideAnotherMeaning() throws {
        for source in ["Remember that Sarah likes oat milk","Sarah prefers soy milk","Buy milk","Purchase peanut butter","Call the plumber"] {
            let tagged=SentenceContextCache.context(for:source)
            let attachment=XCTAttachment(string:source+"\nTAGGER DISABLED="+String(SentenceContext.taggerDisabledForEvaluation)+"\nFULL="+tagged.tokens.map { $0.text+":"+String(describing:$0.lexicalClass)+":"+String(source.distance(from:source.startIndex,to:$0.range.lowerBound))+".."+String(source.distance(from:source.startIndex,to:$0.range.upperBound)) }.joined(separator:" ")+"\nFRAGMENT="+SentenceContextCache.context(for:source.contains("oat") ? "oat milk" : source.contains("soy") ? "soy milk" : "milk").tokens.map { $0.text+":"+String(describing:$0.lexicalClass) }.joined(separator:" ")+"\nREADING="+String(describing:ThoughtOrganizer.organize(source,referenceDate:moment,calendar:calendar)))
            attachment.lifetime = .keepAlways;add(attachment)
            let observed=RuntimeShortSourceCertificate.interpret(source,referenceDate:moment,calendar:calendar)
            XCTAssertNotNil(observed,source)
            guard let result=observed else { continue }
            XCTAssertEqual(result.items.count,1);XCTAssertEqual(result.items[0].sourceQuote,source)
            XCTAssertFalse(result.items[0].needsReview)
        }
        for source in ["Sarah likes oat milk and buy eggs","Sarah likes milk but call Mom","Sarah prefers milk if Dad asks","Sarah likes milk that expires tomorrow","Sarah likes to milk cows","Buy milk then call Maya","Buy milk for Mom","Buy milk unless Dad has some","Buy milk and milk the cows","Sarah likes Sarah","Buy milk-milk","Buy milk eggs","Buy milk some eggs","Call the plumber if ready","Call the plumber unlock the door","Call the plumber and text Dad"] {
            XCTAssertNil(RuntimeShortSourceCertificate.interpret(source,referenceDate:moment,calendar:calendar),source)
        }
    }
    func testWrongPurposeOrRecipientCannotBorrowCertifiedCurrentFrame() {
        for (source,purpose,contact) in [("Remind me to ask Maya about the proposal",RuntimeFoundationInterpreter.Purpose.task,"the proposal"),("Remember that Sarah likes oat milk",.task,"Sarah"),("Remember that Sarah likes oat milk",.note,"Sarah"),("Remind me to ask Maya about the proposal",.note,""),("Remind me to call the dentist tomorrow at 2 PM",.task,"the dentist")] {
            let units=RuntimeIndexedSource(source)
            let row=RuntimeFoundationInterpreter.IndexedItem(evidence:Array(units.units.indices),purpose:purpose,currentMeaning:"",directContact:contact,needsReview:false)
            XCTAssertNil(RuntimeFoundationInterpreter.validateIndexed(.init(items:[row]),source:source,units:units,referenceDate:moment,calendar:calendar,rules:.init(items:[],method:.rules),context:.empty),source+" / "+contact)
        }
    }
    func testHeldKnowledgeCannotEnterSavedActionCandidates() {
        let fact=CapturedItem(originalTextSegment:"Remember that Sarah likes oat milk",displayTitle:"Sarah likes oat milk",itemType:.unclear,createdAt:moment,needsClarification:true)
        fact.semanticState = .underspecified(.uncertainClauseBoundary)
        XCTAssertTrue(fact.needsClarification)
        XCTAssertTrue(CaptureTargetMatcher.candidates(for:"milk",in:[fact],referenceDate:moment,calendar:calendar).isEmpty)
    }
    func testCompletePersonalFactsKeepExistingSubjectMetadataAcrossIndexedBoundary() throws {
        for source in ["Sarah likes sushi","Sarah doesn't like sushi","Sarah dislikes sushi","Sarah prefers window seats","Sarah does not eat shellfish","Sarah is allergic to peanuts","Sarah is not allergic to shellfish","Sarah has never tried sushi","Sarah lives in Toronto","Sarah doesn't live in Toronto"] {
            let units=RuntimeIndexedSource(source),row=RuntimeFoundationInterpreter.IndexedItem(evidence:Array(units.units.indices),purpose:.note,currentMeaning:"",directContact:"",needsReview:false)
            let result=try XCTUnwrap(RuntimeFoundationInterpreter.validateIndexed(.init(items:[row]),source:source,units:units,referenceDate:moment,calendar:calendar,rules:.init(items:[],method:.rules),context:.empty),source)
            XCTAssertEqual(result.items.first?.organization.personName,"Sarah",source);XCTAssertEqual(result.items.first?.organization.itemType,.note,source)
            XCTAssertEqual(result.items.first?.rawQuote,source);XCTAssertFalse(try XCTUnwrap(result.items.first).needsReview)
        }
    }
}
