#if canImport(FoundationModels)
@available(iOS 26.4, *)
@MainActor
final class RuntimeFirstStageProbeTests:XCTestCase {
    private final class Lines:@unchecked Sendable {
        private let lock=NSLock();private var values:[String]=[]
        func append(_ line:String) { lock.lock();values.append(line);lock.unlock() }
        func text()->String { lock.lock();defer { lock.unlock() };return values.joined(separator:"\n") }
    }
    private func attach(_ label:String,_ value:String) { let a=XCTAttachment(string:label+"\n"+value);a.lifetime = .keepAlways;add(a) }
    private func store()->ModelContainer { try! ModelContainer(for:PersistenceController.schema,migrationPlan:SpeakItMigrationPlan.self,configurations:[ModelConfiguration(isStoredInMemoryOnly:true)]) }
    private func saved(_ items:[CapturedItem],repo:SwiftDataThoughtRepository)->RuntimeCaptureContext {
        .init(savedItems:items.map { .init(id:$0.id.uuidString,title:$0.displayTitle,modifiedAt:$0.lastModifiedAt,originalText:$0.originalTextSegment,itemType:$0.itemType.rawValue,personName:$0.personName,dueDate:$0.dueDate,reminderDate:$0.reminderDate,isReviewed:$0.isReviewed,isArchived:$0.isArchived,isCompleted:$0.completedAt != nil,snapshot:repo.atomicSnapshot($0)) })
    }
    private func before(_ source:String,at:Date,context:RuntimeCaptureContext) {
        let raw=RuleBasedThoughtExtractor.process(source,referenceDate:at,calendar:.autoupdatingCurrent,permitsOperations:true)
        let rules=ThoughtExtractionResult(items:raw.items,operations:raw.operations,method:.rules)
        attach("BEFORE GENERATION",source+"\nREFERENCE="+at.ISO8601Format()+"\nZONE="+Calendar.autoupdatingCurrent.timeZone.identifier+"\nCONFIG="+String(describing:RuntimeExampleTestFixtures.reviewed)+"\nMODEL="+String(describing:SystemLanguageModel.default.availability)+"\nCANCELLED="+String(Task.isCancelled)+"\nTAGGER="+String(describing:SentenceContext.taggerAvailability())+"\nCONTEXT="+String(describing:context)+"\nPARTITION="+String(describing:CaptureOperationDetector.partitionWithOwnership(source))+"\nRULES="+String(describing:rules)+"\nHANDOFF="+String(RuntimeOperationalSourceHandoff.valid(rules,source:source,referenceDate:at,calendar:.autoupdatingCurrent))+"\nLOCAL SAVED PLAN="+String(describing:RuntimeSourceInterpreter.savedChangePlan(source,referenceDate:at,calendar:.autoupdatingCurrent,context:context))+"\nSHORT="+String(describing:RuntimeShortSourceCertificate.interpret(source,referenceDate:at,calendar:.autoupdatingCurrent)))
    }
    private func capture(_ source:String,at:Date,repo:SwiftDataThoughtRepository,sourceType:CaptureSource = .inAppText) async throws -> CaptureCreationResult {
        let log=Lines()
        let result=try await RuntimeExampleLibrary.$developmentObserver.withValue({ log.append($0) }) {
            try await RuntimeFoundationInterpreter.$developmentObserver.withValue({ log.append($0) }) {
                try await repo.createCaptureResult(text:source,source:sourceType,createdAt:at,schedulesReminders:false)
            }
        }
        attach("ACTUAL TRACE",log.text())
        attach("ACTUAL SAVED RESULT",source+"\nSOURCE="+result.session.originalTranscription+"\nOPERATION="+String(describing:result.operationOutcome)+"\nROWS="+result.items.map { String(describing:($0.itemType,$0.displayTitle,$0.needsClarification,$0.belongsInToday,$0.belongsInMemory,$0.personName,$0.dueDate,$0.reminderDate,$0.semanticState,RecurrenceStore.rule(for:$0.id))) }.joined(separator:"\n"))
        XCTAssertEqual(result.session.originalTranscription,source)
        return result
    }
    private func seed(_ source:String) async throws {
        let previous=RecurrenceStore.snapshots();defer { RecurrenceStore.restore(previous) }
        let at=Date.now,container=store(),repo=SwiftDataThoughtRepository(modelContext:container.mainContext,requestsReminderAuthorization:false)
        before(source,at:at,context:.empty)
        let result=try await capture(source,at:at,repo:repo)
        XCTAssertEqual(result.items.count,1,source)
        XCTAssertTrue(result.items.first?.belongsInToday == true,"FIRST FAILURE: supported literal source must be actionable before saved-target matching: "+source)
    }
    func testDentistFridaySeed() async throws { try await seed("Remind me about the dentist on Friday") }
    func testDentistTomorrowSeed() async throws { try await seed("Remind me about the dentist tomorrow") }
    func testPassportFridaySeed() async throws { try await seed("Remind me about the passport on Friday") }
    func testPlumberMondaySeed() async throws { try await seed("Remind me about the plumber on Monday") }
    func testMomFridaySeed() async throws { try await seed("Call Mom on Friday") }
    func testMomFridayReminderSeed() async throws { try await seed("Remind me to call Mom on Friday") }
    func testMomTicketsSeed() async throws { try await seed("Call Mom about the tickets") }
    func testRecurringTimesheetSeed() async throws { try await seed("Remind me every Friday to submit my timesheet") }
    func testPickupSeed() async throws { try await seed("Pick up rental van at Central Depot on Friday") }
    func testReturnSeed() async throws { try await seed("Return the packing blankets to Ivo") }
    func testAAColdVoiceSettledManualContextRetainsAmbiguousOperationIdentity() async throws {
        try await settledManualContext(prewarm:false,sourceType:.inAppVoice)
    }
    func testSettledManualContextRetainsAmbiguousOperationIdentity() async throws {
        try await settledManualContext(prewarm:true,sourceType:.inAppText)
    }
    private func settledManualContext(prewarm:Bool,sourceType:CaptureSource) async throws {
        let at=ISO8601DateFormatter().date(from:"2026-10-05T13:00:00Z")!,due=ISO8601DateFormatter().date(from:"2026-10-06T16:00:00Z")!
        let container=store(),repo=SwiftDataThoughtRepository(modelContext:container.mainContext,requestsReminderAuthorization:false)
        var rows:[CapturedItem]=[]
        for title in ["Clinic visit","Dentist visit"] {
            let session=CaptureSession(originalTranscription:title,createdAt:at)
            let row=CapturedItem(originalTextSegment:title,displayTitle:title,itemType:.task,category:.general,createdAt:at,dueDate:due,captureSession:session)
            container.mainContext.insert(session);container.mainContext.insert(row);rows.append(row)
        }
        try container.mainContext.save()
        let source="I need you to cancel the reminder about the appointment tomorrow. I cannot remember whether I called it the clinic visit or the dentist visit when I saved it. Do not guess between them just because one was created more recently. I can choose the right one when I see the names.\n\nAlso buy a packet of envelopes. That is a clear new task unrelated to the appointment, so it can be saved while the cancellation waits. Keep the cancellation request visible and ask me which saved reminder I mean. None of the appointment reminders should change before I select one."
        if prewarm { before(source,at:at,context:saved(rows,repo:repo)) }
        attach("ACTUAL MATCHABLE SAVED ROWS",String(describing:rows.map { ($0.displayTitle,$0.needsClarification,$0.belongsInToday) }))
        let result=try await capture(source,at:at,repo:repo,sourceType:sourceType)
        if case .ambiguous(operation:.cancel,candidateIDs:let ids)?=result.operationOutcome { XCTAssertEqual(Set(ids),Set(rows.map(\.id))) }
        else { XCTFail("FIRST FAILURE: settled saved rows must retain ambiguous cancellation identity") }
        XCTAssertTrue(rows.allSatisfy { !$0.isCompleted && !$0.isArchived })
        XCTAssertTrue(result.items.contains { $0.itemType == .shopping && !$0.needsClarification && $0.displayTitle.localizedCaseInsensitiveContains("envelopes") })
    }
}
#endif

#if DEBUG
@MainActor
final class RuntimeReferenceConnectionRecoveryTests:XCTestCase {
    private final class Failures:@unchecked Sendable {
        private let lock=NSLock();private var left:Int;private(set) var calls=0
        init(_ count:Int) { left=count }
        func next()->RuntimeReferenceStore.Failure? {
            lock.lock();defer { lock.unlock() };calls += 1
            guard left>0 else { return nil };left -= 1
            return .database(stage:"synthetic-cached-read",code:10,extended:6922)
        }
    }
    private func fixture() throws -> (URL,RuntimeExampleConfiguration) {
        let original=try XCTUnwrap(RuntimeExampleTestFixtures.reviewed)
        let folder=FileManager.default.temporaryDirectory.appendingPathComponent("reference-read-recovery-"+UUID().uuidString)
        try FileManager.default.createDirectory(at:folder,withIntermediateDirectories:true)
        let copy=folder.appendingPathComponent("exact-approved.sqlite")
        try FileManager.default.copyItem(at:original.libraryURL,to:copy)
        let config=RuntimeExampleConfiguration(libraryURL:copy,
            allowProposed:original.allowProposed,retrievalEnabled:true,
            expectedSHA256:original.expectedSHA256,
            excludedBlueprints:original.excludedBlueprints,excludedIDs:original.excludedIDs,
            manualReferenceIDs:original.manualReferenceIDs,usesStagedOutline:original.usesStagedOutline)
        return (folder,config)
    }
    func testCancelledVerificationCannotOpenAnUnverifiedBank() async throws {
        let (folder,config)=try fixture();defer { try? FileManager.default.removeItem(at:folder) }
        let cancelled=Task.detached {
            withUnsafeCurrentTask { $0?.cancel() }
            do {
                _=try RuntimeReferenceStore(url:config.libraryURL,expectedSHA256:config.expectedSHA256,allowUnpinnedPrototype:false)
                return false
            } catch is CancellationError { return true }
            catch { return false }
        }
        let refused=await cancelled.value
        XCTAssertTrue(refused)
    }
    func testCachedReadFailureRevalidatesExactBankAndPreservesSelection() async throws {
        let (folder,config)=try fixture();defer { try? FileManager.default.removeItem(at:folder) }
        let library=RuntimeExampleLibrary(),query="Remind me to call Mom tomorrow"
        let original=try await library.select(query,configuration:config);XCTAssertFalse(original.isEmpty)
        let failures=Failures(1)
        let recovered=try await RuntimeReferenceStore.$testReadFailure.withValue({ failures.next() }) { try await library.select(query,configuration:config) }
        XCTAssertEqual(recovered.map(\.id),original.map(\.id));XCTAssertEqual(failures.calls,2)
        XCTAssertTrue(recovered.allSatisfy { $0.approval.production_eligible })
    }
    func testPersistentReadFailureHasOneRetryAndNextCallCanReopen() async throws {
        let (folder,config)=try fixture();defer { try? FileManager.default.removeItem(at:folder) }
        let library=RuntimeExampleLibrary(),query="Remind me to call Mom tomorrow"
        let original=try await library.select(query,configuration:config)
        let failures=Failures(10)
        do {
            _=try await RuntimeReferenceStore.$testReadFailure.withValue({ failures.next() }) { try await library.select(query,configuration:config) }
            XCTFail("A second I/O failure must not produce a partial successful selection")
        } catch { XCTAssertTrue(RuntimeReferenceStore.requiresFreshConnection(after:error)) }
        XCTAssertEqual(failures.calls,2)
        let reopened=try await library.select(query,configuration:config)
        XCTAssertEqual(reopened.map(\.id),original.map(\.id))
    }
    func testReopenNeverAcceptsChangedBytesUnderOriginalApprovalPin() async throws {
        let (folder,config)=try fixture();defer { try? FileManager.default.removeItem(at:folder) }
        let library=RuntimeExampleLibrary(),query="Remind me to call Mom tomorrow"
        _=try await library.select(query,configuration:config)
        try Data("synthetic changed index".utf8).write(to:config.libraryURL)
        let failures=Failures(1)
        do {
            _=try await RuntimeReferenceStore.$testReadFailure.withValue({ failures.next() }) { try await library.select(query,configuration:config) }
            XCTFail("A cached approval label cannot approve replacement bytes")
        } catch {
            guard case RuntimeReferenceStore.Failure.digestMismatch=error else { return XCTFail("Expected exact bank digest rejection, got "+String(describing:type(of:error))) }
        }
        XCTAssertEqual(failures.calls,1)
    }
}
