    func testCompleteRetainedReferenceCannotHideAdoptedActsIdeasOrSavedChanges() throws {
        let reference = "The spare key is in the blue drawer. Remember that. I do not need a task to move it, I just need to find it when we pack. The torch is with the key, so that detail belongs in the same note."
        let referenceUnits = RuntimeIndexedSource(reference)
        let readings = referenceUnits.units.enumerated().map { index, unit in
            "unit=\(index) text=\(unit.text) reading=\(ActionabilityReader.read(unit.text)) currentIntent=\(RuntimeAccountOwnership.hasCurrentIntent(unit.text)) type=\(ThoughtOrganizer.organize(unit.text).itemType)"
        }
        let trace = XCTAttachment(string:readings.joined(separator:"\n"))
        trace.lifetime = .keepAlways;add(trace)
        XCTAssertTrue(RuntimeFoundationInterpreter.currentRetainedReferenceGroup(reference))
        for suffix in [" Call Mom tomorrow.", " I have promised to return it tomorrow.", " I'll return it tomorrow.", " Remind me at 8 PM to find it.", " Cancel my saved call with Mom.", " I have an idea for a wooden cabinet."] {
            XCTAssertFalse(RuntimeFoundationInterpreter.currentRetainedReferenceGroup(reference+suffix),suffix)
        }
        XCTAssertFalse(RuntimeFoundationInterpreter.currentRetainedReferenceGroup(reference.replacingOccurrences(of:"I do not need a task to move it, I just need to find it when we pack.",with:"I do not need a task to move it, but I will wash the windows tomorrow.")))
        XCTAssertFalse(RuntimeFoundationInterpreter.currentRetainedReferenceGroup(reference.replacingOccurrences(of:"The spare key is in the blue drawer. ",with:"")))
        XCTAssertFalse(RuntimeFoundationInterpreter.currentRetainedReferenceGroup(reference.replacingOccurrences(of:"The spare key is in the blue drawer.",with:"The spare key is in the blue drawer, and call Mom tomorrow.")))
        XCTAssertFalse(RuntimeFoundationInterpreter.currentRetainedReferenceGroup(reference+" I had the key last time, and I have promised to return it tomorrow."))
        let history = " I wasted a ridiculous amount of time looking in the box of cables last time."
        XCTAssertTrue(RuntimeFoundationInterpreter.currentRetainedReferenceGroup(reference+history))
        XCTAssertFalse(RuntimeFoundationInterpreter.currentRetainedReferenceGroup(reference+history.replacingOccurrences(of:"last time.",with:"last time, and I have promised to return it tomorrow.")))
        XCTAssertFalse(RuntimeFoundationInterpreter.currentRetainedReferenceGroup(reference+history.replacingOccurrences(of:"last time.",with:"last time, and call Mom tomorrow.")))
        XCTAssertFalse(RuntimeFoundationInterpreter.currentRetainedReferenceGroup(reference+" I wasted time looking in the box if I will return it tomorrow."))
        XCTAssertFalse(RuntimeFoundationInterpreter.currentRetainedReferenceGroup(reference.replacingOccurrences(of:"Remember that.",with:"Asha said, 'Remember that.'")))
        XCTAssertFalse(RuntimeFoundationInterpreter.currentRetainedReferenceGroup(reference.replacingOccurrences(of:"Remember that.",with:"I have not agreed to remember that.")))
        var calendar = Calendar(identifier:.gregorian);calendar.timeZone = TimeZone(identifier:"America/Toronto")!
        let moment = try XCTUnwrap(calendar.date(from:DateComponents(year:2026,month:10,day:5,hour:9)))
