        XCTAssertFalse(RuntimeFoundationInterpreter.conflictingCurrentClockRows([row],units:indexed,referenceDate:moment,calendar:calendar).contains(0))
        let conflicting = RuntimeIndexedSource("Clean the windows tomorrow at 8 AM. Wash the floor tomorrow at 9 AM.")
        let conflictingRow = RuntimeFoundationInterpreter.IndexedItem(evidence:Array(conflicting.units.indices),purpose:.task,currentMeaning:"",directContact:"",needsReview:false)
        XCTAssertTrue(RuntimeFoundationInterpreter.conflictingCurrentClockRows([conflictingRow],units:conflicting,referenceDate:moment,calendar:calendar).contains(0))
        let idea = "There is also an idea for next time, having a quiet corner where people can step away from the noise. Keep that as an idea rather than adding another job for Friday."
        XCTAssertTrue(RuntimeDiscourseCertificate.retainedIdeaExcludesJobDay(idea,day:CalendarDay(year:2026,month:10,day:9),referenceDate:moment,calendar:calendar))
        XCTAssertFalse(RuntimeDiscourseCertificate.retainedIdeaExcludesJobDay(idea.replacingOccurrences(of:"next time",with:"Monday"),day:CalendarDay(year:2026,month:10,day:9),referenceDate:moment,calendar:calendar))
        for separator in ["\n\n","\r\n\r\n","\r\r"] {
            XCTAssertNil(read(source.replacingOccurrences(of:"windows. Last",with:"windows."+separator+"Last")))
        }
        for changed in [
            source+" Call Dad tomorrow.",source+" I have promised to return the key tomorrow.",
