            source.replacingOccurrences(of:"clean the windows",with:"clean the windows degauss the coil"),
            source.replacingOccurrences(of:"larger type",with:"larger type call Mom tomorrow"),
            source.replacingOccurrences(of:"larger type",with:"larger type degauss the coil"),
            source.replacingOccurrences(of:"autumn event",with:"autumn call Mom tomorrow event"),
            source.replacingOccurrences(of:"Get that cleaned",with:"Get that printed"),
            source.replacingOccurrences(of:"five in the evening",with:"99"),
            source.replacingOccurrences(of:"five in the evening",with:"6:99 PM"),
            source.replacingOccurrences(of:"October 12",with:"October 12 at 8 PM"),
            source.replacingOccurrences(of:"October 12",with:"October 12 if the weather allows"),
            source.replacingOccurrences(of:"people are arriving",with:"I have promised to call Mom tomorrow"),
            source.replacingOccurrences(of:"I need to clean the windows.",with:"Asha said, 'I need to clean the windows.'")
        ] { XCTAssertNil(read(changed),changed) }
    }

