        XCTAssertEqual(retry?.isDuplicate,true)
        XCTAssertEqual(retry?.session.id,captureID)
        XCTAssertEqual(try JSONSerialization.data(withJSONObject:LongCaptureQualificationTests.snapshot(try XCTUnwrap(container).mainContext),options:[.sortedKeys]),before)
        result = nil;retry = nil;repository = nil;container = nil
        let reopened = try ModelContainer(for:PersistenceController.schema,migrationPlan:SpeakItMigrationPlan.self,configurations:[configuration])
        XCTAssertEqual(try JSONSerialization.data(withJSONObject:LongCaptureQualificationTests.snapshot(reopened.mainContext),options:[.sortedKeys]),before)
        let reopenedRows = try reopened.mainContext.fetch(FetchDescriptor<CapturedItem>())
        XCTAssertEqual(reopenedRows.count,6)
        XCTAssertTrue(reopenedRows.allSatisfy { $0.captureSession?.originalTranscription == source && $0.captureSession?.id == captureID })
    }
}
