        return RuntimeFoundationInterpreter.currentClosedJointCallPlan(rows,requestedRows:requested,sharedRows:shared,units:indexed,source:source,referenceDate:moment,calendar:calendar,rules:.init(items:[],method:.rules),context:.empty,modelApprovedCandidates:approved)
