    func testExactReviewedPackingAdaptationsRetainCompleteOriginalAndDecodeBothContracts() async throws {
        let selected=try await rows();XCTAssertEqual(Set(selected.map(\.id)),["SIR1-503251","SIR1-456352"])
        for row in selected {
            let original=try object(row),units=RuntimeIndexedSource(row.input.utterance),atoms=RuntimeFoundationInterpreter.fixedOutlineAtoms(units)
            for contract in [RuntimeFoundationInterpreter.ReferenceOutlineContract.keyed,.ordered,.separated,.fixed,.expressive,.compactExpressive,.compactGuided,.compactComplete,.compactMembership,.compactDeclarations,.compactUnitDeclarations,.objectUnitDeclarations] {
                let text=RuntimeFoundationInterpreter.projectedDemonstration(row,outlineContract:contract)
                let projected=try XCTUnwrap(JSONSerialization.jsonObject(with:Data(text.utf8)) as? [String:Any])
                if contract == .compactExpressive || contract == .compactGuided || contract == .compactComplete {
                    let attachment=XCTAttachment(data:Data(text.utf8),uniformTypeIdentifier:"public.json");attachment.name="exact-reference-compact-expressive-"+row.id;attachment.lifetime = .keepAlways;add(attachment)
                }
                if contract == .ordered {
                    let attachment=XCTAttachment(data:Data(text.utf8),uniformTypeIdentifier:"public.json");attachment.name="exact-reference-ordered-"+row.id;attachment.lifetime = .keepAlways;add(attachment)
                }
                for key in ["input","solution","lifecycle_context"] {
                    XCTAssertEqual(try JSONSerialization.data(withJSONObject:XCTUnwrap(projected[key]),options:.sortedKeys),try JSONSerialization.data(withJSONObject:XCTUnwrap(original[key]),options:.sortedKeys),row.id+key)
                }
                let demonstration=try XCTUnwrap(projected["outline_demonstration"] as? [String:Any],row.id)
                XCTAssertTrue((demonstration["indexed_source"] as? String)?.contains(row.input.utterance.components(separatedBy:". ")[0]) == true)
                XCTAssertEqual(projected["reference_id"] as? String,row.id)
                let namespace="ref"+row.id.dropFirst(5)+"/"
                XCTAssertEqual(demonstration["indexed_source"] as? String,units.units.enumerated().map { "\(namespace)u\($0.offset): \($0.element.text)" }.joined(separator:"\n"))
                let local=try XCTUnwrap(RuntimeFoundationInterpreter.referenceOutlineDemonstration(original,contract:contract))
                if contract == .keyed {
                    XCTAssertEqual(local["ownership_atoms"] as? String,RuntimeFoundationInterpreter.keyedOwnershipPrompt(atoms),"Validate original reference-local graph before namespace rendering")
                    XCTAssertEqual(RuntimeFoundationInterpreter.keyedOwnershipPrompt(atoms),RuntimeFoundationInterpreter.ownershipPrompt(atoms,separated:false,unresolvedOnly:true),"Both exact reviewed records were already all-free: approved packet bytes stay identical")
                    let keys=Set(try XCTUnwrap(demonstration["first_response"] as? [String:Any]).keys)
                    XCTAssertEqual(keys,Set(units.units.indices.map { namespace+"u\($0)" }))
                }
                let foreign=try GeneratedContent(json:String(decoding:JSONSerialization.data(withJSONObject:XCTUnwrap(demonstration["first_response"]),options:.sortedKeys),as:UTF8.self))
                let rejected:[RuntimeFoundationInterpreter.FirstOutlineRow]?
                switch contract {
                case .keyed:rejected=try RuntimeFoundationInterpreter.decodeKeyedFreeOutline(foreign,atoms:atoms)
                case .ordered:rejected=try RuntimeFoundationInterpreter.decodeOrderedFreeOutline(foreign,atoms:atoms)
                case .separated:
                    XCTAssertEqual(demonstration["reference_slot_order"] as? [String],units.units.indices.map { namespace+"u\($0)" })
                    let foreignResponse=try XCTUnwrap(demonstration["first_response"] as? [String:Any])
                    XCTAssertNotNil(foreignResponse["owners"] as? [NSNumber],"Keep declared numeric reference-local positions; do not teach a different field type")
                    XCTAssertEqual(try JSONSerialization.data(withJSONObject:foreignResponse,options:.sortedKeys),try JSONSerialization.data(withJSONObject:XCTUnwrap(local["first_response"]),options:.sortedKeys))
                    // A positional response alone contains no source key. It
                    // can decode on an equal-shaped graph; semantic/current
                    // ownership validation, not namespace alone, remains vital.
                    XCTAssertNotNil(try RuntimeFoundationInterpreter.decodeSeparatedOutline(foreign,atoms:atoms))
                    var invalid=foreignResponse;invalid["owners"]=units.units.indices.map { namespace+"u\($0)" }
                    let foreignPointers=try GeneratedContent(json:String(decoding:JSONSerialization.data(withJSONObject:invalid),as:UTF8.self))
                    rejected=try RuntimeFoundationInterpreter.decodeSeparatedOutline(foreignPointers,atoms:atoms)
                case .fixed:rejected=try RuntimeFoundationInterpreter.decodeFixedOutline(foreign,atoms:atoms)
                case .expressive:rejected=try RuntimeFoundationInterpreter.decodeDynamicOutline(foreign,units:units)
                case .compactExpressive:rejected=try RuntimeFoundationInterpreter.decodeCompactExpressiveOutline(foreign,units:units)
                case .compactGuided:rejected=try RuntimeFoundationInterpreter.decodeCompactGuidedOutline(foreign,units:units)
                case .compactComplete:rejected=try RuntimeFoundationInterpreter.decodeCompactCompleteOutline(foreign,units:units)?.rows
                case .compactMembership:
                    XCTAssertEqual(demonstration["reference_slot_order"] as? [String],units.units.indices.map { namespace+"u\($0)" })
                    // Positional numeric membership can decode on an equal-
                    // shaped source. Full CURRENT meaning validation is vital.
                    XCTAssertNotNil(try RuntimeFoundationInterpreter.decodeCompleteUnitMembership(foreign,units:units))
                    var invalid=try XCTUnwrap(demonstration["first_response"] as? [String:Any])
                    invalid["byUnit"]=units.units.indices.map { [namespace+"u\($0)"] }
                    rejected=try RuntimeFoundationInterpreter.decodeCompleteUnitMembership(GeneratedContent(json:String(decoding:JSONSerialization.data(withJSONObject:invalid),as:UTF8.self)),units:units)?.rows
                case .compactUnitDeclarations:
                    XCTAssertEqual(demonstration["reference_slot_order"] as? [String],units.units.indices.map { namespace+"u\($0)" })
                    // A complete positional shape still grants no CURRENT
                    // semantic permission; unchanged full guards are vital.
