                    var invalid=try XCTUnwrap(demonstration["first_response"] as? [String:Any])
                    invalid["byUnit"]=units.units.indices.map { [namespace+"u\($0):P"] }
                    rejected=try RuntimeFoundationInterpreter.decodeCompactUnitDeclarations(GeneratedContent(json:String(decoding:JSONSerialization.data(withJSONObject:invalid),as:UTF8.self)),units:units)?.rows
                case .objectUnitDeclarations:
                    XCTAssertEqual(demonstration["reference_slot_order"] as? [String],units.units.indices.map { namespace+"u\($0)" })
                    // A complete equal-shaped foreign response has no CURRENT
                    // meaning authority. Full semantic validation is required.
                    XCTAssertNotNil(try RuntimeFoundationInterpreter.decodeObjectUnitDeclarations(foreign,units:units))
                    var invalid=try XCTUnwrap(demonstration["first_response"] as? [String:Any])
