                case .keyed:decoded=try RuntimeFoundationInterpreter.decodeKeyedFreeOutline(content,atoms:atoms)
                case .ordered:decoded=try RuntimeFoundationInterpreter.decodeOrderedFreeOutline(content,atoms:atoms)
                case .separated:decoded=try RuntimeFoundationInterpreter.decodeSeparatedOutline(content,atoms:atoms)
                case .fixed:decoded=try RuntimeFoundationInterpreter.decodeFixedOutline(content,atoms:atoms)
                case .expressive:decoded=try RuntimeFoundationInterpreter.decodeDynamicOutline(content,units:units)
                case .compactExpressive:decoded=try RuntimeFoundationInterpreter.decodeCompactExpressiveOutline(content,units:units)
                case .compactGuided:decoded=try RuntimeFoundationInterpreter.decodeCompactGuidedOutline(content,units:units)
                case .compactComplete:decoded=try RuntimeFoundationInterpreter.decodeCompactCompleteOutline(content,units:units)?.rows
                case .compactMembership:decoded=try RuntimeFoundationInterpreter.decodeCompleteUnitMembership(content,units:units)?.rows
