        ] {
            let units=RuntimeIndexedSource(source)
            let values=groups.indices.map { ["p":purposes[$0],"e":groups[$0].map { "u\($0)" },"r":false,"v":false,"x":[]] as [String:Any] }
            let bytes=try JSONSerialization.data(withJSONObject:["rows":values],options:[.sortedKeys])
