            let plan=try XCTUnwrap(RuntimeFoundationInterpreter.stagedOutlinePlan(decoded.rows,units:units))
            let requested=Set(RuntimeFoundationInterpreter.stagedRewriteRows(decoded.rows,items:plan.items,sharedRows:plan.sharedRows,units:units,referenceDate:moment,calendar:calendar))
            XCTAssertTrue(requested.isEmpty,"Unchanged complete current source need not be echoed or revised")
            let revisions=try XCTUnwrap(RuntimeFoundationInterpreter.decodeInlineCurrentRevisions(decoded.completions,rowCount:decoded.rows.count,requestedRows:requested,sharedRows:plan.sharedRows))
            let completed=try XCTUnwrap(RuntimeFoundationInterpreter.completingStagedPlan(plan.items,revisions:revisions,requestedRows:requested,sharedRows:plan.sharedRows,units:units))
            let result=try XCTUnwrap(RuntimeFoundationInterpreter.validateIndexed(.init(items:completed),source:source,units:units,referenceDate:moment,calendar:calendar,rules:ThoughtExtractionEngine.extractWithRules(source,referenceDate:moment,calendar:calendar),context:.empty))
