    func testInlineReconciliationRejectsMissingPartialForeignAndUnrequestedPayloads() throws {
        let units=RuntimeIndexedSource("Call Mom tomorrow.")
        let row:[String:Any]=["p":"task","e":["u0"],"r":false,"v":false,"x":[]]
        func decode(_ value:[String:Any]) throws -> (rows:[RuntimeFoundationInterpreter.FirstOutlineRow],completions:[[String]])? {
