            var bad=row;bad["x"]=x;XCTAssertNil(try decode(bad))
        }
        var missing=row;missing.removeValue(forKey:"x");XCTAssertNil(try decode(missing))
        var foreign=row;foreign["e"]=["ref456352/u0"];XCTAssertNil(try decode(foreign))
        for value in [["","Call Mom tomorrow","Mom"],["","useCurrentReconciliation",""]] {
            XCTAssertNil(try RuntimeFoundationInterpreter.decodeInlineCurrentRevisions([value],rowCount:1,requestedRows:[],sharedRows:[]),"An unrequested tuple cannot donate generated words or recipient")
        }
