        let wrong=try XCTUnwrap(RuntimeFoundationInterpreter.decodeInlineCurrentRevisions([["","Call Dad tomorrow","Dad"]],rowCount:1,requestedRows:[0],sharedRows:[]))
        let original=try XCTUnwrap(RuntimeFoundationInterpreter.stagedOutlinePlan(try XCTUnwrap(decode(row)).rows,units:units))
        let completed=try XCTUnwrap(RuntimeFoundationInterpreter.completingStagedPlan(original.items,revisions:wrong,requestedRows:[0],sharedRows:[],units:units))
