    private func compactUnitContent(_ content:GeneratedContent) throws -> GeneratedContent {
        var root=try XCTUnwrap(JSONSerialization.jsonObject(with:Data(content.jsonString.utf8)) as? [String:Any])
        let membership=try XCTUnwrap(root["byUnit"] as? [[[String:Any]]])
        let codes=["task":"T","shopping":"S","packing":"P","inventory":"I","note":"N","idea":"D","question":"Q","review":"R"]
        root["byUnit"]=try membership.map { try $0.map { member -> String in
            let group=try XCTUnwrap(member["g"] as? Int),value=try XCTUnwrap(member["p"] as? String)
            let review=value.hasSuffix("?"),purpose=review ? String(value.dropLast()) : value
            return "\(group):"+(try XCTUnwrap(codes[purpose]))+(review ? "?" : "")
        } }
        let edits=try XCTUnwrap(root["edits"] as? [[String:Any]])
        root["edits"]=try edits.map { edit -> [String:Any] in
            var mapped=edit;mapped["g"]=String(try XCTUnwrap(edit["g"] as? Int));return mapped
        }
        return try GeneratedContent(json:String(decoding:JSONSerialization.data(withJSONObject:root,options:.sortedKeys),as:UTF8.self))
    }
