    func testCompactUnitDeclarationPlainSchemaRetainsStrictDecoderAndOneInlineContract() throws {
        let source=RuntimeIndexedSource("Call Mom. Keep the prism as a fact.")
        let schema=try XCTUnwrap(RuntimeFoundationInterpreter.compactUnitDeclarationSchema(source))
        let encoded=try JSONSerialization.jsonObject(with:JSONEncoder().encode(schema))
        func patterns(_ value:Any)->[String] {
            if let object=value as? [String:Any] { return object.flatMap { key,value in key == "pattern" ? ((value as? String).map { [$0] } ?? []) : patterns(value) } }
            if let array=value as? [Any] { return array.flatMap(patterns) }
            return []
        }
        XCTAssertTrue(patterns(encoded).isEmpty,"Plain string transport after actual guided calls threw opaque SDK errors; strict app decoding remains required")
        let instruction=RuntimeFoundationInterpreter.compactUnitDeclarationInstructions("legacy-envelope-sentinel requiresRewrite needsReview next phase")
        for legacy in ["legacy-envelope-sentinel","requiresRewrite","next phase","exact supplied current unit identifiers"] { XCTAssertFalse(instruction.contains(legacy),legacy) }
        for required in ["COMPLETE indexed CURRENT source","EVERY CURRENT unit","no intention-count cap","EVERY shared group and corrected actionable group","complete effective CURRENT meaning","literal direct contact","outline_demonstration.first_response","Never guess a saved target","actual user context are authoritative"] { XCTAssertTrue(instruction.contains(required),required) }
        // Guides are advisory until an actual SDK response is observed. The
        // same strict decoder must still reject a malformed guided response.
        let malformed=try GeneratedContent(json:#"{"byUnit":[["0"],["1"]],"edits":[]}"#)
        XCTAssertNil(try RuntimeFoundationInterpreter.decodeCompactUnitDeclarations(malformed,units:source))
    }
    func testObservedNestedSDKErrorMetadataRetainsActualChildrenWithoutInventingCause() throws {
        let leaf=NSError(domain:"SyntheticLeaf",code:901,userInfo:[NSLocalizedDescriptionKey:"diagnostic leaf",NSDebugDescriptionErrorKey:"actual nested metadata","unrelatedValue":"must not export this arbitrary value"])
        let middle=NSError(domain:"FoundationModels.LanguageModelError",code:-1,userInfo:[NSUnderlyingErrorKey:leaf])
        let outer=NSError(domain:"FoundationModels.LanguageModelError",code:-1,userInfo:[NSMultipleUnderlyingErrorsKey:[middle,leaf]])
        let text=RuntimeFoundationInterpreter.observedErrorTreeJSON(outer)
        let root=try XCTUnwrap(JSONSerialization.jsonObject(with:Data(text.utf8)) as? [String:Any])
        let nodes=try XCTUnwrap(root["nodes"] as? [[String:Any]])
        XCTAssertTrue(nodes.contains { $0["path"] as? String == "root.multiple[0].underlying" && $0["domain"] as? String == "SyntheticLeaf" && $0["code"] as? Int == 901 })
        XCTAssertEqual(root["truncated"] as? Bool,false);XCTAssertFalse(text.contains("must not export"))
        XCTAssertEqual(RuntimeFoundationInterpreter.observedFailureReason(outer),"unclassified-sdk-error","Domain/code alone never proves unsupported guides, cancellation or capacity failure")
        let summary=RuntimeFoundationInterpreter.observedErrorIdentity(outer)
        XCTAssertTrue(summary.contains("errorTreeJSON="));XCTAssertTrue(summary.contains("actual nested metadata"))
        var deep=leaf
        for _ in 0..<10 { deep=NSError(domain:"SyntheticWrapper",code:0,userInfo:[NSUnderlyingErrorKey:deep]) }
        let bounded=try XCTUnwrap(JSONSerialization.jsonObject(with:Data(RuntimeFoundationInterpreter.observedErrorTreeJSON(deep).utf8)) as? [String:Any])
        XCTAssertEqual(bounded["truncated"] as? Bool,true)
        XCTAssertLessThanOrEqual((bounded["nodes"] as? [[String:Any]])?.count ?? 99,16)
    }
    private func objectUnitContent(_ content:GeneratedContent) throws -> GeneratedContent {
        var root=try XCTUnwrap(JSONSerialization.jsonObject(with:Data(content.jsonString.utf8)) as? [String:Any])
        let membership=try XCTUnwrap(root["byUnit"] as? [[String]])
        root["byUnit"]=try membership.map { declarations in try declarations.map { value -> [String:String] in
            let parts=value.split(separator:":",omittingEmptySubsequences:false).map(String.init)
            XCTAssertEqual(parts.count,2);guard parts.count == 2 else { throw NSError(domain:"SyntheticObjectFixture",code:1) }
            return ["g":parts[0],"p":parts[1]]
        } }
        return try GeneratedContent(json:String(decoding:JSONSerialization.data(withJSONObject:root,options:.sortedKeys),as:UTF8.self))
    }
    private func objectDeclarationContent(_ content:GeneratedContent) throws -> GeneratedContent {
        try objectUnitContent(compactUnitContent(content))
    }
