    func testObjectUnitDeclarationsDiscardUnusedForeignPackingAndRejectRequiredForeignMeaning() throws {
        let source=IntentConsolidationTests.trainIdeaLongCapture,units=RuntimeIndexedSource(source)
        let groups=[Array(0...6),Array(7...9),Array(10...14),Array(15...17),Array(18...20),Array(21...23),Array(24...25)]
        let purposes=["task","task","packing","idea","note","task","task"]
        let copied="pack 4 packs of paper folders and 5 packs of envelopes for Idris and Gareth to share."
        for word in ["Idris","Gareth","paper folders","envelopes"] { XCTAssertFalse(source.contains(word)) }
        let values=groups.indices.map { ["p":purposes[$0],"e":groups[$0].map { "u\($0)" },"r":false,"v":false,"x":$0 == 2 ? ["",copied,""] : []] as [String:Any] }
        let content=try objectDeclarationContent(declarationContent(["rows":values],unitCount:units.units.count))
        let decoded=try XCTUnwrap(RuntimeFoundationInterpreter.decodeObjectUnitDeclarations(content,units:units))
        let plan=try XCTUnwrap(RuntimeFoundationInterpreter.stagedOutlinePlan(decoded.rows,units:units))
        let requested=Set(RuntimeFoundationInterpreter.stagedRewriteRows(decoded.rows,items:plan.items,sharedRows:plan.sharedRows,units:units,referenceDate:moment,calendar:calendar))
        let revisions=try XCTUnwrap(RuntimeFoundationInterpreter.decodeInlineCurrentRevisions(decoded.completions,rowCount:decoded.rows.count,requestedRows:requested,sharedRows:plan.sharedRows.intersection(requested)))
        let complete=try XCTUnwrap(RuntimeFoundationInterpreter.completingStagedPlan(plan.items,revisions:revisions,requestedRows:requested,sharedRows:plan.sharedRows.intersection(requested),units:units))
        XCTAssertEqual(complete[2].currentMeaning,copied,"Foreign optional rewrite really reaches the validation boundary")
        let result=try XCTUnwrap(RuntimeFoundationInterpreter.validateIndexed(.init(items:complete),source:source,units:units,referenceDate:moment,calendar:calendar,rules:ThoughtExtractionEngine.extractWithRules(source,referenceDate:moment,calendar:calendar),context:.empty))
        var unchanged=complete;unchanged[2].currentMeaning=""
        let expected=try XCTUnwrap(RuntimeFoundationInterpreter.validateIndexed(.init(items:unchanged),source:source,units:units,referenceDate:moment,calendar:calendar,rules:ThoughtExtractionEngine.extractWithRules(source,referenceDate:moment,calendar:calendar),context:.empty))
        XCTAssertEqual(result,expected,"An optional rewrite of an unchanged whole row is discarded; EVERY output field must equal the checked CURRENT-only result")
        XCTAssertEqual(result.items.count,7)
        for item in result.items {
            for word in ["Idris","Gareth","paper folders","envelopes"] {
                XCTAssertFalse(item.sourceQuote.contains(word));XCTAssertFalse(item.rawQuote.contains(word));XCTAssertFalse(item.analysisText.contains(word));XCTAssertFalse(item.suggestedTitle?.contains(word) == true);XCTAssertFalse(item.organization.personName?.contains(word) == true)
            }
        }
        // Once CURRENT correction makes reconciliation mandatory, the same
        // copied meaning cannot be discarded as an optional whole-row edit.
        // Keep the otherwise complete graph and every original source unit.
        let correctedSource=source+" Actually pack the short charging cable, not the long cable."
        let correctedUnits=RuntimeIndexedSource(correctedSource)
        XCTAssertEqual(correctedUnits.units.count,units.units.count+1)
        var required=complete;required[2].evidence.append(correctedUnits.units.count-1)
        XCTAssertEqual(Set(required.flatMap(\.evidence)),Set(correctedUnits.units.indices))
        XCTAssertNil(RuntimeFoundationInterpreter.validateIndexed(.init(items:required),source:correctedSource,units:correctedUnits,referenceDate:moment,calendar:calendar,rules:ThoughtExtractionEngine.extractWithRules(correctedSource,referenceDate:moment,calendar:calendar),context:.empty),"Required reconciliation must reject OTHER-capture facts through unchanged full meaning guards")
    }
