    private final class ValidationTrace:@unchecked Sendable {
        private let lock=NSLock();private var lines:[String]=[]
        func append(_ line:String) { lock.lock();defer { lock.unlock() };lines.append(line) }
        func text()->String { lock.lock();defer { lock.unlock() };return lines.joined(separator:"\n") }
    }
