    func testCurrentComponentDiscoveryFindsExistingCompleteFramesBeforePartitionWithoutForeignFacts() throws {
        let now=try XCTUnwrap(ISO8601DateFormatter().date(from:"2026-10-05T13:00:00Z"))
        let train=RuntimeIndexedSource(IntentConsolidationTests.trainIdeaLongCapture)
        let cues=RuntimeFoundationInterpreter.currentComponentCues(train,referenceDate:now,calendar:calendar)
        XCTAssertTrue(cues.contains(.init(evidence:Array(0...6),reading:"action-before-booked-event")))
        XCTAssertTrue(cues.contains(.init(evidence:Array(15...17),reading:"retained-possible-project")))
        XCTAssertTrue(cues.contains { $0.evidence == [7] && ["communication-matrix","direct-action-matrix"].contains($0.reading) },"Embedded ask is part of the communication matrix, not a separately manufactured root")
        XCTAssertTrue(cues.allSatisfy { !$0.evidence.isEmpty && $0.evidence.allSatisfy(train.units.indices.contains) })
