        XCTAssertTrue(gardenCues.contains { $0.reading == "retained-possible-project" && $0.evidence.count == 3 })
        let a=RuntimeFoundationInterpreter.fixedOutlineAtoms(garden,referenceDate:now,calendar:calendar)
        XCTAssertTrue(RuntimeFoundationInterpreter.prefersComponentPartition(gardenCues,atoms:a,usesFixedOwnership:true))
        XCTAssertFalse(RuntimeFoundationInterpreter.prefersComponentPartition(gardenCues,atoms:a,usesFixedOwnership:false))
        XCTAssertFalse(RuntimeFoundationInterpreter.prefersComponentPartition([],atoms:a,usesFixedOwnership:true))
    }
