    func testKnownPartialLinkChainsDeclineBeforeAnotherCallButCrossPartTargetsRemainProvisional() throws {
        let a=atoms(26),keys=Array(a.prefix(13).map(\.key))
        var good=Dictionary(uniqueKeysWithValues:keys.map { ($0,"task") });good["u0"]="note";good["u1"]="context:u0"
        XCTAssertTrue(RuntimeFoundationInterpreter.currentKeySliceHasCanonicalKnownTargets(good))
        var chain=good;chain["u3"]="context:u1";XCTAssertFalse(RuntimeFoundationInterpreter.currentKeySliceHasCanonicalKnownTargets(chain))
        var correction=good;correction["u3"]="correction:u1";XCTAssertFalse(RuntimeFoundationInterpreter.currentKeySliceHasCanonicalKnownTargets(correction))
        var later=good;later["u12"]="context:u15";XCTAssertTrue(RuntimeFoundationInterpreter.currentKeySliceHasCanonicalKnownTargets(later),"Unknown other-part owner is checked only after full join")
        let observed=["packing","context:u0","correction:u0","context:u1","correction:u1","context:u2","correction:u2","context:u3","correction:u3","context:u4","correction:u4","context:u5","correction:u5"]
        let partial=try XCTUnwrap(RuntimeFoundationInterpreter.decodeCurrentKeySlice(content(Dictionary(uniqueKeysWithValues:zip(keys,observed))),keys:keys,atoms:a))
        XCTAssertFalse(RuntimeFoundationInterpreter.currentKeySliceHasCanonicalKnownTargets(partial),"Observed110 menu walk cannot consume a second generation or authorize a partial effect")
        XCTAssertNotNil(try RuntimeFoundationInterpreter.literalCurrentKeySliceSchema(keys,atoms:a))
        XCTAssertNil(try RuntimeFoundationInterpreter.literalCurrentKeySliceSchema(keys+["u13"],atoms:a))
    }

