#if DEBUG && canImport(FoundationModels)
/// Synthetic current-source proposals; no model, retrieval or real user store.
@MainActor
@available(iOS 26.4, *)
final class RuntimeCaptureRetentionIntentTests: XCTestCase {
    private var calendar: Calendar {
        var value = Calendar(identifier: .gregorian)
        value.timeZone = TimeZone(identifier: "America/Toronto")!
        return value
    }
    private var reference: Date {
        calendar.date(from: DateComponents(year: 2026, month: 8, day: 3, hour: 10))!
    }
    private func validate(_ source: String, purpose: RuntimeFoundationInterpreter.Purpose,
                          anchor: String = "") -> ThoughtExtractionResult? {
        let units = RuntimeIndexedSource(source)
        let proposal = RuntimeFoundationInterpreter.IndexedProposal(items: [.init(
            evidence: Array(units.units.indices), anchor: anchor, purpose: purpose,
            currentMeaning: anchor, directContact: "", needsReview: false)])
        return RuntimeFoundationInterpreter.validateIndexed(proposal, source: source,
            units: units, referenceDate: reference, calendar: calendar,
            rules: ThoughtExtractionEngine.extractWithRules(source,
                referenceDate: reference, calendar: calendar), context: .empty)
    }

    func testFrontedClockAbbreviationKeepsItsCalendarAndReminderInOneCurrentIntent() throws {
        let cases: [(String, Int, Int, Int, Int)] = [
            ("At 3:20 p.m. on August 8, remind me to check in online for my flight.", 8, 8, 15, 20),
            ("At 10:15 a.m. on September 9, remind me to print the return label.", 9, 9, 10, 15),
            ("Around 4 p.m. on October 12, remind me to collect the parcel.", 10, 12, 16, 0),
            ("At 2:05 P.M. on December 4, remind me to water the plant.", 12, 4, 14, 5),
            ("At 3:20 PM. on August 8, remind me to check in online for my flight.", 8, 8, 15, 20),
            ("At 3:20p.m. on August 8, remind me to check in online for my flight.", 8, 8, 15, 20),
            ("Before I forget, at 3:20 p.m. on August 8, remind me to check in online for my flight.", 8, 8, 15, 20),
            ("Before we forget,  at 10:15 a.m.  on September 9, remind me to print the return label.", 9, 9, 10, 15)
        ]
        for (source, month, day, hour, minute) in cases {
            let units = RuntimeIndexedSource(source)
            XCTAssertEqual(units.units.count, 1, source)
            XCTAssertEqual(units.units.first?.text, source, source)
            let result = try XCTUnwrap(validate(source, purpose: .task), source)
            XCTAssertEqual(result.items.count, 1, source)
            let item = try XCTUnwrap(result.items.first, source)
            let expected = calendar.date(from: DateComponents(year: 2026, month: month,
                day: day, hour: hour, minute: minute))!
            XCTAssertEqual(item.sourceQuote, source, source)
            XCTAssertEqual(item.rawQuote, source, source)
            XCTAssertEqual(item.organization.itemType, .task, source)
            XCTAssertFalse(item.needsReview, source)
            XCTAssertEqual(item.organization.dueDate, expected, source)
            XCTAssertEqual(item.organization.reminderDate, expected, source)
            XCTAssertEqual(item.organization.reminderDelivery, .notification, source)
            XCTAssertTrue(result.operations.isEmpty, source)
        }
    }

    func testClockAbbreviationDoesNotJoinIndependentCommandsOrWrittenBoundaries() {
        let cases = [
            "At 3:20 p.m. Call Mom tomorrow.",
            "At 3:20 p.m. Remind me on August 8 to check in online.",
            "The train left at 3:20 p.m. On August 8, call Mom.",
            "At 3:20 p.m. on August 8, remind me to leave before 4 p.m. Call Mom tomorrow.",
            "At 3:20 p.m. on August 8, remind me to leave before 4 p.m. On September 2, call Mom.",
            "At 3:20 p.m.; on August 8, remind me to check in online.",
            "At 3:20 p.m.\non August 8, remind me to check in online.",
            "At 3:20 p.m. on the balcony, call Mom tomorrow."
        ]
        for source in cases {
            let units = RuntimeIndexedSource(source)
            XCTAssertEqual(units.units.count, 2, source)
            XCTAssertTrue(units.units.first?.text.contains("3:20 p.m.") == true, source)
            XCTAssertFalse(units.units.last?.text.contains("3:20 p.m.") == true, source)
        }
    }

    func testCalendarClockBoundaryProofUsesOnlyItsCurrentSentence() throws {
        let second = "At 3:20 p.m. on August 8, remind me to check in online for my flight."
        let source = "Buy apples. " + second
        let units = RuntimeIndexedSource(source)
        XCTAssertEqual(units.units.map(\.text), ["Buy apples.", second])
        let rows: [RuntimeFoundationInterpreter.IndexedItem] = [
            .init(evidence: [0], anchor: "", purpose: .shopping, currentMeaning: "", directContact: "", needsReview: false),
            .init(evidence: [1], anchor: "", purpose: .task, currentMeaning: "", directContact: "", needsReview: false)
        ]
        let result = try XCTUnwrap(RuntimeFoundationInterpreter.validateIndexed(.init(items: rows),
            source: source, units: units, referenceDate: reference, calendar: calendar,
            rules: ThoughtExtractionEngine.extractWithRules(source, referenceDate: reference, calendar: calendar),
            context: .empty))
        XCTAssertEqual(result.items.count, 2)
        let reminder = try XCTUnwrap(result.items.first { $0.organization.reminderDelivery == .notification })
        XCTAssertEqual(reminder.rawQuote, second)
        XCTAssertEqual(reminder.organization.reminderDate,
            calendar.date(from: DateComponents(year: 2026, month: 8, day: 8, hour: 15, minute: 20)))
        XCTAssertTrue(result.operations.isEmpty)
    }

    func testSeparateCalendarClocksAndLeadingWhitespaceKeepTheirOwnUnits() {
        let first = "At 3:20 p.m. on August 8, remind me to check in online!"
        let second = "Around 9 a.m. on September 2, remind me to collect the parcel?"
        for source in [first + " " + second, " \t" + first + "\t " + second] {
            XCTAssertEqual(RuntimeIndexedSource(source).units.map(\.text), [first, second], source)
        }
    }

    func testCheckedPastReportKeepsOneMemoryThroughEngineSaveRetryAndReopen() async throws {
        let source = "A poster said, bring your own chair. That was for an event that has already ended."
        let checked = try XCTUnwrap(validate(source, purpose: .note))
        let engine = await RuntimeExampleTestFixtures.withInterpretation(checked) {
            await ThoughtExtractionEngine.extract(source, referenceDate: reference, calendar: calendar)
        }
        XCTAssertEqual(engine.items, checked.items)
        XCTAssertTrue(engine.operations.isEmpty)

        let directory = FileManager.default.temporaryDirectory
            .appendingPathComponent("SpeakItPastReport-" + UUID().uuidString, isDirectory: true)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: directory) }
        let configuration = ModelConfiguration(url: directory.appendingPathComponent("capture.store"),
                                                cloudKitDatabase: .none)
        var rowID: UUID?, captureID: UUID?
        do {
            let container = try ModelContainer(for: PersistenceController.schema,
                migrationPlan: SpeakItMigrationPlan.self, configurations: [configuration])
            let repository = SwiftDataThoughtRepository(modelContext: container.mainContext,
                requestsReminderAuthorization: false)
            let saved = try await RuntimeExampleTestFixtures.withInterpretation(checked) {
                try await repository.createCaptureResult(text: source, source: .inAppText,
                    createdAt: reference, schedulesReminders: false)
            }
            XCTAssertEqual(saved.session.originalTranscription, source)
            XCTAssertEqual(saved.items.count, 1)
            let item = try XCTUnwrap(saved.items.first)
            rowID = item.id; captureID = saved.session.id
            XCTAssertEqual(item.itemType, .note)
            XCTAssertTrue(item.belongsInMemory)
            XCTAssertFalse(item.belongsInToday)
            XCTAssertFalse(item.needsClarification)
            XCTAssertEqual(item.originalTextSegment, source)
            XCTAssertNil(item.dueDate)
            XCTAssertNil(item.reminderDate)
            let retried = try await RuntimeExampleTestFixtures.withInterpretation(checked) {
                try await repository.createCaptureResult(text: source, source: .inAppText,
                    createdAt: reference, schedulesReminders: false)
            }
            XCTAssertEqual(retried.session.id, captureID)
            XCTAssertEqual(retried.items.map(\.id), [item.id])
        }
        let reopened = try ModelContainer(for: PersistenceController.schema,
            migrationPlan: SpeakItMigrationPlan.self, configurations: [configuration])
        let rows = try reopened.mainContext.fetch(FetchDescriptor<CapturedItem>())
        XCTAssertEqual(rows.count, 1)
        let item = try XCTUnwrap(rows.first)
        XCTAssertEqual(item.id, rowID)
        XCTAssertEqual(item.captureSession?.id, captureID)
        XCTAssertEqual(item.captureSession?.originalTranscription, source)
        XCTAssertEqual(item.originalTextSegment, source)
        XCTAssertEqual(item.itemType, .note)
        XCTAssertTrue(item.belongsInMemory)
        XCTAssertFalse(item.belongsInToday)
        XCTAssertFalse(item.needsClarification)
        XCTAssertNil(item.dueDate)
        XCTAssertNil(item.reminderDate)
    }

    func testIndexedRetentionPurposeCannotBecomeCurrentWorkEvenWithActionAnchor() throws {
        let cases: [(String, RuntimeFoundationInterpreter.Purpose, ItemType)] = [
            ("I want to save the phrase 'quiet courts, bright lamps' as a design thought.", .idea, .idea),
            ("I need to keep the window layout as an idea.", .idea, .idea),
            ("I would like to retain the phrase ‘call Noor tomorrow’ as a Memory.", .note, .note),
            ("We want to save the seating pattern as reference.", .note, .note),
            ("Save that cooking guidance.", .note, .note)
        ]
        for (source, purpose, kind) in cases {
            let accepted = try XCTUnwrap(validate(source, purpose: purpose), source)
            XCTAssertEqual(accepted.items.count, 1, source)
            let row = try XCTUnwrap(accepted.items.first, source)
            XCTAssertEqual(row.organization.itemType, kind, source)
            XCTAssertEqual(row.rawQuote, source, source)
            XCTAssertEqual(row.sourceQuote, source, source)
            XCTAssertFalse(row.needsReview, source)
            XCTAssertNil(row.organization.dueDate, source)
            XCTAssertNil(row.organization.reminderDate, source)
            XCTAssertTrue(accepted.operations.isEmpty, source)
            for anchor in ["", source, ActionabilityReader.actionBody(source)] {
                XCTAssertNil(validate(source, purpose: .task, anchor: anchor), source)
            }
        }
    }

    func testProvedRetentionCannotWaiveSeparateCurrentActions() {
        let retention = "I want to save the phrase 'quiet courts' as a design thought."
        for action in ["I need to mail the parcel tomorrow.", "Arrange the chairs.",
                       "Remind me to rinse the tray at 5 PM."] {
            for source in [retention + " " + action,
                           action + " " + retention,
                           String(retention.dropLast()) + ", and " + action.lowercased()] {
                XCTAssertNil(ActionabilityReader.explicitCaptureRetentionKind(source), source)
                for purpose in [RuntimeFoundationInterpreter.Purpose.note, .idea] {
                    XCTAssertNil(validate(source, purpose: purpose), source)
                }
            }
        }
        // An external label cannot certify the earlier independently framed
        // action. These deny the whole proof, even when a later noun says note.
        for source in [
            "I want to save the phrase 'quiet courts' and I will mail the parcel as a note.",
            "Save the phrase 'quiet courts', arrange the chairs as a note.",
            "Save that cooking guidance and rinse the tray as a note."
        ] {
            XCTAssertNil(ActionabilityReader.explicitCaptureRetentionKind(source), source)
            for purpose in [RuntimeFoundationInterpreter.Purpose.note, .idea] {
                XCTAssertNil(validate(source, purpose: purpose), source)
            }
        }
    }

    func testKnowledgeCapturePointerDoesNotCreateASavingTaskOrAnAlert() throws {
        let source = "The rice is cool. Save that cooking guidance."
        let actual = ThoughtExtractionEngine.extractWithRules(source,
            referenceDate: reference, calendar: calendar)
        XCTAssertFalse(actual.items.isEmpty)
        XCTAssertTrue(actual.items.allSatisfy { !$0.organization.itemType.isActionable }, source)
        XCTAssertFalse(actual.items.contains(where: \.needsReview), source)
        XCTAssertTrue(actual.operations.isEmpty, source)
        XCTAssertTrue(actual.items.allSatisfy { $0.organization.dueDate == nil
            && $0.organization.reminderDate == nil }, source)
        XCTAssertTrue(SourceUnitLedger(source).unownedMeaningfulIDs(claimed:
            actual.items.reduce(into: Set<Int>()) { $0.formUnion($1.sourceUnitIDs) }).isEmpty, source)
    }

    func testRetainedQuoteAndIndependentSavedRevisionHaveSeparateOriginalOwnership() throws {
        let prefix = "I want to save the phrase 'Cancel my saved call with Noor' as an idea."
        let source = prefix + " Change my saved dentist reminder so I call Noor instead of Maya."
        let actual = ThoughtExtractionEngine.extractWithRules(source,
            referenceDate: reference, calendar: calendar)
        let memory = try XCTUnwrap(actual.items.first, source)
        XCTAssertEqual(actual.items.count, 1, source)
        XCTAssertEqual(memory.organization.itemType, .idea, source)
        XCTAssertFalse(memory.needsReview, source)
        // Existing clause shaping excludes the external sentence delimiter
        // from a split raw span. The spoken quotation and repaired source
        // remain exact; the full capture below still owns that delimiter.
        XCTAssertEqual(memory.rawQuote, String(prefix.dropLast()), source)
        XCTAssertEqual(memory.sourceQuote, prefix, source)
        XCTAssertEqual(actual.operations.count, 1, source)
        let revision = try XCTUnwrap(actual.operations.first, source)
        XCTAssertEqual(revision.operation, .revise, source)
        XCTAssertEqual(revision.target, "dentist", source)
        let field = try XCTUnwrap(revision.savedFieldRevision, source)
        XCTAssertEqual(field.itemWords, "dentist", source)
        XCTAssertEqual(field.requestSentence,
            "Change my saved dentist reminder so I call Noor instead of Maya.", source)
        XCTAssertEqual(field.field, .person, source)
        XCTAssertEqual(field.statedOldValue, "Maya", source)
        XCTAssertEqual(field.newValue, "Noor", source)
        XCTAssertEqual(revision.sourceQuote, field.requestSentence, source)
        XCTAssertEqual(revision.sourceUnitIDs,
            SourceUnitLedger(source).ids(in: field.requestRange), source)
        XCTAssertTrue(revision.sourceUnitIDs.isDisjoint(with: memory.sourceUnitIDs), source)
        let ledger = SourceUnitLedger(source)
        let prefixEnd = source.index(source.startIndex, offsetBy: prefix.count)
        XCTAssertEqual(memory.sourceUnitIDs, ledger.ids(in: source.startIndex..<prefixEnd), source)
        XCTAssertTrue(ledger.unownedMeaningfulIDs(claimed:
            memory.sourceUnitIDs.union(revision.sourceUnitIDs)).isEmpty, source)
    }

    func testRetainedQuoteSurvivesResolvedNamedRecipientRevisionWithoutTouchingOtherSavedCalls() throws {
        let container = try ModelContainer(for: PersistenceController.schema,
            migrationPlan: SpeakItMigrationPlan.self,
            configurations: [ModelConfiguration(isStoredInMemoryOnly: true)])
        let repository = SwiftDataThoughtRepository(modelContext: container.mainContext,
            requestsReminderAuthorization: false, permitsOnDeviceIntelligence: false)
        let fixtureZone = calendar.timeZone
        func parsing<T>(_ body: () throws -> T) rethrows -> T {
            let previousZone = NSTimeZone.default
            NSTimeZone.default = fixtureZone
            defer { NSTimeZone.default = previousZone }
            return try body()
        }
        func snapshot(_ id: UUID) throws -> [String: Any] {
            try XCTUnwrap(LongCaptureQualificationTests.snapshot(container.mainContext)
                .first { $0["id"] as? String == id.uuidString })
        }
        func encoded(_ value: [String: Any]) throws -> Data {
            try JSONSerialization.data(withJSONObject: value, options: [.sortedKeys])
        }

        let now = Date.now
        // Pin only synchronous repository parsing. No notification-center
        // assertion or delivery runs under the fixture's time zone.
        let dentist = try parsing {
            try repository.createCapture(text: "Call Maya about the dentist tomorrow at 9 AM.",
                source: .inAppText, createdAt: now.addingTimeInterval(-3600), schedulesReminder: false)
        }
        let other = try parsing {
            try repository.createCapture(text: "Call Noor about the library pickup tomorrow at 11 AM.",
                source: .inAppText, createdAt: now.addingTimeInterval(-3600), schedulesReminder: false)
        }
        let dentistID = dentist.id, otherID = other.id
        XCTAssertEqual(dentist.personName, "Maya")
        XCTAssertTrue(dentist.belongsInToday)
        XCTAssertFalse(dentist.needsClarification)
        XCTAssertNotNil(dentist.dueDate)
        XCTAssertNotNil(dentist.temporalIntent?.time)
        XCTAssertEqual(other.personName, "Noor")
        XCTAssertTrue(other.belongsInToday)
        XCTAssertFalse(other.needsClarification)
        let dentistOriginalCapture = try XCTUnwrap(dentist.captureSession).originalTranscription
        let otherOriginalCapture = try XCTUnwrap(other.captureSession).originalTranscription
        let beforeDentist = try snapshot(dentistID)
        let beforeOther = try encoded(snapshot(otherID))
        let oldTitle = dentist.displayTitle
        let expectedTitle = oldTitle.replacingOccurrences(of: "Maya", with: "Noor")
        XCTAssertNotEqual(expectedTitle, oldTitle)

        let prefix = "I want to save the phrase 'Cancel my saved call with Noor' as an idea."
        let request = "Change my saved dentist reminder so I call Noor instead of Maya."
        let source = prefix + " " + request
        let memory = try parsing {
            try repository.createCapture(text: source, source: .inAppText,
                createdAt: now.addingTimeInterval(60), schedulesReminder: false)
        }
        let session = try XCTUnwrap(memory.captureSession)
        XCTAssertEqual(session.originalTranscription, source)
        XCTAssertEqual(session.processingStatus, .complete)
        XCTAssertEqual(session.items.count, 1)
        XCTAssertEqual(session.items.first?.id, memory.id)
        XCTAssertEqual(memory.itemType, .idea)
        XCTAssertTrue(memory.belongsInMemory)
        XCTAssertFalse(memory.belongsInToday)
        XCTAssertFalse(memory.needsClarification)
        XCTAssertEqual(memory.originalTextSegment, prefix)
        XCTAssertNil(memory.dueDate)
        XCTAssertNil(memory.reminderDate)
        XCTAssertNil(PendingOperationStore.record(for: memory.id))

        let rows = try container.mainContext.fetch(FetchDescriptor<CapturedItem>())
        XCTAssertEqual(rows.count, 3)
        XCTAssertEqual(Set(rows.map(\.id)), Set([dentistID, otherID, memory.id]))
        XCTAssertEqual(rows.filter { $0.belongsInToday }.count, 2)
        let revised = try XCTUnwrap(rows.first { $0.id == dentistID })
        XCTAssertEqual(revised.personName, "Noor")
        XCTAssertEqual(revised.displayTitle, expectedTitle)
        XCTAssertFalse(revised.isArchived)
        XCTAssertFalse(revised.isCompleted)
        XCTAssertEqual(revised.captureSession?.originalTranscription, dentistOriginalCapture)
        XCTAssertEqual(rows.first { $0.id == otherID }?.captureSession?.originalTranscription,
                       otherOriginalCapture)
        XCTAssertEqual(try encoded(snapshot(otherID)), beforeOther)
        var preservedBefore = beforeDentist
        var preservedAfter = try snapshot(dentistID)
        // The recipient's display copy and edit timestamp accompany this
        // one field revision. Every other stored field must remain exact.
        for key in ["personName", "displayTitle", "lastModifiedAt"] {
            preservedBefore.removeValue(forKey: key)
            preservedAfter.removeValue(forKey: key)
        }
        XCTAssertEqual(try encoded(preservedAfter), try encoded(preservedBefore))

        let state = try XCTUnwrap(CaptureOperationState.read(from: session.operationStateData))
        XCTAssertEqual(state.phase, .performed)
        XCTAssertEqual(state.operation, .revise)
        XCTAssertEqual(state.targetID, dentistID)
        XCTAssertEqual(state.sourceQuote, request)
        XCTAssertEqual(state.oldFieldValue, "Maya")
        XCTAssertEqual(state.newFieldValue, "Noor")
        XCTAssertEqual(state.oldTitle, oldTitle)
        XCTAssertEqual(state.newTitle, expectedTitle)
    }

    func testSavedRecipientRevisionPreservesSameSentenceIndependentActionAndReminder() throws {
        let prefix = "I want to save the phrase 'quiet courts' as an idea."
        let request = "Change my saved dentist reminder so I call Noor instead of Maya"
        for tail in ["mail the parcel.", "remind me to mail the parcel tomorrow at 5 PM."] {
            let container = try ModelContainer(for: PersistenceController.schema,
                migrationPlan: SpeakItMigrationPlan.self,
                configurations: [ModelConfiguration(isStoredInMemoryOnly: true)])
            let repository = SwiftDataThoughtRepository(modelContext: container.mainContext,
                requestsReminderAuthorization: false, permitsOnDeviceIntelligence: false)
            func parsing<T>(_ body: () throws -> T) rethrows -> T {
                let previousZone = NSTimeZone.default
                NSTimeZone.default = calendar.timeZone
                defer { NSTimeZone.default = previousZone }
                return try body()
            }
            func snapshot(_ id: UUID) throws -> Data {
                let row = try XCTUnwrap(LongCaptureQualificationTests.snapshot(container.mainContext)
                    .first { $0["id"] as? String == id.uuidString })
                return try JSONSerialization.data(withJSONObject: row, options: [.sortedKeys])
            }
            let now = Date.now
            let dentist = try parsing {
                try repository.createCapture(text: "Call Maya about the dentist tomorrow at 9 AM.",
                    source: .inAppText, createdAt: now.addingTimeInterval(-3600), schedulesReminder: false)
            }
            let other = try parsing {
                try repository.createCapture(text: "Call Noor about the library pickup tomorrow at 11 AM.",
                    source: .inAppText, createdAt: now.addingTimeInterval(-3600), schedulesReminder: false)
            }
            let dentistID = dentist.id, otherID = other.id
            let beforeOther = try snapshot(otherID)
            let oldTitle = dentist.displayTitle
            let oldDue = dentist.dueDate, oldReminder = dentist.reminderDate
            let originalDentist = try XCTUnwrap(dentist.captureSession).originalTranscription
            let source = prefix + " " + request + ", and " + tail
            let field = try XCTUnwrap(SavedFieldRevision.read(source), source)
            XCTAssertFalse(field.requestSentence.localizedCaseInsensitiveContains("mail the parcel"), source)
            let first = try parsing {
                try repository.createCapture(text: source, source: .inAppText,
                    createdAt: now.addingTimeInterval(60), schedulesReminder: false)
            }
            let session = try XCTUnwrap(first.captureSession)
            XCTAssertEqual(session.originalTranscription, source)
            XCTAssertEqual(session.processingStatus, .complete)
            XCTAssertEqual(session.items.count, 2, source)
            let memory = try XCTUnwrap(session.items.first { $0.belongsInMemory }, source)
            let action = try XCTUnwrap(session.items.first { $0.belongsInToday }, source)
            XCTAssertEqual(memory.itemType, .idea, source)
            XCTAssertFalse(memory.needsClarification, source)
            XCTAssertEqual(memory.originalTextSegment, prefix, source)
            XCTAssertFalse(action.needsClarification, source)
            XCTAssertTrue(action.originalTextSegment.localizedCaseInsensitiveContains("mail the parcel"), source)
            XCTAssertFalse(action.originalTextSegment.localizedCaseInsensitiveContains("saved dentist"), source)
            if tail.hasPrefix("remind me") {
                let due = try XCTUnwrap(action.dueDate, source)
                XCTAssertEqual(calendar.component(.hour, from: due), 17, source)
                XCTAssertNotNil(action.reminderDate, source)
            } else {
                XCTAssertNil(action.dueDate, source)
                XCTAssertNil(action.reminderDate, source)
            }
            let rows = try container.mainContext.fetch(FetchDescriptor<CapturedItem>())
            XCTAssertEqual(rows.count, 4, source)
            let revised = try XCTUnwrap(rows.first { $0.id == dentistID }, source)
            XCTAssertEqual(revised.personName, "Noor", source)
            XCTAssertEqual(revised.displayTitle, oldTitle.replacingOccurrences(of: "Maya", with: "Noor"), source)
            XCTAssertEqual(revised.dueDate, oldDue, source)
            XCTAssertEqual(revised.reminderDate, oldReminder, source)
            XCTAssertEqual(revised.captureSession?.originalTranscription, originalDentist, source)
            XCTAssertEqual(try snapshot(otherID), beforeOther, source)
            let state = try XCTUnwrap(CaptureOperationState.read(from: session.operationStateData), source)
            XCTAssertEqual(state.phase, .performed, source)
            XCTAssertEqual(state.targetID, dentistID, source)
            XCTAssertEqual(state.sourceQuote, field.requestSentence, source)
        }
    }

