    func testSavedFieldRevisionUsesNamedTargetBeforeIndependentRetainedContext() throws {
        let request = "Change my saved dentist reminder so I call Noor instead of Maya."
        for context in [
            "I want to save the phrase 'Cancel my saved call with Noor' as an idea.",
            "I would like to keep the phrase \"Change my saved theatre booking\" as a Memory.",
            "The office has green walls. The hallway has a blue carpet."
        ] {
            let source = context + " " + request
            let field = try XCTUnwrap(SavedFieldRevision.read(source), source)
            XCTAssertEqual(field.itemWords, "dentist", source)
            XCTAssertEqual(field.requestSentence, request, source)
            XCTAssertEqual(field.field, .person, source)
            XCTAssertEqual(field.statedOldValue, "Maya", source)
            XCTAssertEqual(field.newValue, "Noor", source)
            XCTAssertEqual(String(source[field.requestRange])
                .trimmingCharacters(in: .whitespacesAndNewlines), request, source)
        }
        // An explicitly anaphoric request still uses the independently stated
        // saved-item context when its own target words supply no name.
        let introduction = "The vegetable box reminder from yesterday was assigned to Maya."
        let anaphoric = "Change that same item so I call Noor instead of Maya."
        let source = introduction + " " + anaphoric
        let field = try XCTUnwrap(SavedFieldRevision.read(source), source)
        XCTAssertEqual(field.itemWords, introduction, source)
        XCTAssertEqual(field.requestSentence, anaphoric, source)
        XCTAssertEqual(field.statedOldValue, "Maya", source)
        XCTAssertEqual(field.newValue, "Noor", source)
    }

